INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C1','kor',6,2,'u3',1,'주장 · 이유 · 근거 — 주장은 어떤 주제에 대한 자신의 의견을 드러내는 말, 이유는 왜 그렇게 주장하는지를 설명하는 말, 근거는 이유를 뒷받침하는 자료나 사실이며, 셋의 자리를 갈라야 평가할 수 있다',ARRAY['[6국01-02][6국02-03]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C2','kor',6,2,'u3',1,'비판적으로 보고 듣기 — 무조건 믿거나 무조건 의심하는 것이 아니라 옳고 그른지를 제대로 따져 보는 것(맞는 것은 맞다고, 부족한 것은 부족하다고 까닭을 들어 말하기), 따져 보지 않으면 사실이 아닌 것을 믿고 옮기게 되고, 따져 보면 믿을 만한 정보를 골라 쓰고 내 생각과 견주어 볼 수 있다',ARRAY['[6국01-02][6국02-03]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C3','kor',6,2,'u3',2,'주장하는 말을 듣는 방법 — 말은 되감을 수 없으므로 메모하며 듣기(이유·근거 적기)·요약하며 듣기(주장·이유·근거로 간추리기)·견주며 듣기(내 생각과 견주기)를 하고, 지나치게 감정에 호소하지는 않는지 태도까지 살핀다',ARRAY['[6국01-02]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C4','kor',6,2,'u3',2,'주장의 타당성 판단 기준 — 주장이 가치 있고 중요한지는 문제를 해결하거나 생활하는 데 도움이 되는가, 실천 가능한가(언제 무엇을 할지 정해져 있는가)로 판단한다',ARRAY['[6국01-02]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C5','kor',6,2,'u3',2,'이유의 타당성 판단 기준 — 이유가 주장과 관련 있는가, 많은 사람이 받아들일 만한가(혼자만의 느낌·사정이 아닌가) 두 물음을 함께 통과해야 한다',ARRAY['[6국01-02]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C6','kor',6,2,'u3',2,'근거의 타당성 판단 기준과 근거 자료 — 근거가 이유와 관련 있는가, 객관적인 사실이나 정보인가로 판단하고, 근거 자료의 유형(표·그래프·면담 자료·사례)을 알며, 근거가 사실인지 책·기사·기관 누리집·어른께 여쭈어 확인하고 출처가 믿을 만한지 다시 살핀다',ARRAY['[6국01-02]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C7','kor',6,2,'u3',4,'주장하는 말의 내용을 평가하며 듣기 — 타당한 점을 먼저 찾고 보완할 점을 찾으며(평가는 이긴 쪽을 고르는 일이 아니라 더 나아지게 하는 일), 평가 기준표에 ◎·○·△로 판단하고 그렇게 판단한 까닭(어떤 기준을 더 무겁게 보았는지)을 말한다',ARRAY['[6국01-02]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C8','kor',6,2,'u3',4,'객관적인 근거와 출처 밝히기 — 누가 보아도 그러한 객관적인 근거와 혼자만의 느낌·짐작인 주관적인 말을 가르고, 주관적인 근거는 더 힘주어 말하거나 감정에 호소하지 않고 확인할 수 있는 자료로 고치며, 가져다 쓴 자료는 어디에서 나왔는지 밝힌다',ARRAY['[6국01-02]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C9','kor',6,2,'u3',7,'영상의 주장 파악하기 — 알려 주는 영상·보여 주는 영상·주장하는 영상을 가르고, 영상은 주장을 직접 말하지 않는 경우가 많으므로 제목(그렇게 정한 까닭)·제시한 자료(무엇을 보여 주려고 넣었는지)·강조하는 장면이나 표현(되풀이·음악이 멈추는 자리·글자만 남는 화면)을 합쳐 주장을 한 문장으로 세운다',ARRAY['[6국02-03]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C10','kor',6,2,'u3',7,'강조와 타당성 가르기 — 음악·되풀이 자막 같은 강조는 만든 사람이 무엇을 가장 하고 싶은 말로 여기는지 알려 주는 실마리일 뿐 그 말이 타당한지·사실인지는 알려 주지 못하며, 주장을 찾는 일과 타당한지 따지는 일은 다르다(끝까지 한 번 보고 두 번째에 적으며 보기)',ARRAY['[6국02-03]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C11','kor',6,2,'u3',9,'카드 뉴스 내용을 평가하며 보기 — 카드 뉴스는 첫 장의 제목과 굵은 글씨에 주장이, 가운데 장에 이유와 근거가 한 쌍씩 놓이며, 짧을수록 빠진 것이 잘 보이지 않으므로 이유마다 「그래서 왜?」, 근거마다 「이게 그 이유를 보여 주나?」를 물으며 같은 세 기준으로 평가한다',ARRAY['[6국02-03]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C12','kor',6,2,'u3',9,'약한 자리 짚기와 부분 평가 — 잘 세워진 자리를 먼저 세고, 문제의 규모(많다·늘고 있다)만 말하는 이유나 이유를 보여 주지 않고 해결 방안(제도)을 말하는 근거를 약한 자리로 짚되, 하나가 약하다고 주장 전체가 틀린 것은 아니며 고칠 자리를 짚어 준다',ARRAY['[6국02-03]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C13','kor',6,2,'u3',12,'영상을 골라 타당성을 평가하고 설명하기 — 여러 사람이 함께 생각해 볼 만한 주제를 정해 구체적인 말로 찾고, 자세히 보기·알아낸 것 말하기·생각하기·궁금해하기 차례로 보며, 주장이 없는 영상은 평가표에서 가려내고, 내용의 타당성을 먼저·표현은 그다음에 보고, 제목·주장·이유·근거·판단·까닭을 넣어 설명한다',ARRAY['[6국02-03]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C14','kor',6,2,'u3',12,'받침 ㅎ의 발음 — 받침 ㅎ 뒤에 ㄱ·ㄷ·ㅈ이 오면 합쳐서 ㅋ·ㅌ·ㅊ으로(넣고[너코]·빨갛다[빨가타]·그렇지[그러치]), ㄴ이 오면 ㄴ으로(넣는[넌는]), 모음이 오면 ㅎ 소리를 내지 않는다(좋아[조아])(기초 다지기)',ARRAY['기초 다지기 — 받침 ㅎ 발음(단원 성취기준 표기 없음)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C15','kor',6,2,'u3',2,'「실수에서 배워요」 내용 알기 — 실수는 조심하지 않아서 잘못하는 행동 · 플레밍이 포도상 구균을 기르던 접시를 실수로 배양기 밖에 두고 휴가를 떠났다가 미생물이 줄어든 것을 보고 페니실린을 발견함 · 주장(실수를 배움의 기회로 삼을 수 있다)·이유(실수에서 문제점을 찾으려 노력하면 고칠 점을 발견할 수 있다)·근거(플레밍 사례)',ARRAY['[6국01-02]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C16','kor',6,2,'u3',4,'「용기초등학교 어린이 생각 발표회」 내용 알기 — 목적(주장을 알려 학생들을 설득)·대상(용기초등학교 학생들)·급식 반찬 구성 바꾸기 · 윤정(채소 위주 음식 날 늘리기 / 지구 온난화 / 소나무 열다섯 그루 기사) · 현우(질 좋은 고기반찬 / 고기반찬으로만 단백질 / 충치 연구 결과)',ARRAY['[6국01-02]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C17','kor',6,2,'u3',4,'「용기초등학교 어린이 생각 발표회」 낱말 알기 — 섭취하다(생물체가 양분 따위를 몸속에 빨아들이다) · 제공하다(무엇을 내주거나 갖다 바치다) · 대항하다(굽히거나 지지 않으려고 맞서서 버티거나 항거하다) · 가속하다(점점 속도를 더하다)',ARRAY['[6국01-02]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C18','kor',6,2,'u3',7,'「낭독의 재발견」으로 영상의 주장 파악하기 — 제목(오래된 방법이라 여긴 낭독의 효과를 다시 알림) · 자료(캐나다 사람들을 대상으로 한 설문과 뇌파 측정 연구 — 집중력이 떨어지고 있다는 결과) · 강조(굵은 글자 입·몸·마음) → 주장: 낭독은 글의 내용을 잘 이해하는 데 도움을 준다',ARRAY['[6국02-03]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C19','kor',6,2,'u3',7,'「나를 성장시키는 기록법」으로 영상의 주장 파악하기 — 그대로 받아 적기만 하면 기억하지 못함 · 정약용 수사차록법(베껴 쓰되 자신의 생각을 덧붙임) · 이순신 「난중일기」 · 천재들의 기록 습관 · 「적자! 생존」(잘 적는 사람이 성장) · 음악이 멈추고 자막 강조 → 주장: 생각을 함께 적은 기록은 자신을 성장시킨다',ARRAY['[6국02-03]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C20','kor',6,2,'u3',9,'「무분별한 혐오·차별 표현은 이제 그만!」 내용 알기 — 혐오·차별 표현의 뜻과 나타나는 모습(말·글·행동·복장·상징물) · 주장(멈추어야 한다) · 이유 셋(부정적 인식 강화 / 많은 사람이 겪음 / 존엄성 침해·사회적 갈등) · 근거 셋(살색 → 살구색 / 경험 여부 그래프 / 각국의 규제 사례)',ARRAY['[6국02-03]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C21','kor',6,2,'u3',9,'카드 뉴스 낱말 알기 — 강화(세력이나 힘을 더 강하고 튼튼하게 함) · 규제(규칙이나 규정에 의하여 일정한 한도를 정하거나 정한 한도를 넘지 못하게 막음) · 조장(바람직하지 않은 일을 더 심해지도록 부추김) · 침해(침범하여 해를 끼침) · 선동하다 · 초래하다',ARRAY['[6국02-03]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C22','kor',6,2,'u3',12,'「비규격 농산물을 소비하자」 타당성 평가(마무리) — 주장은 가치 있고 실천할 수 있음 · 이유 ①(저렴)·②(환경 보호)는 타당, ③(모양이 예쁜 농산물)은 주장과 관련 없음 · 근거 ①(한국소비자원 조사)·②(농림축산식품부 조사)는 타당, ③은 주관적 · 이유 더하기(농가 지원)',ARRAY['[6국02-03]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X01','kor',6,'u3',ARRAY['K6-2-u3-C1','K6-2-u3-C9','K6-2-u3-C11']::text[],'주장 · 이유 · 근거의 자리를 섞는다(이유를 주장으로, 주장을 근거로 여기는 등)','하자는 말? 왜 그런지? 받쳐 주는 자료?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X02','kor',6,'u3',ARRAY['K6-2-u3-C2','K6-2-u3-C7','K6-2-u3-C12']::text[],'비판적으로 보기를 무조건 의심하기·말한 사람 깎아내리기·어딘가 잘못이 있다고 미리 정하기로 여긴다','따져 보기 = 맞는 것은 맞다고, 부족한 것은 부족하다고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X03','kor',6,'u3',ARRAY['K6-2-u3-C2','K6-2-u3-C11']::text[],'말을 잘하거나 짧고 보기 좋거나 많이 퍼진 주장을 따져 보지 않고 그대로 믿는다','「이 말, 무엇이 받쳐 주지?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X04','kor',6,'u3',ARRAY['K6-2-u3-C3']::text[],'메모하거나 간추리지 않고 들어 평가할 거리를 남기지 못하거나, 결론을 미리 정하고 목소리·말솜씨로 판단한다','말은 되감을 수 없어요 — 적고 간추리며 듣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X05','kor',6,'u3',ARRAY['K6-2-u3-C4']::text[],'말만 크고 무엇부터 할지 알 수 없는 주장도 가치 있다고 여긴다(실천 가능성을 보지 않음)','언제 · 무엇을 할지 정해져 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X06','kor',6,'u3',ARRAY['K6-2-u3-C5']::text[],'주장과 관련 없는 이유를 받아들이거나, 관련 있는 이유를 관련 없다고 여긴다','이 이유가 주장이 말하는 일과 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X07','kor',6,'u3',ARRAY['K6-2-u3-C5']::text[],'혼자만의 느낌이나 사정인 이유도 많은 사람이 받아들일 만한 이유로 여긴다','나만 그런가, 많은 사람이 고개를 끄덕일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X08','kor',6,'u3',ARRAY['K6-2-u3-C6','K6-2-u3-C8']::text[],'말한 사람의 느낌이나 짐작을 근거로 여기거나, 근거는 길고 많을수록 좋다고 여긴다','누가 보아도 그러한가, 확인할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X09','kor',6,'u3',ARRAY['K6-2-u3-C6']::text[],'근거가 사실인지 확인하지 않거나, 검색해 나온 것·많이 퍼진 글을 출처 확인 없이 믿는다','책 · 기사 · 기관 누리집 · 어른께 — 그리고 출처 한 번 더') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X10','kor',6,'u3',ARRAY['K6-2-u3-C6']::text[],'근거 자료의 유형(표·그래프·면담 자료·사례)과 그 쓰임을 헷갈린다','나란히 견주기? 흐름? 사람의 말? 있었던 일?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X11','kor',6,'u3',ARRAY['K6-2-u3-C7','K6-2-u3-C12']::text[],'평가를 흠부터 찾는 일이나 이긴 쪽을 고르는 일로 여겨 타당한 점을 먼저 찾지 않는다','살릴 것 먼저, 고칠 것은 그다음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X12','kor',6,'u3',ARRAY['K6-2-u3-C7','K6-2-u3-C13']::text[],'까닭 없이 표시만 하거나 「그냥 그렇게 느꼈다」로 판단하고, 판단이 갈릴 때 어떤 기준을 무겁게 보았는지 말하지 않는다','「나는 ○○을 가장 무겁게 보았어. 그래서 …」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X13','kor',6,'u3',ARRAY['K6-2-u3-C8']::text[],'가져다 쓴 자료의 출처를 밝히지 않아 확인할 길을 막거나 남의 자료를 내 것처럼 쓴다','어디에서 · 언제 나온 자료인지 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X14','kor',6,'u3',ARRAY['K6-2-u3-C8']::text[],'약한 근거를 고칠 때 더 힘주어 되풀이하거나 듣는 사람의 감정에 호소한다','느낌을 키우지 말고 확인할 수 있는 자료로 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X15','kor',6,'u3',ARRAY['K6-2-u3-C9','K6-2-u3-C13']::text[],'영상의 주장을 한 요소(제목만·분위기만)로 정하거나, 주장과 관계없는 것(길이·벽 색)을 실마리로 삼거나, 알려 주는 영상과 주장하는 영상을 헷갈린다','제목 + 자료 + 강조 → 한 문장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X16','kor',6,'u3',ARRAY['K6-2-u3-C9']::text[],'영상도 주장을 문장으로 직접 말할 것이라 여겨, 직접 말하지 않으면 주장이 없다고 본다','「그래서 나더러 무엇을 하라는 걸까?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X17','kor',6,'u3',ARRAY['K6-2-u3-C10']::text[],'음악이 커지고 자막이 되풀이될수록, 곧 강조가 셀수록 주장이 옳거나 사실이라고 여긴다','강조는 「무엇을」 말하고 싶은지만 알려 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X18','kor',6,'u3',ARRAY['K6-2-u3-C12']::text[],'문제의 규모(많다·늘고 있다)만으로 문제가 되는 까닭을 말했다고 여긴다','많아서 → 무엇이 어떻게 나빠지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X19','kor',6,'u3',ARRAY['K6-2-u3-C12']::text[],'문제에 대한 해결 방안(제도·규칙·대책)을 그 문제가 있다는 이유를 보여 주는 근거로 여긴다','이 근거는 문제를 보여 주나, 그 뒤의 일을 말하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X20','kor',6,'u3',ARRAY['K6-2-u3-C12']::text[],'이유나 근거 하나가 약하면 주장 전체가 틀렸다거나 믿을 수 없다고 여긴다','약한 자리는 고칠 자리 — 주장 전체와 가르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X21','kor',6,'u3',ARRAY['K6-2-u3-C13']::text[],'주장이 없는 영상도 평가표로 재거나, 음악·편집·말투 같은 표현과 재미로 타당성을 판단한다','먼저 평가할 수 있는 영상인지 · 내용 먼저, 표현은 그다음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X22','kor',6,'u3',ARRAY['K6-2-u3-C13']::text[],'영상을 찾고 보는 차례를 지키지 않는다(두루뭉술하거나 자극적인 검색어, 본 것과 짐작한 것을 섞기)','구체적인 말로 찾기 · 본 것 → 생각 → 물음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X23','kor',6,'u3',ARRAY['K6-2-u3-C14']::text[],'받침 ㅎ을 뒤 소리와 상관없이 그대로 소리 내거나, ㄱ·ㄷ·ㅈ과 합치지 않고 ㄷ으로 끊어 소리 낸다','ㄱ·ㄷ·ㅈ → ㅋ·ㅌ·ㅊ · ㄴ → ㄴ · 모음 → 소리 없음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X24','kor',6,'u3',ARRAY['K6-2-u3-C5','K6-2-u3-C16']::text[],'이유가 주장과 관련만 있으면, 지나치게 단정한 까닭(「고기반찬으로만」)이나 주장의 참뜻과 어긋난 까닭(「벌금을 내야 하기 때문」)이어도 많은 사람이 받아들일 만하다고 여긴다','관련 있나? 그리고 많은 사람이 고개를 끄덕일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X25','kor',6,'u3',ARRAY['K6-2-u3-C6','K6-2-u3-C16']::text[],'근거가 이유와 같은 화제(단백질·나무 등)를 다루기만 하면 이유를 적절하게 뒷받침한다고 여긴다','이 근거가 「그 이유」가 맞다는 것을 보여 주나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X26','kor',6,'u3',ARRAY['K6-2-u3-C2','K6-2-u3-C13']::text[],'주장을 받아들이거나 사람을 뽑는 기준, 다룰 주제를 내가 좋아하는 것인지·나와 가까운 사람인지 같은 취향과 친분으로 정한다','좋고 싫음 말고, 주장이 타당한지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X27','kor',6,'u3',ARRAY['K6-2-u3-C13']::text[],'영상 평가 댓글에서 주장·판단·까닭 같은 조건을 빠뜨리거나, 타당하지 않은 부분을 정중하게 확인 요청하지 않고 비방하거나 혐오하는 말로 쓴다','주장 → 판단 → 까닭 → 정중한 확인 요청') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X28','kor',6,'u3',ARRAY['K6-2-u3-C4','K6-2-u3-C5','K6-2-u3-C6']::text[],'주장의 길이·듣는 사람의 기분·근거 종류의 수처럼 타당성과 관계없는 것을 타당성 판단 기준으로 삼는다','가치·관련·받아들일 만함·객관 — 이것만 기준') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X29','kor',6,'u3',ARRAY['K6-2-u3-C17','K6-2-u3-C21']::text[],'제재에 나온 낱말(섭취하다·제공하다·대항하다·가속하다·강화·규제·조장·침해)의 뜻을 서로 엇갈리게 안다','뜻풀이를 문장에 넣어 읽어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X30','kor',6,'u3',ARRAY['K6-2-u3-C11','K6-2-u3-C20']::text[],'카드 뉴스를 보고 만든 질문에서 내용을 확인하는 질문(카드 뉴스 안에 답이 있음)과 친구들의 생각을 묻는 질문을 가르지 못한다','답이 카드 안에 있나, 사람마다 다른가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_basic#1','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',1,'mc','auto','생각 열기에서 「누군가의 주장을 받아들이기 전에 한 번 더 생각해야 하는 까닭」으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X26','K6-2-u3-X02','K6-2-u3-X03']::text[],false,'{"seq":1,"concept":"K6-2-u3-C2","difficulty":1,"kind":"mc","stem":"생각 열기에서 「누군가의 주장을 받아들이기 전에 한 번 더 생각해야 하는 까닭」으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"그 내용에 사실이 아닌 내용이 담겨 있을 수 있기 때문","correct":true},{"t":"발표하는 사람이 우리 학교 학생이기 때문","mis":"K6-2-u3-X26"},{"t":"누군가의 주장은 모두 틀린 말이기 때문","mis":"K6-2-u3-X02"},{"t":"말을 잘하는 사람의 주장만 믿으면 되기 때문","mis":"K6-2-u3-X03"}],"explanation":["주장하는 말에는 사실이 아닌 내용이 섞여 있을 수 있어요.","그대로 믿었다가 손해를 볼 수도 있어요.","그래서 받아들이기 전에 한 번 더 따져 보아요."],"asset":{"type":"passage","lines":["[그림] 용기초등학교 어린이 생각 발표회 — 발표자가 말한다.","발표자: “우리 학교 운동장에 쓰레기통을 많이 설치하면","운동장이 깨끗해질 것입니다.”","듣는 친구 1: 발표자가 주장하는 말의 이유와 근거는 무엇일까?","듣는 친구 2: 저 주장을 믿어도 될까?","듣는 친구 3: 어떤 점을 기준으로 타당성을 판단하면 좋을까?"],"numbered":false,"title":"생각 열기 — 『국어』 115쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_basic#2','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',1,'sa','auto','생각 열기에서 듣는 친구가 「발표자가 주장하는 말의 이유와 (    )은/는 무엇일까?」 하고 생각했어요. 빈칸에 들어갈 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C1","difficulty":1,"kind":"sa","stem":"생각 열기에서 듣는 친구가 「발표자가 주장하는 말의 이유와 (    )은/는 무엇일까?」 하고 생각했어요. 빈칸에 들어갈 두 글자 낱말을 쓰세요.","answer":["근거"],"explanation":["발표자는 쓰레기통을 많이 설치하자고 주장했어요.","왜 그런지 밝히는 말이 이유예요.","이유를 뒷받침하는 자료나 사실이 근거예요."],"asset":{"type":"passage","lines":["[그림] 용기초등학교 어린이 생각 발표회 — 발표자가 말한다.","발표자: “우리 학교 운동장에 쓰레기통을 많이 설치하면","운동장이 깨끗해질 것입니다.”","듣는 친구 1: 발표자가 주장하는 말의 이유와 근거는 무엇일까?","듣는 친구 2: 저 주장을 믿어도 될까?","듣는 친구 3: 어떤 점을 기준으로 타당성을 판단하면 좋을까?"],"numbered":false,"title":"생각 열기 — 『국어』 115쪽"},"mis":"K6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_basic#3','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',1,'mc','auto','전교 회장 선거 만화에서 나연이가 1번 후보를 뽑으려는 기준은 무엇인가요?',ARRAY['K6-2-u3-X26','K6-2-u3-X03','K6-2-u3-X04']::text[],false,'{"seq":3,"concept":"K6-2-u3-C2","difficulty":1,"kind":"mc","stem":"전교 회장 선거 만화에서 나연이가 1번 후보를 뽑으려는 기준은 무엇인가요?","options":[{"t":"자신이 좋아하는 놀이를 하게 해 주는지","correct":true},{"t":"후보가 같은 반 친구인지","mis":"K6-2-u3-X26"},{"t":"후보가 주장하는 내용이 타당한지","mis":"K6-2-u3-X03"},{"t":"후보가 큰 목소리로 말하는지","mis":"K6-2-u3-X04"}],"explanation":["나연이는 「나는 놀이를 좋아하니까 무조건」이라고 말했어요.","자신이 좋아하는 것을 하는지가 나연이의 기준이에요.","같은 반 친구인지는 승재의 기준이에요."],"asset":{"type":"speech","turns":[{"who":"1번 후보","text":"제가 전교 회장이 된다면 공부에 지친 친구들이 힘낼 수 있게 한 달에 한 번 놀이만 할 수 있는 날을 만들겠습니다."},{"who":"나연","text":"우아! 나는 놀이를 좋아하니까 무조건 1번 후보를 뽑을 거야."},{"who":"승재","text":"고민할 필요 없이 우리 반 친구인 1번 후보를 뽑아야 의리가 있지!"},{"who":"지윤(속생각)","text":"그런 이유로 전교 회장을 뽑아도 될까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_basic#4','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',1,'ox','auto','비판적으로 본다는 건 무조건 의심하는 것이에요.',ARRAY['K6-2-u3-X02']::text[],false,'{"seq":4,"concept":"K6-2-u3-C2","difficulty":1,"kind":"ox","stem":"비판적으로 본다는 건 무조건 의심하는 것이에요.","answer":"X","reason_options":[{"t":"옳고 그른지를 제대로 따져 보는 것이기 때문에","correct":true},{"t":"어떤 자료든 일단 믿지 않아야 속지 않기 때문에","mis":"K6-2-u3-X02"}],"mis":"K6-2-u3-X02","explanation":["『국어』 117쪽 친구의 말을 떠올려 보아요.","비판적으로 본다는 건 옳고 그른지를 제대로 따져 보는 거예요.","무조건 의심하는 것은 따져 보기 전에 정해 버리는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_basic#5','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',2,'mc','auto','전교 회장 선거 만화에서 지윤이는 무엇을 고민하고 있나요?',ARRAY['K6-2-u3-X26','K6-2-u3-X11','K6-2-u3-X04']::text[],false,'{"seq":5,"concept":"K6-2-u3-C2","difficulty":2,"kind":"mc","stem":"전교 회장 선거 만화에서 지윤이는 무엇을 고민하고 있나요?","options":[{"t":"친구들이 말한 기준으로 전교 회장을 뽑아도 될지","correct":true},{"t":"1번 후보와 친한 사이가 될 수 있을지","mis":"K6-2-u3-X26"},{"t":"나연이와 승재 가운데 누구의 편을 들지","mis":"K6-2-u3-X11"},{"t":"놀이만 하는 날이 일 년에 몇 번인지","mis":"K6-2-u3-X04"}],"explanation":["지윤이는 「그런 이유로 전교 회장을 뽑아도 될까?」 하고 생각했어요.","「그런 이유」는 나연이와 승재가 말한 기준이에요.","좋아하는 것이나 친한 사이가 알맞은 기준인지 고민하고 있어요."],"asset":{"type":"speech","turns":[{"who":"1번 후보","text":"제가 전교 회장이 된다면 공부에 지친 친구들이 힘낼 수 있게 한 달에 한 번 놀이만 할 수 있는 날을 만들겠습니다."},{"who":"나연","text":"우아! 나는 놀이를 좋아하니까 무조건 1번 후보를 뽑을 거야."},{"who":"승재","text":"고민할 필요 없이 우리 반 친구인 1번 후보를 뽑아야 의리가 있지!"},{"who":"지윤(속생각)","text":"그런 이유로 전교 회장을 뽑아도 될까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_basic#6','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',2,'mc','auto','좋은 후보를 뽑으려면 후보의 말 가운데에서 어떤 부분을 잘 살펴봐야 할까요?',ARRAY['K6-2-u3-X26','K6-2-u3-X03']::text[],false,'{"seq":6,"concept":"K6-2-u3-C2","difficulty":2,"kind":"mc","stem":"좋은 후보를 뽑으려면 후보의 말 가운데에서 어떤 부분을 잘 살펴봐야 할까요?","options":[{"t":"후보가 주장하는 내용이 타당한지","correct":true},{"t":"후보가 나와 같은 반인지","mis":"K6-2-u3-X26"},{"t":"후보가 얼마나 자신 있게 말하는지","mis":"K6-2-u3-X03"},{"t":"후보가 약속한 놀이가 내 마음에 드는지","mis":"K6-2-u3-X26"}],"explanation":["후보의 말에는 무엇을 하겠다는 주장이 담겨 있어요.","그 주장이 타당한지 살펴봐야 좋은 후보를 고를 수 있어요.","친한 사이나 내 취향은 주장의 타당성과 상관없어요."],"asset":{"type":"speech","turns":[{"who":"1번 후보","text":"제가 전교 회장이 된다면 공부에 지친 친구들이 힘낼 수 있게 한 달에 한 번 놀이만 할 수 있는 날을 만들겠습니다."},{"who":"나연","text":"우아! 나는 놀이를 좋아하니까 무조건 1번 후보를 뽑을 거야."},{"who":"승재","text":"고민할 필요 없이 우리 반 친구인 1번 후보를 뽑아야 의리가 있지!"},{"who":"지윤(속생각)","text":"그런 이유로 전교 회장을 뽑아도 될까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_basic#7','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',2,'mc','auto','㉯에서 친구 2가 「감기에 걸리지 않는다는 근거는 무엇일까?」 하고 물었어요. 이 물음으로 따져 보려는 것은 무엇인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X06','K6-2-u3-X15']::text[],false,'{"seq":7,"concept":"K6-2-u3-C1","difficulty":2,"kind":"mc","stem":"㉯에서 친구 2가 「감기에 걸리지 않는다는 근거는 무엇일까?」 하고 물었어요. 이 물음으로 따져 보려는 것은 무엇인가요?","options":[{"t":"감기에 걸리지 않는다는 말을 받쳐 주는 자료가 있는지","correct":true},{"t":"카드 뉴스에서 하자고 한 주장이 무엇인지","mis":"K6-2-u3-X01"},{"t":"도라지차가 얼마나 맛있고 향긋한지","mis":"K6-2-u3-X06"},{"t":"카드 뉴스가 몇 장으로 이루어져 있는지","mis":"K6-2-u3-X15"}],"explanation":["「아침마다 도라지차를 마시자」는 주장이에요.","「감기에 걸리지 않는다」는 그렇게 하자는 까닭이에요.","그 까닭이 사실이라는 자료가 근거인데, 그것을 묻고 있어요."],"asset":{"type":"speech","turns":[{"who":"㉮ 영상 속 말","text":"우리 문화를 세계 여러 나라에 알릴 때에는 전통 그대로 전하는 것이 효과적입니다."},{"who":"㉮ 보는 친구","text":"많은 사람을 설득할 수 있는 주장일까?"},{"who":"㉯ 친구 1","text":"어제 카드 뉴스에서 봤는데 아침마다 도라지차를 마시래. 그럼 감기에 걸리지 않는대."},{"who":"㉯ 친구 2","text":"감기에 걸리지 않는다는 근거는 무엇일까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_basic#8','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',2,'match','auto','자료의 내용을 비판적으로 살펴보면 좋은 점을 친구들이 말했어요. 앞말과 뒷말을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u3-C2","difficulty":2,"kind":"match","stem":"자료의 내용을 비판적으로 살펴보면 좋은 점을 친구들이 말했어요. 앞말과 뒷말을 알맞게 이으세요.","pairs":[{"l":"근거가 사실인지 확인하면","r":"잘못된 정보를 걸러 낼 수 있다"},{"l":"주장하는 내용을 내 의견과 비교하면","r":"어떻게 같거나 다른지 알 수 있다"},{"l":"이유가 확실한 정보를 가려내면","r":"그 정보를 믿고 활용할 수 있다"}],"mis":"K6-2-u3-X03","explanation":["근거를 확인하면 잘못된 정보를 걸러 내요.","내 의견과 비교하면 같은 점과 다른 점이 보여요.","이유가 확실한 정보는 믿고 쓸 수 있어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"주장하는 내용이 내 의견과 어떻게 같거나 다른지 비교할 수 있어."},{"who":"친구 2","text":"이유가 확실한 정보는 믿고 활용할 수 있어."},{"who":"친구 3","text":"근거가 사실인지 확인하면 잘못된 정보를 걸러 낼 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_basic#9','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',2,'mc','auto','㉮의 영상 속 말 「우리 문화를 세계 여러 나라에 알릴 때에는 전통 그대로 전하는 것이 효과적입니다.」에서 아직 드러나지 않은 것은 무엇인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":9,"concept":"K6-2-u3-C1","difficulty":2,"kind":"mc","stem":"㉮의 영상 속 말 「우리 문화를 세계 여러 나라에 알릴 때에는 전통 그대로 전하는 것이 효과적입니다.」에서 아직 드러나지 않은 것은 무엇인가요?","options":[{"t":"왜 그런지 밝히는 이유와 그것을 뒷받침하는 근거","correct":true},{"t":"말하는 사람의 의견","mis":"K6-2-u3-X01"},{"t":"무엇에 대한 말인지 — 우리 문화를 알리는 방법","mis":"K6-2-u3-X01"},{"t":"전통 그대로 전하자는 주장","mis":"K6-2-u3-X01"}],"explanation":["「전통 그대로 전하는 것이 효과적」이라는 의견은 드러나 있어요.","왜 효과적인지 밝히는 이유가 없어요.","그 이유를 뒷받침할 근거도 없어 많은 사람을 설득하기 어려워요."],"asset":{"type":"speech","turns":[{"who":"㉮ 영상 속 말","text":"우리 문화를 세계 여러 나라에 알릴 때에는 전통 그대로 전하는 것이 효과적입니다."},{"who":"㉮ 보는 친구","text":"많은 사람을 설득할 수 있는 주장일까?"},{"who":"㉯ 친구 1","text":"어제 카드 뉴스에서 봤는데 아침마다 도라지차를 마시래. 그럼 감기에 걸리지 않는대."},{"who":"㉯ 친구 2","text":"감기에 걸리지 않는다는 근거는 무엇일까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_basic#10','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',3,'error','auto','자료의 내용을 비판적으로 살펴봐야 하는 까닭을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X03']::text[],false,'{"seq":10,"concept":"K6-2-u3-C2","difficulty":3,"kind":"error","stem":"자료의 내용을 비판적으로 살펴봐야 하는 까닭을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「어떤 자료든 틀린 곳이 있게 마련이니 무조건 믿지 않으면 돼.」","correct":true,"mis_target":"K6-2-u3-X02"},{"t":"친구 1 — 「자료의 내용을 제대로 이해할 수 있어.」","mis":"K6-2-u3-X03"},{"t":"친구 2 — 「왜곡된 정보에 휘둘리지 않을 수 있어.」","mis":"K6-2-u3-X03"}],"explanation":["친구 1과 친구 2는 『국어』 117쪽 예시처럼 바르게 말했어요.","친구 3은 따져 보기 전에 믿지 않기로 정해 버렸어요.","비판적으로 보기는 무조건 의심하기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_challenge#1','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',2,'mc','auto','생각 열기의 발표자가 「우리 학교 운동장에 쓰레기통을 많이 설치하면 운동장이 깨끗해질 것입니다.」라고 말했어요. 이 말에 담긴 주장으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X06']::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":2,"kind":"mc","stem":"생각 열기의 발표자가 「우리 학교 운동장에 쓰레기통을 많이 설치하면 운동장이 깨끗해질 것입니다.」라고 말했어요. 이 말에 담긴 주장으로 알맞은 것은 무엇인가요?","options":[{"t":"운동장에 쓰레기통을 많이 설치하자","correct":true},{"t":"운동장이 깨끗해질 것이다","mis":"K6-2-u3-X01"},{"t":"운동장에 쓰레기가 많다는 조사 결과가 있다","mis":"K6-2-u3-X01"},{"t":"운동장에서 신나게 뛰어놀자","mis":"K6-2-u3-X06"}],"explanation":["발표자가 하자고 하는 일은 쓰레기통을 많이 설치하는 것이에요.","「깨끗해질 것」은 그렇게 하자는 까닭에 가까워요.","조사 결과는 근거가 될 자료예요."],"asset":{"type":"passage","lines":["[그림] 용기초등학교 어린이 생각 발표회 — 발표자가 말한다.","발표자: “우리 학교 운동장에 쓰레기통을 많이 설치하면","운동장이 깨끗해질 것입니다.”","듣는 친구 1: 발표자가 주장하는 말의 이유와 근거는 무엇일까?","듣는 친구 2: 저 주장을 믿어도 될까?","듣는 친구 3: 어떤 점을 기준으로 타당성을 판단하면 좋을까?"],"numbered":false,"title":"생각 열기 — 『국어』 115쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_challenge#2','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',2,'sa','auto','『국어』 116쪽 (3)의 예시 답안이에요. 「후보가 주장하는 내용이 (    )한지 살펴봐야 합니다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C2","difficulty":2,"kind":"sa","stem":"『국어』 116쪽 (3)의 예시 답안이에요. 「후보가 주장하는 내용이 (    )한지 살펴봐야 합니다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["타당"],"explanation":["좋은 후보를 뽑으려면 후보의 주장을 살펴야 해요.","주장이 옳고 이치에 맞는지가 타당성이에요.","이 단원은 주장, 이유, 근거의 타당성을 판단하는 공부예요."],"asset":{"type":"speech","turns":[{"who":"1번 후보","text":"제가 전교 회장이 된다면 공부에 지친 친구들이 힘낼 수 있게 한 달에 한 번 놀이만 할 수 있는 날을 만들겠습니다."},{"who":"나연","text":"우아! 나는 놀이를 좋아하니까 무조건 1번 후보를 뽑을 거야."},{"who":"승재","text":"고민할 필요 없이 우리 반 친구인 1번 후보를 뽑아야 의리가 있지!"},{"who":"지윤(속생각)","text":"그런 이유로 전교 회장을 뽑아도 될까?"}]},"mis":"K6-2-u3-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_challenge#3','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',3,'mc','auto','승재가 「우리 반 친구인 1번 후보를 뽑아야 의리가 있지!」라고 한 말이 전교 회장을 뽑는 기준으로 알맞지 않은 까닭은 무엇인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X26','K6-2-u3-X20']::text[],false,'{"seq":3,"concept":"K6-2-u3-C2","difficulty":3,"kind":"mc","stem":"승재가 「우리 반 친구인 1번 후보를 뽑아야 의리가 있지!」라고 한 말이 전교 회장을 뽑는 기준으로 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"같은 반 친구인지는 후보가 주장하는 내용이 타당한지와 상관없기 때문","correct":true},{"t":"같은 반 친구는 절대 뽑으면 안 되기 때문","mis":"K6-2-u3-X02"},{"t":"의리는 전교 회장 선거에서 가장 중요한 기준이기 때문","mis":"K6-2-u3-X26"},{"t":"1번 후보의 주장이 틀렸다는 것이 이미 밝혀졌기 때문","mis":"K6-2-u3-X20"}],"explanation":["승재는 친분을 기준으로 삼았어요.","친분은 주장이 타당한지 알려 주지 못해요.","같은 반 친구라도 주장이 타당하면 뽑을 수 있어요."],"asset":{"type":"speech","turns":[{"who":"1번 후보","text":"제가 전교 회장이 된다면 공부에 지친 친구들이 힘낼 수 있게 한 달에 한 번 놀이만 할 수 있는 날을 만들겠습니다."},{"who":"나연","text":"우아! 나는 놀이를 좋아하니까 무조건 1번 후보를 뽑을 거야."},{"who":"승재","text":"고민할 필요 없이 우리 반 친구인 1번 후보를 뽑아야 의리가 있지!"},{"who":"지윤(속생각)","text":"그런 이유로 전교 회장을 뽑아도 될까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_challenge#4','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',3,'ox','auto','나연이처럼 「놀이를 좋아하니까 무조건」 뽑는 것은 후보 주장의 타당성을 따져 본 것이에요.',ARRAY['K6-2-u3-X26']::text[],false,'{"seq":4,"concept":"K6-2-u3-C2","difficulty":3,"kind":"ox","stem":"나연이처럼 「놀이를 좋아하니까 무조건」 뽑는 것은 후보 주장의 타당성을 따져 본 것이에요.","answer":"X","reason_options":[{"t":"자신이 좋아하는지만 보았을 뿐, 주장이 많은 사람에게 도움이 되고 실천할 수 있는지는 따지지 않았기 때문에","correct":true},{"t":"좋아하는 것을 하겠다는 후보를 뽑는 것이 가장 알맞은 판단이기 때문에","mis":"K6-2-u3-X26"}],"mis":"K6-2-u3-X26","explanation":["「무조건」은 따져 보지 않았다는 말이에요.","타당성은 주장이 가치 있고 실천할 수 있는지로 따져요.","내 취향과 주장의 타당성은 다른 문제예요."],"asset":{"type":"speech","turns":[{"who":"1번 후보","text":"제가 전교 회장이 된다면 공부에 지친 친구들이 힘낼 수 있게 한 달에 한 번 놀이만 할 수 있는 날을 만들겠습니다."},{"who":"나연","text":"우아! 나는 놀이를 좋아하니까 무조건 1번 후보를 뽑을 거야."},{"who":"승재","text":"고민할 필요 없이 우리 반 친구인 1번 후보를 뽑아야 의리가 있지!"},{"who":"지윤(속생각)","text":"그런 이유로 전교 회장을 뽑아도 될까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_challenge#5','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',3,'mc','auto','1번 후보의 말에서 「공부에 지친 친구들이 힘낼 수 있게」는 어떤 구실을 하나요?',ARRAY['K6-2-u3-X01','K6-2-u3-X08']::text[],false,'{"seq":5,"concept":"K6-2-u3-C1","difficulty":3,"kind":"mc","stem":"1번 후보의 말에서 「공부에 지친 친구들이 힘낼 수 있게」는 어떤 구실을 하나요?","options":[{"t":"놀이만 하는 날을 만들겠다는 주장의 이유","correct":true},{"t":"후보가 전교 회장이 되어 하겠다는 주장","mis":"K6-2-u3-X01"},{"t":"그 주장을 뒷받침하는 조사 자료","mis":"K6-2-u3-X08"},{"t":"후보가 자신을 소개하는 말","mis":"K6-2-u3-X01"}],"explanation":["후보가 하겠다는 일은 놀이만 하는 날을 만드는 것이에요.","「친구들이 힘낼 수 있게」는 왜 그 일을 하는지 밝힌 부분이에요.","조사 자료 같은 근거는 이 말에 없어요."],"asset":{"type":"speech","turns":[{"who":"1번 후보","text":"제가 전교 회장이 된다면 공부에 지친 친구들이 힘낼 수 있게 한 달에 한 번 놀이만 할 수 있는 날을 만들겠습니다."},{"who":"나연","text":"우아! 나는 놀이를 좋아하니까 무조건 1번 후보를 뽑을 거야."},{"who":"승재","text":"고민할 필요 없이 우리 반 친구인 1번 후보를 뽑아야 의리가 있지!"},{"who":"지윤(속생각)","text":"그런 이유로 전교 회장을 뽑아도 될까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_challenge#6','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',3,'match','auto','『국어』 116~117쪽에 나온 말과 그 말을 듣고 따져 볼 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C1","difficulty":3,"kind":"match","stem":"『국어』 116~117쪽에 나온 말과 그 말을 듣고 따져 볼 점을 알맞게 이으세요.","pairs":[{"l":"「전통 그대로 전하는 것이 효과적입니다.」","r":"많은 사람을 설득할 수 있는 주장일까?"},{"l":"「그럼 감기에 걸리지 않는대.」","r":"그렇다는 근거는 무엇일까?"},{"l":"「무조건 1번 후보를 뽑을 거야.」","r":"그런 이유로 뽑아도 될까?"}],"mis":"K6-2-u3-X01","explanation":["영상 속 말은 설득력이 있는지 따져요.","카드 뉴스 내용은 근거가 있는지 따져요.","나연이의 말은 그 이유가 알맞은지 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_challenge#7','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',3,'error','auto','생각 열기의 발표를 듣고 친구들이 말했어요. 비판적으로 듣지 않은 친구는 누구인가요?',ARRAY['K6-2-u3-X26','K6-2-u3-X03','K6-2-u3-X02']::text[],false,'{"seq":7,"concept":"K6-2-u3-C2","difficulty":3,"kind":"error","stem":"생각 열기의 발표를 듣고 친구들이 말했어요. 비판적으로 듣지 않은 친구는 누구인가요?","options":[{"t":"친구 3 — 「발표자가 우리 학교 학생이니까 그 주장은 믿어도 돼.」","correct":true,"mis_target":"K6-2-u3-X26"},{"t":"친구 1 — 「받아들이기 전에 이유와 근거가 무엇인지 먼저 들어 볼래.」","mis":"K6-2-u3-X03"},{"t":"친구 2 — 「그대로 믿었다가 손해를 볼 수도 있으니 한 번 더 생각할래.」","mis":"K6-2-u3-X02"}],"explanation":["친구 1은 이유와 근거를 따져 보려고 해요.","친구 2는 한 번 더 생각해야 하는 까닭을 알아요.","친구 3은 누가 말했는지로 믿기로 정해 버렸어요."],"asset":{"type":"passage","lines":["[그림] 용기초등학교 어린이 생각 발표회 — 발표자가 말한다.","발표자: “우리 학교 운동장에 쓰레기통을 많이 설치하면","운동장이 깨끗해질 것입니다.”","듣는 친구 1: 발표자가 주장하는 말의 이유와 근거는 무엇일까?","듣는 친구 2: 저 주장을 믿어도 될까?","듣는 친구 3: 어떤 점을 기준으로 타당성을 판단하면 좋을까?"],"numbered":false,"title":"생각 열기 — 『국어』 115쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_challenge#8','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',4,'essay','teacher','전교 회장 선거 만화에서 나연이와 승재가 후보를 뽑는 기준을 각각 쓰고, 그 기준의 문제점을 쓰세요. 그리고 지윤이에게 알려 줄 좋은 기준을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u3-C2","difficulty":4,"kind":"essay","stem":"전교 회장 선거 만화에서 나연이와 승재가 후보를 뽑는 기준을 각각 쓰고, 그 기준의 문제점을 쓰세요. 그리고 지윤이에게 알려 줄 좋은 기준을 쓰세요.","answer_guide":{"answer":"예: 나연이는 자신이 좋아하는 것(놀이)을 하는지, 승재는 같은 반 친구인지를 기준으로 삼았다. 두 기준은 모두 내 취향이나 친분일 뿐, 후보가 주장하는 내용이 타당한지와는 상관이 없다. 지윤이에게는 후보의 주장이 학교생활에 도움이 되고 실천할 수 있는지, 그 이유와 근거가 알맞은지 살펴보자고 말해 주겠다.","scoring_points":["나연이와 승재의 기준을 바르게 썼는가","취향·친분은 타당성과 관계없다는 문제점을 썼는가","주장의 타당성을 살피는 기준을 제안했는가"]},"explanation":["나연이는 좋아하는 것, 승재는 친분이 기준이에요.","둘 다 주장의 내용을 따지지 않았어요.","좋은 기준은 후보 주장의 타당성이에요."],"asset":{"type":"speech","turns":[{"who":"1번 후보","text":"제가 전교 회장이 된다면 공부에 지친 친구들이 힘낼 수 있게 한 달에 한 번 놀이만 할 수 있는 날을 만들겠습니다."},{"who":"나연","text":"우아! 나는 놀이를 좋아하니까 무조건 1번 후보를 뽑을 거야."},{"who":"승재","text":"고민할 필요 없이 우리 반 친구인 1번 후보를 뽑아야 의리가 있지!"},{"who":"지윤(속생각)","text":"그런 이유로 전교 회장을 뽑아도 될까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_challenge#9','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',4,'essay','teacher','㉯의 카드 뉴스 내용 「아침마다 도라지차를 마시래. 그럼 감기에 걸리지 않는대.」를 주장과 이유로 나누어 쓰고, 이 내용을 믿기 전에 무엇을 어떻게 확인해야 하는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C1","difficulty":4,"kind":"essay","stem":"㉯의 카드 뉴스 내용 「아침마다 도라지차를 마시래. 그럼 감기에 걸리지 않는대.」를 주장과 이유로 나누어 쓰고, 이 내용을 믿기 전에 무엇을 어떻게 확인해야 하는지 쓰세요.","answer_guide":{"answer":"예: 주장은 「아침마다 도라지차를 마시자」이고, 이유는 「그러면 감기에 걸리지 않기 때문」이다. 그런데 감기에 걸리지 않는다는 근거가 나와 있지 않다. 믿기 전에 그 말을 뒷받침하는 자료가 있는지 관련 책이나 기사를 찾아보고, 그 기사의 출처가 믿을 만한지도 다시 살펴보아야 한다.","scoring_points":["주장과 이유를 바르게 나누었는가","근거가 빠졌다는 점을 짚었는가","책·기사 찾기와 출처 확인 같은 방법을 썼는가"]},"explanation":["하자는 말이 주장, 그 까닭이 이유예요.","친구 2가 물은 것처럼 근거가 빠져 있어요.","근거가 사실인지 여러 방법으로 확인해요."],"asset":{"type":"speech","turns":[{"who":"㉮ 영상 속 말","text":"우리 문화를 세계 여러 나라에 알릴 때에는 전통 그대로 전하는 것이 효과적입니다."},{"who":"㉮ 보는 친구","text":"많은 사람을 설득할 수 있는 주장일까?"},{"who":"㉯ 친구 1","text":"어제 카드 뉴스에서 봤는데 아침마다 도라지차를 마시래. 그럼 감기에 걸리지 않는대."},{"who":"㉯ 친구 2","text":"감기에 걸리지 않는다는 근거는 무엇일까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L01_challenge#10','kor',6,2,'u3','L01','tb_g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',4,'essay','teacher','「비판적으로 본다는 건 무조건 의심하는 게 아니라 옳고 그른지를 제대로 따져 보는 거야.」라는 말을 바탕으로, 자료를 비판적으로 살펴보면 좋은 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C2","difficulty":4,"kind":"essay","stem":"「비판적으로 본다는 건 무조건 의심하는 게 아니라 옳고 그른지를 제대로 따져 보는 거야.」라는 말을 바탕으로, 자료를 비판적으로 살펴보면 좋은 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 비판적으로 보는 것은 의심부터 하는 것이 아니라 옳고 그른지를 따져 보는 것이다. 이렇게 살펴보면 자료의 내용을 제대로 이해할 수 있고, 근거가 사실인지 확인해서 잘못된 정보를 걸러 낼 수 있다. 또 주장하는 내용이 내 의견과 어떻게 같거나 다른지 비교할 수 있다.","scoring_points":["비판적으로 보기와 무조건 의심하기를 갈랐는가","좋은 점을 두 가지 썼는가","『국어』 117쪽의 생각과 이어지게 썼는가"]},"explanation":["따져 보기는 의심하기와 달라요.","제대로 이해하고 잘못된 정보를 걸러 내요.","내 의견과 견주어 볼 수도 있어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"주장하는 내용이 내 의견과 어떻게 같거나 다른지 비교할 수 있어."},{"who":"친구 2","text":"이유가 확실한 정보는 믿고 활용할 수 있어."},{"who":"친구 3","text":"근거가 사실인지 확인하면 잘못된 정보를 걸러 낼 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_basic#1','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C15',1,'sa','auto','「실수에서 배워요」에서 말한 실수의 뜻이에요. 「실수는 조심하지 않아서 잘못하는 (    )을/를 말합니다.」 빈칸에 알맞은 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u3-C15","difficulty":1,"kind":"sa","stem":"「실수에서 배워요」에서 말한 실수의 뜻이에요. 「실수는 조심하지 않아서 잘못하는 (    )을/를 말합니다.」 빈칸에 알맞은 낱말을 쓰세요.","answer":["행동"],"explanation":["말하는 이는 먼저 주제인 「실수」의 뜻을 밝혔어요.","실수는 조심하지 않아서 잘못하는 행동이에요.","주제 낱말의 뜻을 알면 주장하는 말을 깊이 이해할 수 있어요."],"asset":{"type":"passage","lines":["실수는 조심하지 않아서 잘못하는 행동을 말합니다.","(간추림) 친구와 부딪치는 실수, 약속을 깜빡 잊는 실수는 우리를 속상하게 한다.","하지만 모든 실수가 나쁜 것은 아닙니다.","(간추림) 실수에서 문제점을 찾으려 노력하면 고칠 점을 발견할 수 있다.","(간추림) 1928년 플레밍은 포도상 구균을 기르던 접시를","(간추림) 실수로 배양기 밖에 두고 휴가를 떠났다.","(간추림) 돌아와 미생물이 줄어든 것을 보고 페니실린을 발견했다.","(간추림) 실수를 했느냐보다 무엇을 배우고 실천하느냐가 중요하다."],"numbered":false,"title":"「실수에서 배워요」 — 『국어』 118쪽 듣기 자료 간추림"},"mis":"K6-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_basic#2','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C15',1,'mc','auto','「실수에서 배워요」에서 플레밍이 한 실수는 무엇인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":2,"concept":"K6-2-u3-C15","difficulty":1,"kind":"mc","stem":"「실수에서 배워요」에서 플레밍이 한 실수는 무엇인가요?","options":[{"t":"포도상 구균을 기르던 접시를 배양기 밖에 두고 휴가를 떠났다","correct":true},{"t":"페니실린을 배양기 안에 넣어 두고 잊어버렸다","mis":"K6-2-u3-X04"},{"t":"친구와 한 약속을 깜빡 잊고 지키지 못했다","mis":"K6-2-u3-X04"},{"t":"접시 안의 미생물을 모두 버렸다","mis":"K6-2-u3-X04"}],"explanation":["플레밍은 접시를 실수로 배양기 밖에 두고 휴가를 떠났어요.","돌아와 보니 접시 안의 미생물이 줄어 있었어요.","그 결과 페니실린을 발견했어요."],"asset":{"type":"passage","lines":["실수는 조심하지 않아서 잘못하는 행동을 말합니다.","(간추림) 친구와 부딪치는 실수, 약속을 깜빡 잊는 실수는 우리를 속상하게 한다.","하지만 모든 실수가 나쁜 것은 아닙니다.","(간추림) 실수에서 문제점을 찾으려 노력하면 고칠 점을 발견할 수 있다.","(간추림) 1928년 플레밍은 포도상 구균을 기르던 접시를","(간추림) 실수로 배양기 밖에 두고 휴가를 떠났다.","(간추림) 돌아와 미생물이 줄어든 것을 보고 페니실린을 발견했다.","(간추림) 실수를 했느냐보다 무엇을 배우고 실천하느냐가 중요하다."],"numbered":false,"title":"「실수에서 배워요」 — 『국어』 118쪽 듣기 자료 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_basic#3','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C6',1,'ox','auto','「실수에서 배워요」에서 말하는 이가 든 근거의 유형은 사례예요.',ARRAY['K6-2-u3-X10']::text[],false,'{"seq":3,"concept":"K6-2-u3-C6","difficulty":1,"kind":"ox","stem":"「실수에서 배워요」에서 말하는 이가 든 근거의 유형은 사례예요.","answer":"O","reason_options":[{"t":"플레밍이 실수를 탐구해 페니실린을 발견한 실제 일을 들었기 때문에","correct":true},{"t":"사람이 직접 한 말을 묻고 답한 면담 자료이기 때문에","mis":"K6-2-u3-X10"}],"mis":"K6-2-u3-X10","explanation":["근거 자료에는 표, 그래프, 면담 자료, 사례가 있어요.","말하는 이는 플레밍에게 실제로 있었던 일을 들었어요.","실제로 있었던 일을 드는 것은 사례예요."],"asset":{"type":"passage","lines":["주장 실수를 배움의 기회로 삼을 수 있다.","이유 실수에서 문제점을 찾으려 노력하면 고칠 점을 발견할 수 있기 때문이다.","근거 실수를 그냥 지나치지 않고 자세히 탐구한 플레밍처럼","      실수를 다시 생각해 보고 반성하면 더 좋은 해결 방법을","      찾을 수 있기 때문이다."],"numbered":false,"title":"「실수에서 배워요」의 주장 · 이유 · 근거 — 『국어』 119쪽 3번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_basic#4','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C4',1,'mc','auto','주장이 가치 있고 중요한지 판단할 때 쓰는 물음으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X28']::text[],false,'{"seq":4,"concept":"K6-2-u3-C4","difficulty":1,"kind":"mc","stem":"주장이 가치 있고 중요한지 판단할 때 쓰는 물음으로 알맞은 것은 무엇인가요?","options":[{"t":"실천 가능한 주장인가요?","correct":true},{"t":"이유는 주장과 관련 있나요?","mis":"K6-2-u3-X01"},{"t":"근거로 객관적인 사실이나 정보를 활용하고 있나요?","mis":"K6-2-u3-X01"},{"t":"주장의 길이가 적당한가요?","mis":"K6-2-u3-X28"}],"explanation":["주장은 「도움이 되는가」, 「실천 가능한가」로 판단해요.","주장과 관련 있는지는 이유를 판단하는 물음이에요.","객관적인 사실인지는 근거를 판단하는 물음이에요."],"asset":{"type":"passage","lines":["주장 — 문제를 해결하거나 생활하는 데 도움이 되는 주장인가요?","주장 — 실천 가능한 주장인가요?","이유 — 이유는 주장과 관련 있나요?","이유 — 많은 사람이 받아들일 만한 타당한 이유인가요?","근거 — 근거는 이유와 관련 있나요?","근거 — 근거로 객관적인 사실이나 정보를 활용하고 있나요?","[표시] 매우 그렇다: ◎ · 그렇다: ○ · 보통이다: △"],"numbered":false,"title":"타당성 판단 기준 — 『국어』 120~121쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_basic#5','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C15',2,'mc','auto','「실수에서 배워요」의 주장은 무엇인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":5,"concept":"K6-2-u3-C15","difficulty":2,"kind":"mc","stem":"「실수에서 배워요」의 주장은 무엇인가요?","options":[{"t":"실수를 배움의 기회로 삼을 수 있다","correct":true},{"t":"실수에서 문제점을 찾으려 노력하면 고칠 점을 발견할 수 있다","mis":"K6-2-u3-X01"},{"t":"플레밍은 실수로 페니실린을 발견했다","mis":"K6-2-u3-X01"},{"t":"실수는 조심하지 않아서 잘못하는 행동이다","mis":"K6-2-u3-X01"}],"explanation":["말하는 이가 듣는 사람에게 받아들이라고 하는 생각이 주장이에요.","「고칠 점을 발견할 수 있다」는 주장의 이유예요.","플레밍 이야기는 이유를 뒷받침하는 근거예요."],"asset":{"type":"passage","lines":["주장 실수를 배움의 기회로 삼을 수 있다.","이유 실수에서 문제점을 찾으려 노력하면 고칠 점을 발견할 수 있기 때문이다.","근거 실수를 그냥 지나치지 않고 자세히 탐구한 플레밍처럼","      실수를 다시 생각해 보고 반성하면 더 좋은 해결 방법을","      찾을 수 있기 때문이다."],"numbered":false,"title":"「실수에서 배워요」의 주장 · 이유 · 근거 — 『국어』 119쪽 3번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_basic#6','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C3',2,'match','auto','『국어』 119쪽에서 친구들이 말한 주장하는 말을 듣는 방법과 그 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C3","difficulty":2,"kind":"match","stem":"『국어』 119쪽에서 친구들이 말한 주장하는 말을 듣는 방법과 그 까닭을 알맞게 이으세요.","pairs":[{"l":"메모하며 듣기","r":"주장과 이유나 근거를 놓치지 않으려고"},{"l":"내 생각과 비교하며 듣기","r":"주장과 내 생각이 어떻게 같고 다른지 알려고"},{"l":"말하는 태도 살피며 듣기","r":"지나치게 감정에 호소하지는 않는지 알려고"}],"mis":"K6-2-u3-X04","explanation":["주장하는 말은 다시 듣기 어려워 메모하며 들어요.","내 생각과 비교하며 들으면 판단이 깊어져요.","말하는 이의 표현이나 태도도 주의하며 들어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"말하는 사람의 주장과 이유나 근거를 놓치지 않도록 메모하며 듣는 게 좋겠어."},{"who":"친구 2","text":"말하는 사람의 주장과 내 생각을 비교하며 들으면 어떨까?"},{"who":"친구 3","text":"지나치게 감정에 호소하지는 않는지 주의하며 들어야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_basic#7','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C5',2,'blank','auto','『국어』 121쪽 5번에서 이유의 타당성을 판단하는 물음이에요. 「이유는 주장과 (    ) 있나요?」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u3-X28','K6-2-u3-X14','K6-2-u3-X10']::text[],false,'{"seq":7,"concept":"K6-2-u3-C5","difficulty":2,"kind":"blank","stem":"『국어』 121쪽 5번에서 이유의 타당성을 판단하는 물음이에요. 「이유는 주장과 (    ) 있나요?」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"관련","correct":true},{"t":"길이","mis":"K6-2-u3-X28"},{"t":"감정","mis":"K6-2-u3-X14"},{"t":"그림","mis":"K6-2-u3-X10"}],"explanation":["이유는 주장을 적절하게 뒷받침해야 해요.","그래서 먼저 이유가 주장과 관련 있는지 살펴요.","그다음 많은 사람이 받아들일 만한지 살펴요."],"asset":{"type":"passage","lines":["주장 — 문제를 해결하거나 생활하는 데 도움이 되는 주장인가요?","주장 — 실천 가능한 주장인가요?","이유 — 이유는 주장과 관련 있나요?","이유 — 많은 사람이 받아들일 만한 타당한 이유인가요?","근거 — 근거는 이유와 관련 있나요?","근거 — 근거로 객관적인 사실이나 정보를 활용하고 있나요?","[표시] 매우 그렇다: ◎ · 그렇다: ○ · 보통이다: △"],"numbered":false,"title":"타당성 판단 기준 — 『국어』 120~121쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_basic#8','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C6',2,'mc','auto','말하는 이가 제시한 근거의 유형을 고를 때, 『국어』 121쪽에 나온 근거 자료의 유형이 아닌 것은 무엇인가요?',ARRAY['K6-2-u3-X10']::text[],false,'{"seq":8,"concept":"K6-2-u3-C6","difficulty":2,"kind":"mc","stem":"말하는 이가 제시한 근거의 유형을 고를 때, 『국어』 121쪽에 나온 근거 자료의 유형이 아닌 것은 무엇인가요?","options":[{"t":"말하는 이의 느낌","correct":true},{"t":"표","mis":"K6-2-u3-X10"},{"t":"면담 자료","mis":"K6-2-u3-X10"},{"t":"사례","mis":"K6-2-u3-X10"}],"explanation":["근거 자료의 유형에는 표, 그래프, 면담 자료, 사례가 있어요.","말하는 이의 느낌은 누구나 확인할 수 있는 자료가 아니에요.","근거로는 객관적인 사실이나 정보를 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_basic#9','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C4',2,'ox','auto','「환경을 보호하자.」보다 「종이컵보다 개인 컵을 사용하자.」가 더 실천 가능한 주장이에요.',ARRAY['K6-2-u3-X05']::text[],false,'{"seq":9,"concept":"K6-2-u3-C4","difficulty":2,"kind":"ox","stem":"「환경을 보호하자.」보다 「종이컵보다 개인 컵을 사용하자.」가 더 실천 가능한 주장이에요.","answer":"O","reason_options":[{"t":"무엇을 해야 할지 구체적으로 드러나 생활에서 바로 해 볼 수 있기 때문에","correct":true},{"t":"범위가 큰 주장일수록 많은 사람에게 도움이 되므로 더 실천하기 쉽기 때문에","mis":"K6-2-u3-X05"}],"mis":"K6-2-u3-X05","explanation":["「환경을 보호하자.」는 범위가 큰 주장이에요.","「개인 컵을 사용하자.」는 할 일이 구체적이에요.","실천 가능할 때 주장의 가치가 더 높아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_basic#10','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C4',3,'essay','teacher','「실수에서 배워요」의 주장이 가치 있고 중요한지 『국어』 120쪽의 두 물음으로 판단하고, 각각 그렇게 판단한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C4","difficulty":3,"kind":"essay","stem":"「실수에서 배워요」의 주장이 가치 있고 중요한지 『국어』 120쪽의 두 물음으로 판단하고, 각각 그렇게 판단한 까닭을 쓰세요.","answer_guide":{"answer":"예: 문제를 해결하거나 생활하는 데 도움이 되는 주장이다. 누구나 실수를 하고 실수 때문에 속상할 때가 많은데, 실수를 배움의 기회로 삼자는 주장은 우리가 실수에서 배우고 성장하도록 돕기 때문이다. 또 실천 가능한 주장이다. 실수를 했을 때 돌아보고 고치려는 행동은 특별한 준비 없이 누구나 일상에서 바로 할 수 있기 때문이다.","scoring_points":["도움이 되는지 판단하고 까닭을 썼는가","실천 가능한지 판단하고 까닭을 썼는가","「실수에서 배워요」의 내용과 이어 썼는가"]},"explanation":["물음 하나 — 도움이 되는 주장인가?","물음 둘 — 실천 가능한 주장인가?","판단마다 「왜냐하면」으로 까닭을 붙여요."],"asset":{"type":"passage","lines":["주장 실수를 배움의 기회로 삼을 수 있다.","이유 실수에서 문제점을 찾으려 노력하면 고칠 점을 발견할 수 있기 때문이다.","근거 실수를 그냥 지나치지 않고 자세히 탐구한 플레밍처럼","      실수를 다시 생각해 보고 반성하면 더 좋은 해결 방법을","      찾을 수 있기 때문이다."],"numbered":false,"title":"「실수에서 배워요」의 주장 · 이유 · 근거 — 『국어』 119쪽 3번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_challenge#1','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C3',2,'mc','auto','주장하는 말을 들을 때 메모하며 듣기와 요약하며 듣기를 적극적으로 활용해야 하는 까닭은 무엇인가요?',ARRAY['K6-2-u3-X04','K6-2-u3-X28']::text[],false,'{"seq":1,"concept":"K6-2-u3-C3","difficulty":2,"kind":"mc","stem":"주장하는 말을 들을 때 메모하며 듣기와 요약하며 듣기를 적극적으로 활용해야 하는 까닭은 무엇인가요?","options":[{"t":"주장하는 말은 한 번 들은 뒤에 다시 듣기 어렵기 때문","correct":true},{"t":"주장하는 말은 언제나 글보다 내용이 길기 때문","mis":"K6-2-u3-X04"},{"t":"말하는 사람의 목소리를 기억해야 하기 때문","mis":"K6-2-u3-X04"},{"t":"메모하는 모습을 보여야 말하는 사람이 기뻐하기 때문","mis":"K6-2-u3-X28"}],"explanation":["주장하는 글은 다시 읽을 수 있어요.","주장하는 말은 한 번 들으면 되풀이해 듣기 어려워요.","그래서 주장, 이유, 근거를 적고 간추리며 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_challenge#2','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C6',2,'sa','auto','『국어』 121쪽의 정리 글이에요. 「타당성을 평가한다는 것은 제시된 이유와 근거가 주장과 잘 맞고 (    )이 있는지 판단하는 것을 뜻해요.」 빈칸에 알맞은 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C6","difficulty":2,"kind":"sa","stem":"『국어』 121쪽의 정리 글이에요. 「타당성을 평가한다는 것은 제시된 이유와 근거가 주장과 잘 맞고 (    )이 있는지 판단하는 것을 뜻해요.」 빈칸에 알맞은 낱말을 쓰세요.","answer":["설득력"],"explanation":["이유와 근거가 주장과 잘 맞는지 살펴요.","그 말이 듣는 사람을 설득할 힘이 있는지도 살펴요.","그 힘을 설득력이라고 해요."],"mis":"K6-2-u3-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_challenge#3','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C5',3,'mc','auto','「실수에서 배워요」의 이유를 『국어』 121쪽 판단 기준으로 판단한 결과로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X06','K6-2-u3-X07','K6-2-u3-X01']::text[],false,'{"seq":3,"concept":"K6-2-u3-C5","difficulty":3,"kind":"mc","stem":"「실수에서 배워요」의 이유를 『국어』 121쪽 판단 기준으로 판단한 결과로 알맞은 것은 무엇인가요?","options":[{"t":"주장과 관련 있고 많은 사람이 받아들일 만해 두 기준 모두 ◎","correct":true},{"t":"주장과 관련 없는 이야기라서 「관련」 기준에 △","mis":"K6-2-u3-X06"},{"t":"말하는 이 혼자만의 생각이라서 「받아들일 만함」에 △","mis":"K6-2-u3-X07"},{"t":"이유가 아니라 근거라서 판단할 수 없음","mis":"K6-2-u3-X01"}],"explanation":["이유는 「실수에서 문제점을 찾으려 노력하면 고칠 점을 발견할 수 있다」예요.","실수를 배움의 기회로 삼자는 주장과 바로 이어져요.","누구나 겪어 보아 고개를 끄덕일 만한 이유예요."],"asset":{"type":"passage","lines":["주장 실수를 배움의 기회로 삼을 수 있다.","이유 실수에서 문제점을 찾으려 노력하면 고칠 점을 발견할 수 있기 때문이다.","근거 실수를 그냥 지나치지 않고 자세히 탐구한 플레밍처럼","      실수를 다시 생각해 보고 반성하면 더 좋은 해결 방법을","      찾을 수 있기 때문이다."],"numbered":false,"title":"「실수에서 배워요」의 주장 · 이유 · 근거 — 『국어』 119쪽 3번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_challenge#4','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C6',3,'error','auto','근거로 제시된 정보가 사실인지 확인하는 방법을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X09','K6-2-u3-X02']::text[],false,'{"seq":4,"concept":"K6-2-u3-C6","difficulty":3,"kind":"error","stem":"근거로 제시된 정보가 사실인지 확인하는 방법을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「인터넷 검색 첫 화면에 나온 글이면 확인은 끝난 거야.」","correct":true,"mis_target":"K6-2-u3-X09"},{"t":"친구 1 — 「관련 있는 내용을 다룬 책이나 기사를 찾아볼래.」","mis":"K6-2-u3-X02"},{"t":"친구 2 — 「기사를 찾으면 그 기사의 출처가 믿을 만한지 다시 살펴볼래.」","mis":"K6-2-u3-X02"}],"explanation":["근거가 사실인지 알아보려면 관련 책이나 기사를 찾아볼 수 있어요.","찾은 기사의 출처가 믿을 만한지도 다시 살펴요.","검색 화면에 나왔다고 사실이 되는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_challenge#5','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C15',3,'mc','auto','「실수에서 배워요」의 근거가 이유를 적절하게 뒷받침한다고 볼 수 있는 까닭은 무엇인가요?',ARRAY['K6-2-u3-X03','K6-2-u3-X08']::text[],false,'{"seq":5,"concept":"K6-2-u3-C15","difficulty":3,"kind":"mc","stem":"「실수에서 배워요」의 근거가 이유를 적절하게 뒷받침한다고 볼 수 있는 까닭은 무엇인가요?","options":[{"t":"실수를 자세히 탐구해 새로운 것을 발견한 실제 사례를 보여 주기 때문","correct":true},{"t":"플레밍이 유명한 과학자라서 무조건 믿을 수 있기 때문","mis":"K6-2-u3-X03"},{"t":"말하는 이가 플레밍을 좋아한다고 밝혔기 때문","mis":"K6-2-u3-X08"},{"t":"근거는 길고 자세할수록 타당하기 때문","mis":"K6-2-u3-X08"}],"explanation":["이유는 「실수에서 고칠 점을 발견할 수 있다」예요.","플레밍은 실수를 그냥 넘기지 않고 탐구해 페니실린을 발견했어요.","이유를 실제로 보여 주는 사례라서 뒷받침이 돼요."],"asset":{"type":"passage","lines":["주장 실수를 배움의 기회로 삼을 수 있다.","이유 실수에서 문제점을 찾으려 노력하면 고칠 점을 발견할 수 있기 때문이다.","근거 실수를 그냥 지나치지 않고 자세히 탐구한 플레밍처럼","      실수를 다시 생각해 보고 반성하면 더 좋은 해결 방법을","      찾을 수 있기 때문이다."],"numbered":false,"title":"「실수에서 배워요」의 주장 · 이유 · 근거 — 『국어』 119쪽 3번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_challenge#6','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C6',3,'match','auto','『국어』 121쪽 6번처럼 주장하는 말의 타당성을 평가하는 물음과 그 물음으로 살펴보는 대상을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C6","difficulty":3,"kind":"match","stem":"『국어』 121쪽 6번처럼 주장하는 말의 타당성을 평가하는 물음과 그 물음으로 살펴보는 대상을 알맞게 이으세요.","pairs":[{"l":"가치 있고 중요한가?","r":"주장"},{"l":"많은 사람이 받아들일 만한가?","r":"이유"},{"l":"객관적인 사실이나 정보를 활용했는가?","r":"근거"}],"mis":"K6-2-u3-X28","explanation":["주장은 가치 있고 중요한지 살펴요.","이유는 주장과 관련 있고 많은 사람이 받아들일 만한지 살펴요.","근거는 이유와 관련 있고 객관적인지 살펴요."],"asset":{"type":"passage","lines":["주장 — 문제를 해결하거나 생활하는 데 도움이 되는 주장인가요?","주장 — 실천 가능한 주장인가요?","이유 — 이유는 주장과 관련 있나요?","이유 — 많은 사람이 받아들일 만한 타당한 이유인가요?","근거 — 근거는 이유와 관련 있나요?","근거 — 근거로 객관적인 사실이나 정보를 활용하고 있나요?","[표시] 매우 그렇다: ◎ · 그렇다: ○ · 보통이다: △"],"numbered":false,"title":"타당성 판단 기준 — 『국어』 120~121쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_challenge#7','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C3',3,'blank','auto','『국어』 119쪽에서 한 친구가 말했어요. 「말하는 사람의 주장과 내 생각을 (    ) 들으면 어떨까?」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":7,"concept":"K6-2-u3-C3","difficulty":3,"kind":"blank","stem":"『국어』 119쪽에서 한 친구가 말했어요. 「말하는 사람의 주장과 내 생각을 (    ) 들으면 어떨까?」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"비교하며","correct":true},{"t":"따라 하며","mis":"K6-2-u3-X04"},{"t":"외우며","mis":"K6-2-u3-X04"},{"t":"흘려들으며","mis":"K6-2-u3-X04"}],"explanation":["주장하는 말을 들을 때 내 생각과 견주어 보아요.","그러면 같은 점과 다른 점이 드러나요.","비교하며 들으면 비판적으로 들을 수 있어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"말하는 사람의 주장과 이유나 근거를 놓치지 않도록 메모하며 듣는 게 좋겠어."},{"who":"친구 2","text":"말하는 사람의 주장과 내 생각을 비교하며 들으면 어떨까?"},{"who":"친구 3","text":"지나치게 감정에 호소하지는 않는지 주의하며 들어야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_challenge#8','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C5',4,'essay','teacher','「실수에서 배워요」의 이유와 근거가 타당한지 『국어』 121쪽 네 가지 기준으로 판단하고, 근거의 유형과 함께 그렇게 판단한 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u3-C5","difficulty":4,"kind":"essay","stem":"「실수에서 배워요」의 이유와 근거가 타당한지 『국어』 121쪽 네 가지 기준으로 판단하고, 근거의 유형과 함께 그렇게 판단한 까닭을 쓰세요.","answer_guide":{"answer":"예: 이유는 주장과 관련 있고(◎), 실수에서 고칠 점을 찾을 수 있다는 것은 많은 사람이 받아들일 만하다(◎). 근거의 유형은 사례이다. 플레밍이 실수를 탐구해 페니실린을 발견한 일은 이유와 관련 있고(◎), 실제로 있었던 객관적인 사실이다(◎). 그래서 이유와 근거가 모두 타당하다고 판단했다.","scoring_points":["이유의 두 기준을 판단했는가","근거의 유형(사례)을 밝혔는가","근거의 두 기준을 판단하고 까닭을 썼는가"]},"explanation":["이유 — 관련 있나, 많은 사람이 받아들일 만한가.","근거 — 관련 있나, 객관적인가.","판단마다 까닭을 들어 말해요."],"asset":{"type":"passage","lines":["주장 실수를 배움의 기회로 삼을 수 있다.","이유 실수에서 문제점을 찾으려 노력하면 고칠 점을 발견할 수 있기 때문이다.","근거 실수를 그냥 지나치지 않고 자세히 탐구한 플레밍처럼","      실수를 다시 생각해 보고 반성하면 더 좋은 해결 방법을","      찾을 수 있기 때문이다."],"numbered":false,"title":"「실수에서 배워요」의 주장 · 이유 · 근거 — 『국어』 119쪽 3번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_challenge#9','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C3',4,'essay','teacher','『국어』 119쪽에서 친구들이 말한 주장하는 말을 듣는 방법 세 가지를 쓰고, 「실수에서 배워요」를 다시 들을 때 그 방법을 어떻게 쓸지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C3","difficulty":4,"kind":"essay","stem":"『국어』 119쪽에서 친구들이 말한 주장하는 말을 듣는 방법 세 가지를 쓰고, 「실수에서 배워요」를 다시 들을 때 그 방법을 어떻게 쓸지 쓰세요.","answer_guide":{"answer":"예: 주장과 이유나 근거를 놓치지 않도록 메모하며 듣고, 말하는 사람의 주장과 내 생각을 비교하며 듣고, 지나치게 감정에 호소하지는 않는지 주의하며 듣는다. 「실수에서 배워요」를 다시 들을 때에는 주장, 이유, 근거를 표에 적고, 실수를 배움의 기회로 삼자는 생각이 내 경험과 맞는지 견주어 보겠다.","scoring_points":["듣는 방법 세 가지를 썼는가","「실수에서 배워요」에 적용한 모습을 썼는가","메모·비교·태도 살피기가 드러났는가"]},"explanation":["메모하며 듣기.","내 생각과 비교하며 듣기.","표현과 태도까지 살피며 듣기."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"말하는 사람의 주장과 이유나 근거를 놓치지 않도록 메모하며 듣는 게 좋겠어."},{"who":"친구 2","text":"말하는 사람의 주장과 내 생각을 비교하며 들으면 어떨까?"},{"who":"친구 3","text":"지나치게 감정에 호소하지는 않는지 주의하며 들어야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L02_challenge#10','kor',6,2,'u3','L02','tb_g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C4',4,'essay','teacher','『국어』 121쪽 6번처럼 주장하는 말을 듣고 내용의 타당성을 평가하는 방법을 주장, 이유, 근거로 나누어 정리하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C4","difficulty":4,"kind":"essay","stem":"『국어』 121쪽 6번처럼 주장하는 말을 듣고 내용의 타당성을 평가하는 방법을 주장, 이유, 근거로 나누어 정리하세요.","answer_guide":{"answer":"예: 주장 — 주장이 가치 있고 중요한지 판단한다(문제를 해결하거나 생활하는 데 도움이 되는지, 실천 가능한지). 이유 — 이유가 주장과 관련 있는지, 많은 사람이 받아들일 만한 타당한 이유인지 살펴본다. 근거 — 근거가 이유와 관련 있는지, 근거로 객관적인 사실이나 정보를 활용하고 있는지 살펴본다.","scoring_points":["주장의 판단 방법을 썼는가","이유의 두 기준을 썼는가","근거의 두 기준을 썼는가"]},"explanation":["주장 — 가치 있고 중요한가.","이유 — 관련 · 받아들일 만함.","근거 — 관련 · 객관적인 사실이나 정보."],"asset":{"type":"passage","lines":["주장 — 문제를 해결하거나 생활하는 데 도움이 되는 주장인가요?","주장 — 실천 가능한 주장인가요?","이유 — 이유는 주장과 관련 있나요?","이유 — 많은 사람이 받아들일 만한 타당한 이유인가요?","근거 — 근거는 이유와 관련 있나요?","근거 — 근거로 객관적인 사실이나 정보를 활용하고 있나요?","[표시] 매우 그렇다: ◎ · 그렇다: ○ · 보통이다: △"],"numbered":false,"title":"타당성 판단 기준 — 『국어』 120~121쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_basic#1','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C16',1,'mc','auto','「용기초등학교 어린이 생각 발표회」에서 윤정이와 현우가 주장하는 말을 한 목적은 무엇인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":1,"concept":"K6-2-u3-C16","difficulty":1,"kind":"mc","stem":"「용기초등학교 어린이 생각 발표회」에서 윤정이와 현우가 주장하는 말을 한 목적은 무엇인가요?","options":[{"t":"자신의 주장을 알려 학생들을 설득하려고","correct":true},{"t":"급식 반찬을 만드는 방법을 알려 주려고","mis":"K6-2-u3-X04"},{"t":"친구들의 급식 습관을 칭찬하려고","mis":"K6-2-u3-X04"},{"t":"채소와 고기의 맛을 견주어 보려고","mis":"K6-2-u3-X04"}],"explanation":["주장하는 말에는 청중을 설득하려는 내용이 담겨 있어요.","윤정이와 현우는 급식에 대한 자신의 주장을 알렸어요.","듣는 학생들이 자신의 생각에 동의하게 하려는 것이 목적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_basic#2','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C16',1,'sa','auto','「용기초등학교 어린이 생각 발표회」에서 윤정이와 현우는 누구를 대상으로 주장하는 말을 했는지 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C16","difficulty":1,"kind":"sa","stem":"「용기초등학교 어린이 생각 발표회」에서 윤정이와 현우는 누구를 대상으로 주장하는 말을 했는지 쓰세요.","answer":["용기초등학교 학생들","용기초등학교 학생","용기초등학교 학생 여러분","학생들"],"explanation":["윤정이는 「용기초등학교 학생 여러분」 하고 말을 시작했어요.","주장하는 말을 들을 때는 대상을 먼저 파악해요.","대상은 용기초등학교 학생들이에요."],"mis":"K6-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_basic#3','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C17',1,'blank','auto','「용기초등학교 어린이 생각 발표회」에 나온 낱말이에요. 「점점 속도를 더하다.」라는 뜻을 가진 낱말은 무엇인가요?',ARRAY['K6-2-u3-X29']::text[],false,'{"seq":3,"concept":"K6-2-u3-C17","difficulty":1,"kind":"blank","stem":"「용기초등학교 어린이 생각 발표회」에 나온 낱말이에요. 「점점 속도를 더하다.」라는 뜻을 가진 낱말은 무엇인가요?","options":[{"t":"가속하다","correct":true},{"t":"대항하다","mis":"K6-2-u3-X29"},{"t":"제공하다","mis":"K6-2-u3-X29"},{"t":"발생하다","mis":"K6-2-u3-X29"}],"explanation":["윤정이는 육류 생산과 소비가 지구 온난화를 가속한다고 했어요.","「가속하다」는 점점 속도를 더한다는 뜻이에요.","모르는 낱말은 사전에서 뜻을 찾아 확인해요."],"asset":{"type":"passage","lines":["보기: 가속하다 · 대항하다 · 발생하다 · 섭취하다 · 제공하다","㉮ 생물체가 양분 따위를 몸속에 빨아들이다.","㉯ 무엇을 내주거나 갖다 바치다.","㉰ 굽히거나 지지 않으려고 맞서서 버티거나 항거하다.","㉱ 점점 속도를 더하다."],"numbered":false,"title":"「용기초등학교 어린이 생각 발표회」 낱말 알기 — 『국어』 125쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_basic#4','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C16',1,'ox','auto','윤정이와 현우는 둘 다 학교 급식의 반찬 구성을 바꾸고 싶어 해요.',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":4,"concept":"K6-2-u3-C16","difficulty":1,"kind":"ox","stem":"윤정이와 현우는 둘 다 학교 급식의 반찬 구성을 바꾸고 싶어 해요.","answer":"O","reason_options":[{"t":"윤정이는 채소 위주의 음식을, 현우는 질 좋은 고기반찬을 늘리자고 했기 때문에","correct":true},{"t":"두 사람 모두 고기반찬을 줄이자고 했기 때문에","mis":"K6-2-u3-X04"}],"mis":"K6-2-u3-X04","explanation":["두 친구가 바꾸고 싶은 것은 급식 반찬의 구성이에요.","윤정이는 채소 위주의 음식을 제공하는 날을 늘리자고 했어요.","현우는 질 좋은 고기반찬을 더 충분히 제공하자고 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_basic#5','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C16',2,'mc','auto','현우가 주장하는 말에서 이유에 해당하는 것은 무엇인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X04']::text[],false,'{"seq":5,"concept":"K6-2-u3-C16","difficulty":2,"kind":"mc","stem":"현우가 주장하는 말에서 이유에 해당하는 것은 무엇인가요?","options":[{"t":"질 좋은 고기반찬으로만 성장에 필요한 단백질을 섭취할 수 있기 때문","correct":true},{"t":"질 좋은 고기반찬을 더 충분히 제공하자","mis":"K6-2-u3-X01"},{"t":"단백질 섭취 부족 시 충치 발생 위험이 높아질 수 있다는 연구 결과","mis":"K6-2-u3-X01"},{"t":"육류를 생산하는 과정이 지구 온난화를 가속하기 때문","mis":"K6-2-u3-X04"}],"explanation":["「고기반찬을 더 충분히 제공하자」는 주장이에요.","「~ 때문」으로 왜 그런지 밝힌 부분이 이유예요.","연구 결과는 이유를 뒷받침하려고 든 근거예요."],"asset":{"type":"passage","lines":["주장 질 좋은 고기반찬을 더 충분히 제공하자.","이유 질 좋은 고기반찬으로만 성장에 필요한 단백질을 섭취할 수 있기 때문이다.","근거 단백질 섭취 부족 시 충치 발생 위험이 높아질 수 있다는 연구 결과가 있다."],"numbered":false,"title":"「용기초등학교 어린이 생각 발표회」 현우의 말 정리 — 『국어』 124쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_basic#6','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C7',2,'mc','auto','『국어』 126쪽 판단 예시에서 현우의 이유가 「많은 사람이 받아들일 만한 타당한 이유인가요?」에 △를 받은 까닭은 무엇인가요?',ARRAY['K6-2-u3-X06','K6-2-u3-X04','K6-2-u3-X24']::text[],false,'{"seq":6,"concept":"K6-2-u3-C7","difficulty":2,"kind":"mc","stem":"『국어』 126쪽 판단 예시에서 현우의 이유가 「많은 사람이 받아들일 만한 타당한 이유인가요?」에 △를 받은 까닭은 무엇인가요?","options":[{"t":"단백질은 다른 음식으로도 섭취할 수 있어 「고기반찬으로만」을 받아들이기 어렵기 때문","correct":true},{"t":"이유가 고기반찬을 제공하자는 주장과 전혀 관련이 없기 때문","mis":"K6-2-u3-X06"},{"t":"현우가 발표할 때 목소리가 작아 잘 들리지 않았기 때문","mis":"K6-2-u3-X04"},{"t":"고기반찬을 좋아하는 학생이 많아 누구나 받아들일 만한 이유이기 때문","mis":"K6-2-u3-X24"}],"explanation":["현우의 이유는 주장과 관련은 있어요(◎).","하지만 단백질은 다른 음식으로도 충분히 섭취할 수 있어요.","그래서 많은 사람이 받아들이기에는 부족해요(△)."],"asset":{"type":"passage","lines":["기준 이유는 주장과 관련 있나요? — 윤정 ◎ · 현우 ◎","기준 많은 사람이 받아들일 만한 타당한 이유인가요? — 윤정 ◎ · 현우 △","기준 근거는 이유와 관련 있나요? — 윤정 ◎ · 현우 ○","기준 근거로 객관적인 사실이나 정보를 활용하나요? — 윤정 ◎ · 현우 ◎"],"numbered":false,"title":"이유와 근거의 타당성 판단 — 『국어』 126쪽 (2) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_basic#7','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C17',2,'match','auto','「용기초등학교 어린이 생각 발표회」에 나온 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u3-C17","difficulty":2,"kind":"match","stem":"「용기초등학교 어린이 생각 발표회」에 나온 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"섭취하다","r":"생물체가 양분 따위를 몸속에 빨아들이다"},{"l":"제공하다","r":"무엇을 내주거나 갖다 바치다"},{"l":"대항하다","r":"굽히거나 지지 않으려고 맞서서 버티거나 항거하다"}],"mis":"K6-2-u3-X29","explanation":["단백질을 「섭취하다」는 몸속에 빨아들인다는 뜻이에요.","급식을 「제공하다」는 내준다는 뜻이에요.","질병에 「대항하다」는 지지 않으려고 맞선다는 뜻이에요."],"asset":{"type":"passage","lines":["보기: 가속하다 · 대항하다 · 발생하다 · 섭취하다 · 제공하다","㉮ 생물체가 양분 따위를 몸속에 빨아들이다.","㉯ 무엇을 내주거나 갖다 바치다.","㉰ 굽히거나 지지 않으려고 맞서서 버티거나 항거하다.","㉱ 점점 속도를 더하다."],"numbered":false,"title":"「용기초등학교 어린이 생각 발표회」 낱말 알기 — 『국어』 125쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_basic#8','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C8',2,'mc','auto','윤정이가 근거를 말하며 「한 기사에 따르면」이라고 밝힌 것이 좋은 까닭은 무엇인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X14','K6-2-u3-X09']::text[],false,'{"seq":8,"concept":"K6-2-u3-C8","difficulty":2,"kind":"mc","stem":"윤정이가 근거를 말하며 「한 기사에 따르면」이라고 밝힌 것이 좋은 까닭은 무엇인가요?","options":[{"t":"근거가 어디에서 나왔는지 밝혀 듣는 사람이 확인해 볼 수 있기 때문","correct":true},{"t":"말이 길어져 더 그럴듯하게 들리기 때문","mis":"K6-2-u3-X08"},{"t":"듣는 사람의 감정을 움직이기 때문","mis":"K6-2-u3-X14"},{"t":"출처를 밝히면 근거가 사실인지 따로 살필 필요가 없기 때문","mis":"K6-2-u3-X09"}],"explanation":["근거는 누가 보아도 그러한 객관적인 정보여야 해요.","어디에서 나온 정보인지 밝히면 듣는 사람이 확인할 수 있어요.","그래도 그 출처가 믿을 만한지는 한 번 더 살펴요."],"asset":{"type":"passage","lines":["주장 급식에서 채소 위주의 음식을 제공하는 날을 늘리자.","이유 육류를 생산하고 소비하는 과정이 지구 온난화를 가속하는 원인이 되기 때문이다.","근거 일주일에 한 번 채식을 했을 때 일 년에 소나무 열다섯 그루를","      심는 효과가 있다는 기사가 있다."],"numbered":false,"title":"「용기초등학교 어린이 생각 발표회」 윤정이의 말 정리 — 『국어』 124쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_basic#9','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C7',2,'ox','auto','친구들의 판단 결과가 서로 다를 때에는 표시만 맞추면 되고 까닭은 말하지 않아도 돼요.',ARRAY['K6-2-u3-X12']::text[],false,'{"seq":9,"concept":"K6-2-u3-C7","difficulty":2,"kind":"ox","stem":"친구들의 판단 결과가 서로 다를 때에는 표시만 맞추면 되고 까닭은 말하지 않아도 돼요.","answer":"X","reason_options":[{"t":"어떤 기준으로 그렇게 판단했는지 논리적으로 설명해야 하기 때문에","correct":true},{"t":"판단 결과는 사람마다 언제나 같아야 하기 때문에","mis":"K6-2-u3-X12"}],"mis":"K6-2-u3-X12","explanation":["어떤 기준을 무겁게 보느냐에 따라 판단이 달라질 수 있어요.","그럴 때는 자신이 그렇게 판단한 까닭을 설명해요.","까닭을 들으며 서로의 판단을 견주어 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_basic#10','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C7',3,'essay','teacher','『국어』 126쪽 (3)처럼 윤정이의 주장하는 말에서 타당한 점과 보완할 점을 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C7","difficulty":3,"kind":"essay","stem":"『국어』 126쪽 (3)처럼 윤정이의 주장하는 말에서 타당한 점과 보완할 점을 하나씩 쓰세요.","answer_guide":{"answer":"예: 타당한 점 — 이유를 뒷받침하려고 일주일에 한 번 채식을 하면 일 년에 소나무 열다섯 그루를 심는 효과가 있다는 구체적인 근거를 들어 설명한 점이 타당하다. 보완할 점 — 채식을 하면 우리 몸에 어떤 좋은 점이 있는지도 이유와 근거로 제시하면 주장을 더 잘 뒷받침할 수 있을 것 같다.","scoring_points":["타당한 점을 근거와 이어 썼는가","보완할 점을 썼는가","주장을 더 잘 뒷받침하는 방향을 제안했는가"]},"explanation":["타당한 점을 먼저 찾아요.","그다음 보완할 점을 찾아요.","보완할 점은 더 나아지게 하는 제안이에요."],"asset":{"type":"passage","lines":["주장 급식에서 채소 위주의 음식을 제공하는 날을 늘리자.","이유 육류를 생산하고 소비하는 과정이 지구 온난화를 가속하는 원인이 되기 때문이다.","근거 일주일에 한 번 채식을 했을 때 일 년에 소나무 열다섯 그루를","      심는 효과가 있다는 기사가 있다."],"numbered":false,"title":"「용기초등학교 어린이 생각 발표회」 윤정이의 말 정리 — 『국어』 124쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_challenge#1','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C16',2,'mc','auto','윤정이가 주장하는 말에서 근거에 해당하는 것은 무엇인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X04']::text[],false,'{"seq":1,"concept":"K6-2-u3-C16","difficulty":2,"kind":"mc","stem":"윤정이가 주장하는 말에서 근거에 해당하는 것은 무엇인가요?","options":[{"t":"일주일에 한 번 채식을 했을 때 일 년에 소나무 열다섯 그루를 심는 효과가 있다는 기사","correct":true},{"t":"육류를 생산하고 소비하는 과정이 지구 온난화를 가속하는 원인이 된다","mis":"K6-2-u3-X01"},{"t":"급식에서 채소 위주의 음식을 제공하는 날을 늘리자","mis":"K6-2-u3-X01"},{"t":"단백질은 몸을 튼튼하게 해 준다","mis":"K6-2-u3-X04"}],"explanation":["「채소 위주 음식 날을 늘리자」는 주장이에요.","「지구 온난화를 가속하는 원인」은 이유예요.","이유를 뒷받침하려고 든 기사 내용이 근거예요."],"asset":{"type":"passage","lines":["주장 급식에서 채소 위주의 음식을 제공하는 날을 늘리자.","이유 육류를 생산하고 소비하는 과정이 지구 온난화를 가속하는 원인이 되기 때문이다.","근거 일주일에 한 번 채식을 했을 때 일 년에 소나무 열다섯 그루를","      심는 효과가 있다는 기사가 있다."],"numbered":false,"title":"「용기초등학교 어린이 생각 발표회」 윤정이의 말 정리 — 『국어』 124쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_challenge#2','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C17',2,'sa','auto','「용기초등학교 어린이 생각 발표회」에 나온 낱말 가운데 「생물체가 양분 따위를 몸속에 빨아들이다.」라는 뜻을 가진 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C17","difficulty":2,"kind":"sa","stem":"「용기초등학교 어린이 생각 발표회」에 나온 낱말 가운데 「생물체가 양분 따위를 몸속에 빨아들이다.」라는 뜻을 가진 낱말을 쓰세요.","answer":["섭취하다","섭취"],"explanation":["현우는 고기반찬으로 단백질을 섭취해야 한다고 했어요.","「섭취하다」는 양분을 몸속에 빨아들인다는 뜻이에요.","<보기>의 「발생하다」는 뜻풀이가 없는 낱말이에요."],"asset":{"type":"passage","lines":["보기: 가속하다 · 대항하다 · 발생하다 · 섭취하다 · 제공하다","㉮ 생물체가 양분 따위를 몸속에 빨아들이다.","㉯ 무엇을 내주거나 갖다 바치다.","㉰ 굽히거나 지지 않으려고 맞서서 버티거나 항거하다.","㉱ 점점 속도를 더하다."],"numbered":false,"title":"「용기초등학교 어린이 생각 발표회」 낱말 알기 — 『국어』 125쪽"},"mis":"K6-2-u3-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_challenge#3','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',3,'mc','auto','『국어』 126쪽 판단 예시에서 현우의 근거가 「근거는 이유와 관련 있나요?」에 ○를 받은 까닭은 무엇인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X25','K6-2-u3-X20']::text[],false,'{"seq":3,"concept":"K6-2-u3-C7","difficulty":3,"kind":"mc","stem":"『국어』 126쪽 판단 예시에서 현우의 근거가 「근거는 이유와 관련 있나요?」에 ○를 받은 까닭은 무엇인가요?","options":[{"t":"단백질이 중요하다는 것만 보여 줄 뿐, 「고기반찬으로만」이라는 이유는 보여 주지 못하기 때문","correct":true},{"t":"연구 결과는 누구나 확인할 수 있는 객관적인 정보가 아니기 때문","mis":"K6-2-u3-X08"},{"t":"근거에 「단백질」이라는 낱말이 들어 있으니 이유를 충분히 뒷받침하기 때문","mis":"K6-2-u3-X25"},{"t":"현우의 주장이 틀렸다는 것이 다른 연구로 이미 밝혀졌기 때문","mis":"K6-2-u3-X20"}],"explanation":["현우의 근거는 단백질이 부족하면 충치 위험이 높아진다는 연구 결과예요.","이것은 단백질이 중요하다는 것을 보여 줘요.","「고기반찬으로만」 섭취할 수 있다는 이유를 보여 주지는 못해요."],"asset":{"type":"passage","lines":["기준 이유는 주장과 관련 있나요? — 윤정 ◎ · 현우 ◎","기준 많은 사람이 받아들일 만한 타당한 이유인가요? — 윤정 ◎ · 현우 △","기준 근거는 이유와 관련 있나요? — 윤정 ◎ · 현우 ○","기준 근거로 객관적인 사실이나 정보를 활용하나요? — 윤정 ◎ · 현우 ◎"],"numbered":false,"title":"이유와 근거의 타당성 판단 — 『국어』 126쪽 (2) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_challenge#4','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',3,'error','auto','두 친구의 주장하는 말을 평가하며 친구들이 말했어요. 평가하는 태도가 알맞지 않은 친구는 누구인가요?',ARRAY['K6-2-u3-X11','K6-2-u3-X02']::text[],false,'{"seq":4,"concept":"K6-2-u3-C7","difficulty":3,"kind":"error","stem":"두 친구의 주장하는 말을 평가하며 친구들이 말했어요. 평가하는 태도가 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 3 — 「현우의 말에는 보완할 점이 있으니 타당한 점은 찾을 필요가 없어.」","correct":true,"mis_target":"K6-2-u3-X11"},{"t":"친구 1 — 「현우는 객관적인 연구 결과를 근거로 든 점이 타당해.」","mis":"K6-2-u3-X02"},{"t":"친구 2 — 「윤정이는 채식이 우리 몸에 주는 좋은 점도 이유로 들면 더 좋겠어.」","mis":"K6-2-u3-X02"}],"explanation":["친구 1은 타당한 점을 찾았어요.","친구 2는 더 나아지게 할 보완할 점을 말했어요.","평가는 흠만 찾는 일이 아니라 타당한 점도 함께 찾는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_challenge#5','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C8',3,'mc','auto','우리 반 생각 발표회를 준비하며 조사한 자료를 근거로 쓸 때 해야 할 일은 무엇인가요?',ARRAY['K6-2-u3-X14','K6-2-u3-X13','K6-2-u3-X08']::text[],false,'{"seq":5,"concept":"K6-2-u3-C8","difficulty":3,"kind":"mc","stem":"우리 반 생각 발표회를 준비하며 조사한 자료를 근거로 쓸 때 해야 할 일은 무엇인가요?","options":[{"t":"조사한 자료가 어디에서 나왔는지 출처를 정확히 밝힌다","correct":true},{"t":"자료가 부족하면 더 큰 목소리로 되풀이해 말한다","mis":"K6-2-u3-X14"},{"t":"출처는 빼고 자료가 내 생각인 것처럼 말한다","mis":"K6-2-u3-X13"},{"t":"자료는 많을수록 좋으니 관련 없는 자료도 넣는다","mis":"K6-2-u3-X08"}],"explanation":["조사한 자료를 활용할 때는 출처를 정확히 밝혀요.","그래야 듣는 사람이 확인할 수 있어요.","근거는 이유와 관련 있는 것만 골라요."],"asset":{"type":"passage","lines":["문제 급식실에 한꺼번에 많은 학년이 몰려서 급식을 받는 데 오래 걸린다.","주장 학년별로 급식 시간을 조정하자.","이유 급식을 받는 데 오랜 시간을 기다리지 않아도 된다.","이유 식사 시간이 부족해져 건강과 학습에도 영향을 미칠 수 있다.","근거 학생 수가 많은 학교에서 급식 시간을 조정한 뒤","      식사 시간이 안정적으로 확보되었다는 사례가 있다.","근거 급식실이 혼잡하면 서둘러 식사를 하게 되어 소화 불량이나","      위장 장애가 발생할 가능성이 높다는 연구 결과가 있다."],"numbered":false,"title":"우리 반 생각 발표회 준비 예시 — 『국어』 127쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_challenge#6','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',3,'mc','auto','『국어』 128쪽 평가표 예시를 보고, 주장하는 말의 내용이 가장 타당한 친구를 고르세요.',ARRAY['K6-2-u3-X12','K6-2-u3-X11']::text[],false,'{"seq":6,"concept":"K6-2-u3-C7","difficulty":3,"kind":"mc","stem":"『국어』 128쪽 평가표 예시를 보고, 주장하는 말의 내용이 가장 타당한 친구를 고르세요.","options":[{"t":"김○○","correct":true},{"t":"박○○","mis":"K6-2-u3-X12"},{"t":"신○○","mis":"K6-2-u3-X12"},{"t":"세 친구 모두 같다","mis":"K6-2-u3-X11"}],"explanation":["김○○은 세 기준 모두 ◎를 받았어요.","박○○은 근거가 △, 신○○은 주장이 △예요.","그래서 김○○의 말이 가장 타당하다고 판단할 수 있어요."],"asset":{"type":"passage","lines":["기준 주장은 가치 있고 중요한가요? — 김○○ ◎ · 박○○ ◎ · 신○○ △","기준 이유는 주장을 적절하게 뒷받침하나요? — 김○○ ◎ · 박○○ ○ · 신○○ ◎","기준 근거는 이유를 적절하게 뒷받침하나요? — 김○○ ◎ · 박○○ △ · 신○○ ○"],"numbered":false,"title":"친구들의 주장하는 말 평가 — 『국어』 128쪽 (5) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_challenge#7','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',3,'ox','auto','「질 좋은 고기반찬으로만 성장에 필요한 단백질을 섭취할 수 있기 때문이다.」는 주장과 관련 있으므로 타당한 이유라고 할 수 있어요.',ARRAY['K6-2-u3-X24']::text[],false,'{"seq":7,"concept":"K6-2-u3-C7","difficulty":3,"kind":"ox","stem":"「질 좋은 고기반찬으로만 성장에 필요한 단백질을 섭취할 수 있기 때문이다.」는 주장과 관련 있으므로 타당한 이유라고 할 수 있어요.","answer":"X","reason_options":[{"t":"주장과 관련은 있지만, 단백질은 다른 음식으로도 섭취할 수 있어 많은 사람이 받아들이기 어렵기 때문에","correct":true},{"t":"주장과 관련만 있으면 이유는 언제나 타당하기 때문에","mis":"K6-2-u3-X24"}],"mis":"K6-2-u3-X24","explanation":["이유는 두 가지 물음을 함께 통과해야 해요.","주장과 관련 있는지, 많은 사람이 받아들일 만한지예요.","현우의 이유는 둘째 물음에서 부족해요."],"asset":{"type":"passage","lines":["주장 질 좋은 고기반찬을 더 충분히 제공하자.","이유 질 좋은 고기반찬으로만 성장에 필요한 단백질을 섭취할 수 있기 때문이다.","근거 단백질 섭취 부족 시 충치 발생 위험이 높아질 수 있다는 연구 결과가 있다."],"numbered":false,"title":"「용기초등학교 어린이 생각 발표회」 현우의 말 정리 — 『국어』 124쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_challenge#8','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',4,'essay','teacher','현우의 주장하는 말이 타당한지 이유와 근거의 판단 기준으로 판단하고, 『국어』 126쪽 (3)처럼 타당한 점과 보완할 점을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u3-C7","difficulty":4,"kind":"essay","stem":"현우의 주장하는 말이 타당한지 이유와 근거의 판단 기준으로 판단하고, 『국어』 126쪽 (3)처럼 타당한 점과 보완할 점을 쓰세요.","answer_guide":{"answer":"예: 이유는 주장과 관련 있지만 단백질은 콩, 두부, 달걀 등으로도 섭취할 수 있으므로 많은 사람이 받아들이기에는 부족하다. 근거는 객관적인 연구 결과이지만 단백질의 중요성만 설명해 이유와 관련성이 조금 떨어진다. 타당한 점 — 객관적인 연구 결과를 근거로 들었다. 보완할 점 — 주장을 뒷받침할 다른 이유와 근거를 더하면 좋겠다.","scoring_points":["이유를 두 기준으로 판단했는가","근거를 두 기준으로 판단했는가","타당한 점과 보완할 점을 함께 썼는가"]},"explanation":["이유 — 관련은 있으나 받아들이기 어려움.","근거 — 객관적이나 이유와 관련성이 약함.","타당한 점을 먼저, 보완할 점은 그다음."],"asset":{"type":"passage","lines":["주장 질 좋은 고기반찬을 더 충분히 제공하자.","이유 질 좋은 고기반찬으로만 성장에 필요한 단백질을 섭취할 수 있기 때문이다.","근거 단백질 섭취 부족 시 충치 발생 위험이 높아질 수 있다는 연구 결과가 있다."],"numbered":false,"title":"「용기초등학교 어린이 생각 발표회」 현우의 말 정리 — 『국어』 124쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_challenge#9','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C8',4,'essay','teacher','『국어』 127쪽처럼 학교에서 해결하고 싶은 문제 하나를 정해 주장, 이유, 근거를 정리하세요. 근거는 어디에서 나온 자료인지 밝히는 방법도 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C8","difficulty":4,"kind":"essay","stem":"『국어』 127쪽처럼 학교에서 해결하고 싶은 문제 하나를 정해 주장, 이유, 근거를 정리하세요. 근거는 어디에서 나온 자료인지 밝히는 방법도 함께 쓰세요.","answer_guide":{"answer":"예: 문제 — 급식실에 한꺼번에 많은 학년이 몰려 급식을 받는 데 오래 걸린다. 주장 — 학년별로 급식 시간을 조정하자. 이유 — 급식을 받는 데 오랜 시간을 기다리지 않아도 되기 때문이다. 근거 — 학생 수가 많은 학교에서 급식 시간을 조정한 뒤 식사 시간이 안정적으로 확보되었다는 사례가 있다. 발표할 때에는 그 사례가 실린 기사나 자료의 이름을 함께 말하겠다.","scoring_points":["해결하고 싶은 문제와 주장을 썼는가","주장과 관련 있는 이유와 근거를 썼는가","출처를 밝히는 방법을 썼는가"]},"explanation":["주장은 가치 있고 실천할 수 있게 정해요.","이유와 근거도 판단 기준을 떠올리며 정리해요.","조사한 자료는 출처를 정확히 밝혀요."],"asset":{"type":"passage","lines":["문제 급식실에 한꺼번에 많은 학년이 몰려서 급식을 받는 데 오래 걸린다.","주장 학년별로 급식 시간을 조정하자.","이유 급식을 받는 데 오랜 시간을 기다리지 않아도 된다.","이유 식사 시간이 부족해져 건강과 학습에도 영향을 미칠 수 있다.","근거 학생 수가 많은 학교에서 급식 시간을 조정한 뒤","      식사 시간이 안정적으로 확보되었다는 사례가 있다.","근거 급식실이 혼잡하면 서둘러 식사를 하게 되어 소화 불량이나","      위장 장애가 발생할 가능성이 높다는 연구 결과가 있다."],"numbered":false,"title":"우리 반 생각 발표회 준비 예시 — 『국어』 127쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L04_challenge#10','kor',6,2,'u3','L04','tb_g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',4,'essay','teacher','『국어』 128쪽 평가표 예시를 보고, 주장하는 말의 내용이 가장 타당한 친구의 이름과 그 까닭을 쓰세요. 그리고 다른 두 친구에게 해 줄 말을 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C7","difficulty":4,"kind":"essay","stem":"『국어』 128쪽 평가표 예시를 보고, 주장하는 말의 내용이 가장 타당한 친구의 이름과 그 까닭을 쓰세요. 그리고 다른 두 친구에게 해 줄 말을 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 가장 타당한 친구는 김○○이다. 우리 학교 학생들이 점심시간을 알차게 쓰도록 돕는 가치 있는 주장이고, 주장을 뒷받침하는 이유를 잘 들었으며, 실제 사례와 연구 결과를 근거로 이유를 적절하게 뒷받침했다. 박○○에게는 이유를 뒷받침할 근거를 더 찾아보자고, 신○○에게는 주장이 학교생활에 도움이 되고 실천할 수 있게 다듬어 보자고 말하겠다.","scoring_points":["가장 타당한 친구를 바르게 골랐는가","세 기준에 따라 까닭을 썼는가","다른 친구에게 보완할 점을 알려 주었는가"]},"explanation":["세 기준을 차례로 견주어요.","판단한 까닭을 간단히 정리해요.","다른 친구에게는 보완할 점을 알려 줘요."],"asset":{"type":"passage","lines":["기준 주장은 가치 있고 중요한가요? — 김○○ ◎ · 박○○ ◎ · 신○○ △","기준 이유는 주장을 적절하게 뒷받침하나요? — 김○○ ◎ · 박○○ ○ · 신○○ ◎","기준 근거는 이유를 적절하게 뒷받침하나요? — 김○○ ◎ · 박○○ △ · 신○○ ○"],"numbered":false,"title":"친구들의 주장하는 말 평가 — 『국어』 128쪽 (5) 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_basic#1','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',1,'mc','auto','주제가 「환경 보호」인 영상들의 미리 보기 제목이에요. 무엇을 하자는 주장이 가장 뚜렷하게 담긴 영상은 어느 것인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":1,"concept":"K6-2-u3-C9","difficulty":1,"kind":"mc","stem":"주제가 「환경 보호」인 영상들의 미리 보기 제목이에요. 무엇을 하자는 주장이 가장 뚜렷하게 담긴 영상은 어느 것인가요?","options":[{"t":"플라스틱은 지구를 망친다! 당장 줄여야 하는 이유","correct":true},{"t":"이 나라에서는 플라스틱 이렇게 줄였다.","mis":"K6-2-u3-X15"},{"t":"일주일 동안 플라스틱 없이 살아 본 결과","mis":"K6-2-u3-X15"},{"t":"일회용 컵 사용, 정말 줄일 수 있을까?","mis":"K6-2-u3-X15"}],"explanation":["「당장 줄여야 하는 이유」는 플라스틱을 줄이자는 주장과 그 이유를 말하겠다는 제목이에요.","다른 나라의 사례나 체험 결과를 알려 주는 제목은 정보를 전하는 쪽에 가까워요.","물음 꼴의 제목은 주장보다 궁금증을 먼저 드러내요."],"asset":{"type":"passage","lines":["● 일회용 컵 사용, 정말 줄일 수 있을까?","● 플라스틱은 지구를 망친다! 당장 줄여야 하는 이유","● 이 나라에서는 플라스틱 이렇게 줄였다.","● 일주일 동안 플라스틱 없이 살아 본 결과"],"numbered":false,"title":"주제가 「환경 보호」인 영상들의 미리 보기 제목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_basic#2','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C18',1,'sa','auto','『국어』 130쪽 4번에서 쓴 「낭독의 재발견」의 주장이에요. 「낭독은 글의 내용을 잘 (    )하는 데 도움을 준다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C18","difficulty":1,"kind":"sa","stem":"『국어』 130쪽 4번에서 쓴 「낭독의 재발견」의 주장이에요. 「낭독은 글의 내용을 잘 (    )하는 데 도움을 준다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["이해"],"explanation":["제목, 자료, 강조한 표현을 합쳐 주장을 세워요.","영상은 낭독이 집중력과 기억력에 도움이 된다고 보여 줘요.","그래서 주장은 「낭독은 글의 내용을 잘 이해하는 데 도움을 준다」예요."],"asset":{"type":"passage","lines":["[장면] 책에 집중하지 못하는 시대","[장면] 캐나다 사람들을 대상으로 설문과 뇌파 측정 연구를 한 결과","[장면] 낭랑하게 목청을 돋우고 가락에 맞추어 책을 읽다 보면","[장면] ‘입, 몸, 마음’이라는 낱말을 굵은 글자로 강조한다."],"numbered":false,"title":"영상 「낭독의 재발견」의 장면 — 『국어』 129~130쪽"},"mis":"K6-2-u3-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_basic#3','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',1,'mc','auto','『국어』 129쪽 2번에서 영상의 주장을 파악할 때 살펴볼 점으로 친구들이 말하지 않은 것은 무엇인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":3,"concept":"K6-2-u3-C9","difficulty":1,"kind":"mc","stem":"『국어』 129쪽 2번에서 영상의 주장을 파악할 때 살펴볼 점으로 친구들이 말하지 않은 것은 무엇인가요?","options":[{"t":"영상의 길이가 몇 분인지","correct":true},{"t":"영상의 제목이 무엇을 뜻하는지","mis":"K6-2-u3-X15"},{"t":"영상에서 사용한 자료","mis":"K6-2-u3-X15"},{"t":"음악이나 자막 같은 효과로 강조하는 장면이나 표현","mis":"K6-2-u3-X15"}],"explanation":["친구들은 제목, 자료, 강조하는 장면이나 표현을 살펴보자고 했어요.","영상의 길이는 주장과 관계가 없어요.","세 가지를 합쳐야 주장을 찾을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_basic#4','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C19',1,'ox','auto','「나를 성장시키는 기록법」에서 「적자! 생존」은 「잘 적는 사람이 성장할 수 있다」는 뜻으로 표현한 거예요.',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":4,"concept":"K6-2-u3-C19","difficulty":1,"kind":"ox","stem":"「나를 성장시키는 기록법」에서 「적자! 생존」은 「잘 적는 사람이 성장할 수 있다」는 뜻으로 표현한 거예요.","answer":"O","reason_options":[{"t":"‘적자생존’이라는 사자성어의 원래 뜻 대신 기록의 중요성을 드러내려고 바꾸어 썼기 때문에","correct":true},{"t":"사자성어는 언제나 원래 뜻으로만 쓰이기 때문에","mis":"K6-2-u3-X15"}],"mis":"K6-2-u3-X15","explanation":["영상은 「적자! 생존」이라는 표현을 강조했어요.","원래 뜻 대신 「잘 적는 사람이 성장할 수 있다」는 뜻으로 썼어요.","강조한 표현에서 영상의 주장을 짐작할 수 있어요."],"asset":{"type":"passage","lines":["1 제목 — 나를 성장시키는 기록법","2 열심히 받아 적었는데도 뒤돌아서면 기억하지 못한다.","3 정약용이 활용한 수사차록법","4 이순신의 「난중일기」 — 업무를 정리하고 작전을 세우며 생각을 정리한 기록","5 천재로 불렸던 인물들의 공통점 — 떠오르는 생각을 종이에 기록하는 능력","6 「적자! 생존」 — 잘 적는 사람이 살아남는 현상?"],"numbered":false,"title":"영상 「나를 성장시키는 기록법」의 장면 — 『국어』 131쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_basic#5','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C18',2,'mc','auto','「낭독의 재발견」의 제목을 이렇게 정한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":5,"concept":"K6-2-u3-C18","difficulty":2,"kind":"mc","stem":"「낭독의 재발견」의 제목을 이렇게 정한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"오래된 방법이라 여긴 낭독의 효과를 다시 알려 주려고","correct":true},{"t":"낭독을 처음 시작한 사람이 누구인지 소개하려고","mis":"K6-2-u3-X15"},{"t":"책을 빨리 많이 읽는 새로운 방법을 알려 주려고","mis":"K6-2-u3-X15"},{"t":"캐나다 사람들이 책 읽는 생활을 보여 주려고","mis":"K6-2-u3-X15"}],"explanation":["「재발견」은 이미 있던 것의 가치를 다시 찾는다는 뜻이에요.","규민이는 낭독의 효과를 다시 한번 알려 주려는 것이라고 했어요.","제목에는 만든 사람의 관점이 드러나요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"영상의 제목을 ‘낭독의 재발견’으로 정한 까닭은 무엇일까?"},{"who":"규민","text":"오래된 방법이라고 생각했던 낭독의 효과를 다시 한번 알려 주기 위해서야."},{"who":"지호","text":"인간의 집중력이 점점 떨어지고 있다는 실험 결과를 보여 주는 자료를 제시한 까닭은 무엇일까?"},{"who":"규민","text":"집중력과 기억력 향상에 도움이 되는 낭독의 필요성을 보여 주는 정보를 제시하고 싶었기 때문이야."},{"who":"지호","text":"영상에서 ‘입, 몸, 마음’이라는 낱말을 굵은 글자로 강조한 까닭은 무엇일까?"},{"who":"규민","text":"낭독의 긍정적인 효과를 강조해서 표현하기 위해서야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_basic#6','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C18',2,'mc','auto','「낭독의 재발견」에서 캐나다 사람들을 대상으로 한 설문과 뇌파 측정 연구 결과를 제시한 까닭은 무엇인가요?',ARRAY['K6-2-u3-X15','K6-2-u3-X21']::text[],false,'{"seq":6,"concept":"K6-2-u3-C18","difficulty":2,"kind":"mc","stem":"「낭독의 재발견」에서 캐나다 사람들을 대상으로 한 설문과 뇌파 측정 연구 결과를 제시한 까닭은 무엇인가요?","options":[{"t":"집중력과 기억력에 도움이 되는 낭독이 필요함을 보여 주려고","correct":true},{"t":"캐나다가 세계에서 책을 가장 많이 읽는 나라임을 알리려고","mis":"K6-2-u3-X15"},{"t":"뇌파를 재는 기계를 다루는 방법을 가르쳐 주려고","mis":"K6-2-u3-X15"},{"t":"연구 장면을 넣어 영상을 더 길고 화려하게 만들려고","mis":"K6-2-u3-X21"}],"explanation":["연구 결과는 사람들의 집중력이 점점 떨어지고 있다는 것을 보여 줘요.","그래서 집중력과 기억력에 도움이 되는 낭독이 필요하다는 것이에요.","자료는 주장을 뒷받침하려고 넣어요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"영상의 제목을 ‘낭독의 재발견’으로 정한 까닭은 무엇일까?"},{"who":"규민","text":"오래된 방법이라고 생각했던 낭독의 효과를 다시 한번 알려 주기 위해서야."},{"who":"지호","text":"인간의 집중력이 점점 떨어지고 있다는 실험 결과를 보여 주는 자료를 제시한 까닭은 무엇일까?"},{"who":"규민","text":"집중력과 기억력 향상에 도움이 되는 낭독의 필요성을 보여 주는 정보를 제시하고 싶었기 때문이야."},{"who":"지호","text":"영상에서 ‘입, 몸, 마음’이라는 낱말을 굵은 글자로 강조한 까닭은 무엇일까?"},{"who":"규민","text":"낭독의 긍정적인 효과를 강조해서 표현하기 위해서야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_basic#7','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',2,'blank','auto','『국어』 133쪽 6번에서 정리한 영상의 주장을 파악하는 방법이에요. 「영상에서 제시한 (    )의 내용을 파악한다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u3-X15','K6-2-u3-X03']::text[],false,'{"seq":7,"concept":"K6-2-u3-C9","difficulty":2,"kind":"blank","stem":"『국어』 133쪽 6번에서 정리한 영상의 주장을 파악하는 방법이에요. 「영상에서 제시한 (    )의 내용을 파악한다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"자료","correct":true},{"t":"길이","mis":"K6-2-u3-X15"},{"t":"배경 색","mis":"K6-2-u3-X15"},{"t":"조회 수","mis":"K6-2-u3-X03"}],"explanation":["영상은 주장을 직접 말하기보다 자료를 보여 줘요.","그 자료가 어떤 주장을 뒷받침하려고 나왔는지 파악해요.","제목, 자료, 강조하는 장면이나 표현을 함께 살펴요."],"asset":{"type":"passage","lines":["● 영상의 제목을 살펴보고 그렇게 정한 까닭을 생각해 본다.","● 영상에서 제시한 자료의 내용을 파악한다.","● 영상에서 강조하는 장면이나 표현이 무엇인지 찾고","  그렇게 표현한 까닭을 생각해 본다."],"numbered":false,"title":"영상의 주장을 파악하는 방법 — 『국어』 133쪽 6번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_basic#8','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C19',2,'mc','auto','「나를 성장시키는 기록법」의 장면 2에서 열심히 받아 적었는데도 뒤돌아서면 기억하지 못한 까닭은 무엇인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X04','K6-2-u3-X15']::text[],false,'{"seq":8,"concept":"K6-2-u3-C19","difficulty":2,"kind":"mc","stem":"「나를 성장시키는 기록법」의 장면 2에서 열심히 받아 적었는데도 뒤돌아서면 기억하지 못한 까닭은 무엇인가요?","options":[{"t":"이해하거나 생각하지 않고 있는 그대로 받아 적었기 때문","correct":true},{"t":"받아 적은 양이 너무 적어 빠진 내용이 많았기 때문","mis":"K6-2-u3-X08"},{"t":"손이 느려서 너무 천천히 받아 적었기 때문","mis":"K6-2-u3-X04"},{"t":"적은 것을 다른 사람에게 한 번도 보여 주지 않았기 때문","mis":"K6-2-u3-X15"}],"explanation":["영상은 이해하지 않고, 생각하지 않고 오로지 적기만 했다고 보여 줘요.","그대로 받아 적기만 하면 기억에 남지 않아요.","생각을 함께 적어야 한다는 주장으로 이어져요."],"asset":{"type":"passage","lines":["1 제목 — 나를 성장시키는 기록법","2 열심히 받아 적었는데도 뒤돌아서면 기억하지 못한다.","3 정약용이 활용한 수사차록법","4 이순신의 「난중일기」 — 업무를 정리하고 작전을 세우며 생각을 정리한 기록","5 천재로 불렸던 인물들의 공통점 — 떠오르는 생각을 종이에 기록하는 능력","6 「적자! 생존」 — 잘 적는 사람이 살아남는 현상?"],"numbered":false,"title":"영상 「나를 성장시키는 기록법」의 장면 — 『국어』 131쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_basic#9','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',2,'match','auto','영상의 주장을 파악할 때 살펴보는 요소와 「낭독의 재발견」에서 찾은 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C9","difficulty":2,"kind":"match","stem":"영상의 주장을 파악할 때 살펴보는 요소와 「낭독의 재발견」에서 찾은 내용을 알맞게 이으세요.","pairs":[{"l":"제목","r":"‘낭독의 재발견’"},{"l":"제시한 자료","r":"캐나다 사람들을 대상으로 한 설문과 뇌파 측정 연구 결과"},{"l":"강조한 표현","r":"굵은 글자로 쓴 ‘입, 몸, 마음’"}],"mis":"K6-2-u3-X15","explanation":["제목은 낭독의 효과를 다시 알리려는 뜻을 담았어요.","자료는 집중력이 떨어지고 있다는 것을 보여 줘요.","굵은 글자는 낭독의 좋은 점을 강조해요."],"asset":{"type":"passage","lines":["[장면] 책에 집중하지 못하는 시대","[장면] 캐나다 사람들을 대상으로 설문과 뇌파 측정 연구를 한 결과","[장면] 낭랑하게 목청을 돋우고 가락에 맞추어 책을 읽다 보면","[장면] ‘입, 몸, 마음’이라는 낱말을 굵은 글자로 강조한다."],"numbered":false,"title":"영상 「낭독의 재발견」의 장면 — 『국어』 129~130쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_basic#10','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C19',3,'essay','teacher','「나를 성장시키는 기록법」의 주장을 한 문장으로 쓰고, 그 주장을 뒷받침하는 장면을 두 가지 찾아 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C19","difficulty":3,"kind":"essay","stem":"「나를 성장시키는 기록법」의 주장을 한 문장으로 쓰고, 그 주장을 뒷받침하는 장면을 두 가지 찾아 쓰세요.","answer_guide":{"answer":"예: 주장 — 생각을 함께 적은 기록은 자신을 성장시킨다. 장면 — 정약용은 중요하다고 생각하는 부분을 베껴 쓰되 자신의 생각을 덧붙여 기록하는 수사차록법을 활용했다. 이순신은 「난중일기」로 업무와 자신의 생각을 정리해 최고의 전략을 이끌었다.","scoring_points":["주장을 한 문장으로 바르게 썼는가","주장을 뒷받침하는 장면을 두 가지 썼는가","장면과 주장을 이어 설명했는가"]},"explanation":["제목은 「나를 성장시키는」 기록을 말해요.","정약용과 이순신의 기록은 생각을 함께 적은 기록이에요.","여러 장면을 합쳐 주장을 세워요."],"asset":{"type":"passage","lines":["1 제목 — 나를 성장시키는 기록법","2 열심히 받아 적었는데도 뒤돌아서면 기억하지 못한다.","3 정약용이 활용한 수사차록법","4 이순신의 「난중일기」 — 업무를 정리하고 작전을 세우며 생각을 정리한 기록","5 천재로 불렸던 인물들의 공통점 — 떠오르는 생각을 종이에 기록하는 능력","6 「적자! 생존」 — 잘 적는 사람이 살아남는 현상?"],"numbered":false,"title":"영상 「나를 성장시키는 기록법」의 장면 — 『국어』 131쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_challenge#1','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C10',2,'mc','auto','「나를 성장시키는 기록법」에서 배경 음악과 자막 효과는 영상의 주장에 어떤 도움을 주나요?',ARRAY['K6-2-u3-X17','K6-2-u3-X15']::text[],false,'{"seq":1,"concept":"K6-2-u3-C10","difficulty":2,"kind":"mc","stem":"「나를 성장시키는 기록법」에서 배경 음악과 자막 효과는 영상의 주장에 어떤 도움을 주나요?","options":[{"t":"중요한 내용에서 음악이 멈추거나 자막이 강조되어 그 부분에 집중하게 한다","correct":true},{"t":"음악이 커질수록 영상의 주장이 사실이라는 것을 보여 준다","mis":"K6-2-u3-X17"},{"t":"자막은 영상이 얼마나 긴지와 몇 번째 장면인지를 알려 준다","mis":"K6-2-u3-X15"},{"t":"음악과 자막은 분위기만 꾸밀 뿐 주장과 아무 관계가 없다","mis":"K6-2-u3-X15"}],"explanation":["영상은 음악이나 자막으로 하고 싶은 말을 강조해요.","중요한 내용에서 음악이 멈추거나 자막이 커지면 그 부분에 집중하게 돼요.","강조는 주장을 찾는 실마리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_challenge#2','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C19',2,'sa','auto','「나를 성장시키는 기록법」에서 정약용이 활용한 기록 방법의 이름을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C19","difficulty":2,"kind":"sa","stem":"「나를 성장시키는 기록법」에서 정약용이 활용한 기록 방법의 이름을 쓰세요.","answer":["수사차록법"],"explanation":["영상의 장면 3에는 정약용의 기록 방법이 나와요.","중요하다고 생각하는 부분을 베껴 쓰되 생각을 덧붙여 기록하는 방법이에요.","이 방법의 이름은 수사차록법이에요."],"asset":{"type":"passage","lines":["1 제목 — 나를 성장시키는 기록법","2 열심히 받아 적었는데도 뒤돌아서면 기억하지 못한다.","3 정약용이 활용한 수사차록법","4 이순신의 「난중일기」 — 업무를 정리하고 작전을 세우며 생각을 정리한 기록","5 천재로 불렸던 인물들의 공통점 — 떠오르는 생각을 종이에 기록하는 능력","6 「적자! 생존」 — 잘 적는 사람이 살아남는 현상?"],"numbered":false,"title":"영상 「나를 성장시키는 기록법」의 장면 — 『국어』 131쪽"},"mis":"K6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_challenge#3','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',3,'mc','auto','영상에서 주장을 직접 말하지 않을 때에는 어떻게 해야 하나요?',ARRAY['K6-2-u3-X16','K6-2-u3-X15']::text[],false,'{"seq":3,"concept":"K6-2-u3-C9","difficulty":3,"kind":"mc","stem":"영상에서 주장을 직접 말하지 않을 때에는 어떻게 해야 하나요?","options":[{"t":"제시한 자료와 강조한 표현을 바탕으로 보는 사람이 주장을 추론한다","correct":true},{"t":"주장을 말하지 않았으니 주장이 없는 영상으로 본다","mis":"K6-2-u3-X16"},{"t":"제목 하나만 보고 주장을 정한다","mis":"K6-2-u3-X15"},{"t":"가장 길게 나온 장면을 주장으로 본다","mis":"K6-2-u3-X15"}],"explanation":["영상은 주장을 직접 말하기보다 자료를 보여 주는 경우가 많아요.","보는 사람이 자료를 바탕으로 주장을 추론해야 해요.","제목, 자료, 강조를 함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_challenge#4','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C10',3,'error','auto','영상의 강조 효과에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X15']::text[],false,'{"seq":4,"concept":"K6-2-u3-C10","difficulty":3,"kind":"error","stem":"영상의 강조 효과에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「자막이 여러 번 되풀이되었으니 그 말은 틀림없이 사실이야.」","correct":true,"mis_target":"K6-2-u3-X17"},{"t":"친구 1 — 「되풀이된 낱말을 보면 영상이 무엇을 강조하는지 알 수 있어.」","mis":"K6-2-u3-X15"},{"t":"친구 2 — 「음악이 멈추는 장면은 중요한 내용이 나오는 자리일 수 있어.」","mis":"K6-2-u3-X15"}],"explanation":["되풀이되는 낱말이나 음악이 멈추는 자리는 강조하는 곳이에요.","강조는 무엇을 말하고 싶은지 알려 줘요.","그 말이 사실인지는 자료로 따로 따져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_challenge#5','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C19',3,'mc','auto','「나를 성장시키는 기록법」에서 이순신은 「난중일기」를 통해 어떤 것을 얻었나요?',ARRAY['K6-2-u3-X15','K6-2-u3-X04']::text[],false,'{"seq":5,"concept":"K6-2-u3-C19","difficulty":3,"kind":"mc","stem":"「나를 성장시키는 기록법」에서 이순신은 「난중일기」를 통해 어떤 것을 얻었나요?","options":[{"t":"업무를 정리하고 자신의 생각을 정리해 최고의 전략을 이끌었다","correct":true},{"t":"그날 있었던 일을 생각 없이 그대로 베껴 두었다","mis":"K6-2-u3-X15"},{"t":"일기를 쓰지 않아도 모든 것을 기억할 수 있었다","mis":"K6-2-u3-X04"},{"t":"다른 사람의 일기를 모아 책으로 냈다","mis":"K6-2-u3-X15"}],"explanation":["「난중일기」는 업무를 정리하고 작전을 세우며 생각을 정리한 기록이에요.","이순신은 그 기록으로 최고의 전략을 이끌었어요.","생각을 함께 적은 기록이 사람을 성장시킨다는 주장을 뒷받침해요."],"asset":{"type":"passage","lines":["1 제목 — 나를 성장시키는 기록법","2 열심히 받아 적었는데도 뒤돌아서면 기억하지 못한다.","3 정약용이 활용한 수사차록법","4 이순신의 「난중일기」 — 업무를 정리하고 작전을 세우며 생각을 정리한 기록","5 천재로 불렸던 인물들의 공통점 — 떠오르는 생각을 종이에 기록하는 능력","6 「적자! 생존」 — 잘 적는 사람이 살아남는 현상?"],"numbered":false,"title":"영상 「나를 성장시키는 기록법」의 장면 — 『국어』 131쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_challenge#6','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C19',3,'mc','auto','「나를 성장시키는 기록법」에서 여러 인물과 상황을 보여 주며 되풀이해 나오는 낱말로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X15','K6-2-u3-X01']::text[],false,'{"seq":6,"concept":"K6-2-u3-C19","difficulty":3,"kind":"mc","stem":"「나를 성장시키는 기록법」에서 여러 인물과 상황을 보여 주며 되풀이해 나오는 낱말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"생각 · 기록 · 습관","correct":true},{"t":"캐나다 · 뇌파 · 설문","mis":"K6-2-u3-X15"},{"t":"입 · 몸 · 마음","mis":"K6-2-u3-X15"},{"t":"나이 · 장애 · 종교","mis":"K6-2-u3-X01"}],"explanation":["영상은 여러 인물을 보여 주며 같은 낱말을 되풀이해요.","「생각, 기록, 습관」이 되풀이되며 강조돼요.","생각을 기록하는 습관이 나를 성장시킨다는 주장으로 모여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_challenge#7','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C18',3,'ox','auto','「낭독의 재발견」에서 ‘입, 몸, 마음’을 굵은 글자로 쓴 까닭은 낭독의 긍정적인 효과를 강조하려는 거예요.',ARRAY['K6-2-u3-X17']::text[],false,'{"seq":7,"concept":"K6-2-u3-C18","difficulty":3,"kind":"ox","stem":"「낭독의 재발견」에서 ‘입, 몸, 마음’을 굵은 글자로 쓴 까닭은 낭독의 긍정적인 효과를 강조하려는 거예요.","answer":"O","reason_options":[{"t":"굵은 글자는 만든 사람이 꼭 전하고 싶은 내용을 드러내는 강조 표현이기 때문에","correct":true},{"t":"굵은 글자로 쓴 말은 그 자체로 사실이라는 증거이기 때문에","mis":"K6-2-u3-X17"}],"mis":"K6-2-u3-X17","explanation":["규민이는 낭독의 긍정적인 효과를 강조해서 표현하려는 것이라고 했어요.","굵은 글자는 강조하는 표현이에요.","강조된 표현은 주장을 찾는 실마리가 돼요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"영상의 제목을 ‘낭독의 재발견’으로 정한 까닭은 무엇일까?"},{"who":"규민","text":"오래된 방법이라고 생각했던 낭독의 효과를 다시 한번 알려 주기 위해서야."},{"who":"지호","text":"인간의 집중력이 점점 떨어지고 있다는 실험 결과를 보여 주는 자료를 제시한 까닭은 무엇일까?"},{"who":"규민","text":"집중력과 기억력 향상에 도움이 되는 낭독의 필요성을 보여 주는 정보를 제시하고 싶었기 때문이야."},{"who":"지호","text":"영상에서 ‘입, 몸, 마음’이라는 낱말을 굵은 글자로 강조한 까닭은 무엇일까?"},{"who":"규민","text":"낭독의 긍정적인 효과를 강조해서 표현하기 위해서야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_challenge#8','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',4,'essay','teacher','영상의 주장을 파악하는 방법 세 가지를 쓰고, 그 방법으로 「낭독의 재발견」의 주장을 찾아 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u3-C9","difficulty":4,"kind":"essay","stem":"영상의 주장을 파악하는 방법 세 가지를 쓰고, 그 방법으로 「낭독의 재발견」의 주장을 찾아 쓰세요.","answer_guide":{"answer":"예: 영상의 제목을 살펴보고 그렇게 정한 까닭을 생각해 보고, 영상에서 제시한 자료의 내용을 파악하고, 영상에서 강조하는 장면이나 표현을 찾아 그렇게 표현한 까닭을 생각해 본다. 「낭독의 재발견」은 제목으로 낭독의 효과를 다시 알리려 하고, 집중력이 떨어지고 있다는 연구 결과를 보여 주며, ‘입, 몸, 마음’을 굵은 글자로 강조했다. 그래서 주장은 「낭독은 글의 내용을 잘 이해하는 데 도움을 준다」이다.","scoring_points":["방법 세 가지(제목·자료·강조)를 썼는가","「낭독의 재발견」에 방법을 적용했는가","주장을 한 문장으로 썼는가"]},"explanation":["제목 — 그렇게 정한 까닭.","자료 — 무엇을 보여 주려는지.","강조 — 그렇게 표현한 까닭."],"asset":{"type":"speech","turns":[{"who":"지호","text":"영상의 제목을 ‘낭독의 재발견’으로 정한 까닭은 무엇일까?"},{"who":"규민","text":"오래된 방법이라고 생각했던 낭독의 효과를 다시 한번 알려 주기 위해서야."},{"who":"지호","text":"인간의 집중력이 점점 떨어지고 있다는 실험 결과를 보여 주는 자료를 제시한 까닭은 무엇일까?"},{"who":"규민","text":"집중력과 기억력 향상에 도움이 되는 낭독의 필요성을 보여 주는 정보를 제시하고 싶었기 때문이야."},{"who":"지호","text":"영상에서 ‘입, 몸, 마음’이라는 낱말을 굵은 글자로 강조한 까닭은 무엇일까?"},{"who":"규민","text":"낭독의 긍정적인 효과를 강조해서 표현하기 위해서야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_challenge#9','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C19',4,'essay','teacher','「나를 성장시키는 기록법」의 장면 5와 장면 6이 각각 무엇을 보여 주는지 쓰고, 두 장면이 영상의 주장과 어떻게 이어지는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C19","difficulty":4,"kind":"essay","stem":"「나를 성장시키는 기록법」의 장면 5와 장면 6이 각각 무엇을 보여 주는지 쓰고, 두 장면이 영상의 주장과 어떻게 이어지는지 쓰세요.","answer_guide":{"answer":"예: 장면 5는 천재로 불렸던 인물들이 모두 떠오르는 생각을 종이에 기록하는 습관이 있었다는 것을 보여 준다. 기록이 자신의 생각을 정리하고 발전시키는 데 도움이 되었기 때문이다. 장면 6은 「적자! 생존」을 강조해 잘 적는 사람이 성장할 수 있다는 뜻을 드러낸다. 두 장면은 생각을 함께 적은 기록이 자신을 성장시킨다는 주장을 뒷받침한다.","scoring_points":["장면 5의 내용을 썼는가","장면 6의 강조 표현의 뜻을 썼는가","두 장면을 주장과 이어 설명했는가"]},"explanation":["장면 5는 자료로 주장을 뒷받침해요.","장면 6은 강조한 표현으로 주장을 드러내요.","자료와 강조를 합쳐 주장을 세워요."],"asset":{"type":"passage","lines":["1 제목 — 나를 성장시키는 기록법","2 열심히 받아 적었는데도 뒤돌아서면 기억하지 못한다.","3 정약용이 활용한 수사차록법","4 이순신의 「난중일기」 — 업무를 정리하고 작전을 세우며 생각을 정리한 기록","5 천재로 불렸던 인물들의 공통점 — 떠오르는 생각을 종이에 기록하는 능력","6 「적자! 생존」 — 잘 적는 사람이 살아남는 현상?"],"numbered":false,"title":"영상 「나를 성장시키는 기록법」의 장면 — 『국어』 131쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L07_challenge#10','kor',6,2,'u3','L07','tb_g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C10',4,'essay','teacher','영상에서 음악을 멈추거나 자막을 되풀이하는 강조 효과가 주장을 파악하는 데 어떤 도움을 주는지 쓰고, 그래도 주장이 타당한지는 무엇으로 따져야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C10","difficulty":4,"kind":"essay","stem":"영상에서 음악을 멈추거나 자막을 되풀이하는 강조 효과가 주장을 파악하는 데 어떤 도움을 주는지 쓰고, 그래도 주장이 타당한지는 무엇으로 따져야 하는지 쓰세요.","answer_guide":{"answer":"예: 음악을 멈추거나 자막을 되풀이하는 장면은 만든 사람이 가장 전하고 싶은 내용이 나오는 곳이어서 주장을 쉽게 찾게 해 준다. 하지만 강조가 세다고 그 말이 타당한 것은 아니다. 주장이 타당한지는 주장이 가치 있고 중요한지, 이유와 근거가 주장과 이유를 적절하게 뒷받침하는지로 따져야 한다.","scoring_points":["강조 효과가 주장 찾기에 주는 도움을 썼는가","강조와 타당성을 갈랐는가","타당성을 따지는 기준을 썼는가"]},"explanation":["강조는 무엇을 말하고 싶은지 알려 줘요.","주장을 찾는 일과 타당한지 따지는 일은 달라요.","타당성은 주장·이유·근거 기준으로 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_basic#1','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C20',1,'mc','auto','카드 뉴스 「무분별한 혐오·차별 표현은 이제 그만!」의 주장은 무엇인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":1,"concept":"K6-2-u3-C20","difficulty":1,"kind":"mc","stem":"카드 뉴스 「무분별한 혐오·차별 표현은 이제 그만!」의 주장은 무엇인가요?","options":[{"t":"혐오·차별 표현을 멈추어야 한다","correct":true},{"t":"혐오·차별 표현은 많은 사람이 겪고 있다","mis":"K6-2-u3-X01"},{"t":"독일은 혐오·차별 표현을 형법으로 규제한다","mis":"K6-2-u3-X01"},{"t":"‘살색’을 ‘살구색’으로 바꾸어 쓴다","mis":"K6-2-u3-X01"}],"explanation":["주장은 카드 뉴스의 제목과 강조하는 내용에서 확인해요.","「많은 사람이 겪고 있다」는 멈추어야 하는 이유예요.","독일의 규제나 살구색은 이유를 뒷받침하려고 든 근거예요."],"asset":{"type":"passage","lines":["셋째 장 [왜 멈추어야 할까요?] 특정 집단에 대한 부정적 인식을 강화할 수 있기 때문","      [사례] ‘살색’ → ‘살구색’(피부색에 대한 편견과 차별이 생길 수 있어 바꿈)","넷째 장 [왜 멈추어야 할까요?] 많은 사람이 겪고 있기 때문","      [그래프] 국가인권위원회 조사 — 참여자의 70.3퍼센트가 경험함","다섯째 장 [왜 멈추어야 할까요?] 인간의 존엄성을 침해하고 사회적 갈등을 초래하기 때문","      [사례] 독일은 형법으로, 캐나다는 인권법으로 규제 · 우리나라도 제도 마련","여섯째 장 혐오·차별 표현을 멈추는 것이 서로를 존중하는 사회로 나아가는 첫걸음"],"numbered":false,"title":"같은 카드 뉴스 셋째~여섯째 장 간추림 — 『국어』 135~136쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_basic#2','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C21',1,'sa','auto','카드 뉴스 낱말 알기에서 「바람직하지 않은 일을 더 심해지도록 부추김.」이라는 뜻을 가진 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C21","difficulty":1,"kind":"sa","stem":"카드 뉴스 낱말 알기에서 「바람직하지 않은 일을 더 심해지도록 부추김.」이라는 뜻을 가진 낱말을 쓰세요.","answer":["조장"],"explanation":["<보기>에는 강화, 규제, 조장, 침해가 있어요.","바람직하지 않은 일을 부추기는 것은 조장이에요.","「친구를 따돌리는 행동을 조장하면」처럼 써요."],"asset":{"type":"passage","lines":["● 강화: 세력이나 힘을 더 강하고 튼튼하게 함.","● 규제: 규칙이나 규정에 의하여 일정한 한도를 정하거나","  정한 한도를 넘지 못하게 막음.","● 조장: 바람직하지 않은 일을 더 심해지도록 부추김.","● 침해: 침범하여 해를 끼침."],"numbered":false,"title":"카드 뉴스 낱말 알기 보기 — 『국어』 138쪽"},"mis":"K6-2-u3-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_basic#3','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',1,'ox','auto','카드 뉴스의 주장은 제목과 중요하게 강조하는 내용에서 확인할 수 있어요.',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":3,"concept":"K6-2-u3-C11","difficulty":1,"kind":"ox","stem":"카드 뉴스의 주장은 제목과 중요하게 강조하는 내용에서 확인할 수 있어요.","answer":"O","reason_options":[{"t":"카드 뉴스는 첫 장의 제목과 강조한 문장에 하고 싶은 말을 담기 때문에","correct":true},{"t":"주장은 언제나 마지막 장의 출처 줄에만 쓰기 때문에","mis":"K6-2-u3-X01"}],"mis":"K6-2-u3-X01","explanation":["카드 뉴스는 이미지와 짧은 글로 핵심 정보를 전해요.","제목 「무분별한 혐오·차별 표현은 이제 그만!」에 주장이 담겼어요.","출처 줄은 근거가 어디에서 나왔는지 알려 줘요."],"asset":{"type":"passage","lines":["첫째 장 — 무분별한 혐오·차별 표현은 이제 그만!","둘째 장 — 혐오·차별 표현이란 무엇일까요?","[뜻] 성별, 장애, 종교, 나이, 출신 지역, 인종 같은 것으로 개인이나 집단에","      대해 편견을 조장하거나 멸시, 모욕, 위협, 폭력을 선동하는 행위","[나타나는 모습] 말 · 글 · 행동 · 복장 · 상징물"],"numbered":false,"title":"카드 뉴스 「무분별한 혐오·차별 표현은 이제 그만!」 첫째 · 둘째 장 — 『국어』 134쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_basic#4','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C20',1,'mc','auto','카드 뉴스의 둘째 장에서 설명한 혐오·차별 표현의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X04']::text[],false,'{"seq":4,"concept":"K6-2-u3-C20","difficulty":1,"kind":"mc","stem":"카드 뉴스의 둘째 장에서 설명한 혐오·차별 표현의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"성별, 장애, 나이 같은 것으로 개인이나 집단에 대해 편견을 조장하거나 멸시·모욕을 선동하는 행위","correct":true},{"t":"서로 생각이 달라 까닭을 들어 자신의 의견을 펼치며 토론하는 행위","mis":"K6-2-u3-X02"},{"t":"다른 사람의 잘못된 점을 예의를 지키며 정중하게 짚어 주는 말","mis":"K6-2-u3-X02"},{"t":"모르는 낱말의 뜻을 사전에서 찾아 바르게 고쳐 쓰는 일","mis":"K6-2-u3-X04"}],"explanation":["둘째 장은 혐오·차별 표현이 무엇인지 알려 줘요.","편견을 조장하거나 멸시, 모욕, 위협, 폭력을 선동하는 행위예요.","의견이 달라 토론하는 것은 혐오·차별 표현이 아니에요."],"asset":{"type":"passage","lines":["첫째 장 — 무분별한 혐오·차별 표현은 이제 그만!","둘째 장 — 혐오·차별 표현이란 무엇일까요?","[뜻] 성별, 장애, 종교, 나이, 출신 지역, 인종 같은 것으로 개인이나 집단에","      대해 편견을 조장하거나 멸시, 모욕, 위협, 폭력을 선동하는 행위","[나타나는 모습] 말 · 글 · 행동 · 복장 · 상징물"],"numbered":false,"title":"카드 뉴스 「무분별한 혐오·차별 표현은 이제 그만!」 첫째 · 둘째 장 — 『국어』 134쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_basic#5','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C20',2,'mc','auto','이유 「특정 집단에 대한 부정적 인식을 강화할 수 있기 때문」을 뒷받침하려고 든 근거는 무엇인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X19']::text[],false,'{"seq":5,"concept":"K6-2-u3-C20","difficulty":2,"kind":"mc","stem":"이유 「특정 집단에 대한 부정적 인식을 강화할 수 있기 때문」을 뒷받침하려고 든 근거는 무엇인가요?","options":[{"t":"‘살색’을 ‘살구색’으로 바꾸어 쓴 순화 사례","correct":true},{"t":"혐오·차별 표현 경험 여부 그래프","mis":"K6-2-u3-X01"},{"t":"각국의 혐오·차별 표현 규제 사례","mis":"K6-2-u3-X19"},{"t":"「서로를 존중하는 사회로 나아가는 첫걸음」이라는 마지막 장의 말","mis":"K6-2-u3-X01"}],"explanation":["셋째 장의 이유 아래에 살색과 살구색 이야기가 있어요.","‘살색’은 피부색이 모두 같다는 편견을 심어 줄 수 있어 바꾸었어요.","그래프는 둘째 이유, 규제 사례는 셋째 이유의 근거예요."],"asset":{"type":"passage","lines":["셋째 장 [왜 멈추어야 할까요?] 특정 집단에 대한 부정적 인식을 강화할 수 있기 때문","      [사례] ‘살색’ → ‘살구색’(피부색에 대한 편견과 차별이 생길 수 있어 바꿈)","넷째 장 [왜 멈추어야 할까요?] 많은 사람이 겪고 있기 때문","      [그래프] 국가인권위원회 조사 — 참여자의 70.3퍼센트가 경험함","다섯째 장 [왜 멈추어야 할까요?] 인간의 존엄성을 침해하고 사회적 갈등을 초래하기 때문","      [사례] 독일은 형법으로, 캐나다는 인권법으로 규제 · 우리나라도 제도 마련","여섯째 장 혐오·차별 표현을 멈추는 것이 서로를 존중하는 사회로 나아가는 첫걸음"],"numbered":false,"title":"같은 카드 뉴스 셋째~여섯째 장 간추림 — 『국어』 135~136쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_basic#6','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C21',2,'match','auto','『국어』 138쪽 낱말 알기의 문장과 빈칸에 들어갈 낱말을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C21","difficulty":2,"kind":"match","stem":"『국어』 138쪽 낱말 알기의 문장과 빈칸에 들어갈 낱말을 알맞게 이으세요.","pairs":[{"l":"다른 사람의 사생활을 함부로 (    )하면 안 된다.","r":"침해"},{"l":"친구를 따돌리는 행동을 (    )하면 모두가 상처받을 수 있다.","r":"조장"},{"l":"도서관에서는 조용한 환경을 위해 큰 소리를 내는 것을 (    )한다.","r":"규제"}],"mis":"K6-2-u3-X29","explanation":["사생활을 침범해 해를 끼치는 것은 침해예요.","나쁜 일을 부추기는 것은 조장이에요.","한도를 넘지 못하게 막는 것은 규제예요."],"asset":{"type":"passage","lines":["● 강화: 세력이나 힘을 더 강하고 튼튼하게 함.","● 규제: 규칙이나 규정에 의하여 일정한 한도를 정하거나","  정한 한도를 넘지 못하게 막음.","● 조장: 바람직하지 않은 일을 더 심해지도록 부추김.","● 침해: 침범하여 해를 끼침."],"numbered":false,"title":"카드 뉴스 낱말 알기 보기 — 『국어』 138쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_basic#7','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C12',2,'mc','auto','『국어』 139쪽 판단 예시에서 이유 2 「많은 사람이 겪고 있기 때문」이 「많은 사람이 받아들일 만한 타당한 이유인가요?」에 △를 받은 까닭은 무엇인가요?',ARRAY['K6-2-u3-X18','K6-2-u3-X02','K6-2-u3-X06']::text[],false,'{"seq":7,"concept":"K6-2-u3-C12","difficulty":2,"kind":"mc","stem":"『국어』 139쪽 판단 예시에서 이유 2 「많은 사람이 겪고 있기 때문」이 「많은 사람이 받아들일 만한 타당한 이유인가요?」에 △를 받은 까닭은 무엇인가요?","options":[{"t":"문제의 규모만 보여 줄 뿐, 왜 멈추어야 하는지와는 연결이 약하기 때문","correct":true},{"t":"많은 사람이 겪고 있으니 멈추어야 할 까닭으로 충분하기 때문","mis":"K6-2-u3-X18"},{"t":"국가인권위원회 자료라서 그 조사 결과를 믿을 수 없기 때문","mis":"K6-2-u3-X02"},{"t":"이유 2가 혐오·차별 표현을 멈추자는 주장과 전혀 관련이 없기 때문","mis":"K6-2-u3-X06"}],"explanation":["이유 2는 혐오·차별 표현을 겪은 사람이 많다는 규모를 말해요.","왜 멈추어야 하는지 밝히려면 어떤 문제가 생기는지를 말해야 해요.","그래서 보통이다(△)로 판단할 수 있어요."],"asset":{"type":"passage","lines":["이유 1 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","이유 2 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 △","이유 3 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","근거 1 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 2 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 3 — 이유와 관련 △ · 객관적인 사실이나 정보 ◎"],"numbered":false,"title":"이유와 근거의 타당성 판단 — 『국어』 139~140쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_basic#8','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',2,'blank','auto','카드 뉴스가 어떤 매체인지 설명한 말이에요. 「카드 뉴스는 이미지와 짧은 글을 합쳐 (    ) 정보를 전달하는 매체예요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X21']::text[],false,'{"seq":8,"concept":"K6-2-u3-C11","difficulty":2,"kind":"blank","stem":"카드 뉴스가 어떤 매체인지 설명한 말이에요. 「카드 뉴스는 이미지와 짧은 글을 합쳐 (    ) 정보를 전달하는 매체예요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"핵심","correct":true},{"t":"모든","mis":"K6-2-u3-X08"},{"t":"재미있는","mis":"K6-2-u3-X21"},{"t":"긴","mis":"K6-2-u3-X08"}],"explanation":["카드 뉴스는 몇 장의 카드에 그림과 짧은 글을 담아요.","그래서 중요한 내용만 골라 전해요.","짧을수록 빠진 것이 없는지 더 꼼꼼히 살펴야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_basic#9','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C12',2,'ox','auto','근거 3 「독일과 캐나다는 혐오·차별 표현을 법으로 규제한다」는 이유 3을 적절하게 뒷받침해요.',ARRAY['K6-2-u3-X19']::text[],false,'{"seq":9,"concept":"K6-2-u3-C12","difficulty":2,"kind":"ox","stem":"근거 3 「독일과 캐나다는 혐오·차별 표현을 법으로 규제한다」는 이유 3을 적절하게 뒷받침해요.","answer":"X","reason_options":[{"t":"규제는 혐오·차별 표현에 대한 해결 방안이라 존엄성 침해나 사회적 갈등이 일어난다는 이유를 보여 주지 못하기 때문에","correct":true},{"t":"나라 이름과 법이 나오면 어떤 이유든 뒷받침하는 근거가 되기 때문에","mis":"K6-2-u3-X19"}],"mis":"K6-2-u3-X19","explanation":["이유 3은 혐오·차별 표현이 존엄성을 침해하고 갈등을 초래한다는 것이에요.","여러 나라의 규제는 그 문제에 대한 해결 방안이에요.","그래서 근거 3은 이유와 관련성이 약해요(△)."],"asset":{"type":"passage","lines":["이유 1 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","이유 2 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 △","이유 3 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","근거 1 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 2 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 3 — 이유와 관련 △ · 객관적인 사실이나 정보 ◎"],"numbered":false,"title":"이유와 근거의 타당성 판단 — 『국어』 139~140쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_basic#10','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C12',3,'essay','teacher','『국어』 140쪽처럼 이유 2를 보통이다(△)로 판단한 까닭을 쓰고, 주장을 더 적절하게 뒷받침하려면 어떤 이유를 제시해야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C12","difficulty":3,"kind":"essay","stem":"『국어』 140쪽처럼 이유 2를 보통이다(△)로 판단한 까닭을 쓰고, 주장을 더 적절하게 뒷받침하려면 어떤 이유를 제시해야 하는지 쓰세요.","answer_guide":{"answer":"예: 혐오·차별 표현을 많은 사람이 겪고 있다는 이유는 문제의 규모만 보여 줄 뿐, 왜 멈추어야 하는지와는 연결이 약하다. 혐오·차별 표현 때문에 어떤 문제가 생기고 있는지, 예를 들어 누군가를 부정적으로 보게 만들어 마음에 상처를 준다는 것을 이유로 제시해야 주장을 적절하게 뒷받침할 수 있다.","scoring_points":["이유 2가 규모만 말한다는 점을 썼는가","왜 멈추어야 하는지와 연결이 약하다고 썼는가","어떤 문제가 생기는지를 이유로 제안했는가"]},"explanation":["규모는 「얼마나 많은가」예요.","이유는 「왜 멈추어야 하는가」에 답해야 해요.","생기는 문제를 이유로 바꾸어 보아요."],"asset":{"type":"passage","lines":["셋째 장 [왜 멈추어야 할까요?] 특정 집단에 대한 부정적 인식을 강화할 수 있기 때문","      [사례] ‘살색’ → ‘살구색’(피부색에 대한 편견과 차별이 생길 수 있어 바꿈)","넷째 장 [왜 멈추어야 할까요?] 많은 사람이 겪고 있기 때문","      [그래프] 국가인권위원회 조사 — 참여자의 70.3퍼센트가 경험함","다섯째 장 [왜 멈추어야 할까요?] 인간의 존엄성을 침해하고 사회적 갈등을 초래하기 때문","      [사례] 독일은 형법으로, 캐나다는 인권법으로 규제 · 우리나라도 제도 마련","여섯째 장 혐오·차별 표현을 멈추는 것이 서로를 존중하는 사회로 나아가는 첫걸음"],"numbered":false,"title":"같은 카드 뉴스 셋째~여섯째 장 간추림 — 『국어』 135~136쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_challenge#1','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C11',2,'mc','auto','『국어』 138쪽에서 친구들이 말한, 카드 뉴스의 내용이 타당한지 평가해야 하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X03','K6-2-u3-X11']::text[],false,'{"seq":1,"concept":"K6-2-u3-C11","difficulty":2,"kind":"mc","stem":"『국어』 138쪽에서 친구들이 말한, 카드 뉴스의 내용이 타당한지 평가해야 하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"잘못된 주장에 속지 않고 내 의견과 비교하며 판단할 수 있기 때문","correct":true},{"t":"카드 뉴스는 짧아서 언제나 틀린 내용만 담고 있기 때문","mis":"K6-2-u3-X02"},{"t":"많은 사람이 본 카드 뉴스는 따로 평가하지 않아도 믿을 수 있기 때문","mis":"K6-2-u3-X03"},{"t":"평가를 잘하면 카드 뉴스를 만든 사람과의 겨루기에서 이길 수 있기 때문","mis":"K6-2-u3-X11"}],"explanation":["타당한지 살펴보면 잘못된 주장에 속지 않아요.","다른 사람의 의견과 내 의견을 비교하며 판단할 수 있어요.","주장, 이유, 근거의 관련성을 논리적으로 정리할 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_challenge#2','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C21',2,'sa','auto','카드 뉴스 낱말 알기에서 「침범하여 해를 끼침.」이라는 뜻을 가진 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C21","difficulty":2,"kind":"sa","stem":"카드 뉴스 낱말 알기에서 「침범하여 해를 끼침.」이라는 뜻을 가진 낱말을 쓰세요.","answer":["침해"],"explanation":["다섯째 장에는 「인간의 존엄성을 침해하고」라는 말이 나와요.","침범하여 해를 끼치는 것을 침해라고 해요.","「사생활을 함부로 침해하면 안 된다」처럼 써요."],"asset":{"type":"passage","lines":["● 강화: 세력이나 힘을 더 강하고 튼튼하게 함.","● 규제: 규칙이나 규정에 의하여 일정한 한도를 정하거나","  정한 한도를 넘지 못하게 막음.","● 조장: 바람직하지 않은 일을 더 심해지도록 부추김.","● 침해: 침범하여 해를 끼침."],"numbered":false,"title":"카드 뉴스 낱말 알기 보기 — 『국어』 138쪽"},"mis":"K6-2-u3-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_challenge#3','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',3,'mc','auto','근거 3을 이유 3에 맞게 고치려면 어떻게 하면 좋을까요?',ARRAY['K6-2-u3-X08','K6-2-u3-X14','K6-2-u3-X20']::text[],false,'{"seq":3,"concept":"K6-2-u3-C12","difficulty":3,"kind":"mc","stem":"근거 3을 이유 3에 맞게 고치려면 어떻게 하면 좋을까요?","options":[{"t":"존엄성 침해나 사회적 갈등이 실제로 일어난 구체적인 사례를 든다","correct":true},{"t":"혐오·차별 표현을 규제하는 나라 이름을 더 많이 늘어놓는다","mis":"K6-2-u3-X08"},{"t":"「꼭 멈추어야 합니다!」라는 말을 더 크게 여러 번 되풀이한다","mis":"K6-2-u3-X14"},{"t":"근거 3을 빼고 주장을 「규제를 늘리자」로 바꾼다","mis":"K6-2-u3-X20"}],"explanation":["이유 3은 존엄성 침해와 사회적 갈등을 말해요.","그 일이 실제로 일어났다는 구체적인 사례가 있어야 이유를 보여 줘요.","나라 이름을 늘리거나 더 힘주어 말하는 것은 고치는 방법이 아니에요."],"asset":{"type":"passage","lines":["이유 1 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","이유 2 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 △","이유 3 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","근거 1 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 2 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 3 — 이유와 관련 △ · 객관적인 사실이나 정보 ◎"],"numbered":false,"title":"이유와 근거의 타당성 판단 — 『국어』 139~140쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_challenge#4','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C20',3,'mc','auto','『국어』 137쪽 내용 알기에서 만든 질문 가운데 친구들의 생각을 묻는 질문은 어느 것인가요?',ARRAY['K6-2-u3-X30']::text[],false,'{"seq":4,"concept":"K6-2-u3-C20","difficulty":3,"kind":"mc","stem":"『국어』 137쪽 내용 알기에서 만든 질문 가운데 친구들의 생각을 묻는 질문은 어느 것인가요?","options":[{"t":"혐오·차별 표현을 줄이기 위해 생활 속에서 어떤 행동을 할 수 있을까요?","correct":true},{"t":"다른 나라에서는 혐오·차별 표현을 어떻게 규제하고 있나요?","mis":"K6-2-u3-X30"},{"t":"혐오·차별 표현을 경험한 사람은 얼마나 많은가요?","mis":"K6-2-u3-X30"},{"t":"이 카드 뉴스의 주장은 무엇인가요?","mis":"K6-2-u3-X30"}],"explanation":["규제 사례, 경험한 사람의 수, 주장은 카드 뉴스 안에 답이 있어요.","그런 질문은 내용을 확인하는 질문이에요.","생활 속에서 할 수 있는 행동은 사람마다 생각이 달라 생각을 묻는 질문이에요."],"asset":{"type":"passage","lines":["셋째 장 [왜 멈추어야 할까요?] 특정 집단에 대한 부정적 인식을 강화할 수 있기 때문","      [사례] ‘살색’ → ‘살구색’(피부색에 대한 편견과 차별이 생길 수 있어 바꿈)","넷째 장 [왜 멈추어야 할까요?] 많은 사람이 겪고 있기 때문","      [그래프] 국가인권위원회 조사 — 참여자의 70.3퍼센트가 경험함","다섯째 장 [왜 멈추어야 할까요?] 인간의 존엄성을 침해하고 사회적 갈등을 초래하기 때문","      [사례] 독일은 형법으로, 캐나다는 인권법으로 규제 · 우리나라도 제도 마련","여섯째 장 혐오·차별 표현을 멈추는 것이 서로를 존중하는 사회로 나아가는 첫걸음"],"numbered":false,"title":"같은 카드 뉴스 셋째~여섯째 장 간추림 — 『국어』 135~136쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_challenge#5','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',3,'error','auto','카드 뉴스의 내용을 평가하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X20','K6-2-u3-X11','K6-2-u3-X19']::text[],false,'{"seq":5,"concept":"K6-2-u3-C12","difficulty":3,"kind":"error","stem":"카드 뉴스의 내용을 평가하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「이유 2와 근거 3이 약하니까 이 카드 뉴스의 주장은 틀렸어.」","correct":true,"mis_target":"K6-2-u3-X20"},{"t":"친구 1 — 「이유 1과 이유 3은 주장과 관련 있고 많은 사람이 받아들일 만해.」","mis":"K6-2-u3-X11"},{"t":"친구 2 — 「근거 3은 이유에 대한 해결 방안이라 이유를 보여 주지 못해.」","mis":"K6-2-u3-X19"}],"explanation":["친구 1은 타당한 점을 먼저 찾았어요.","친구 2는 약한 근거의 까닭을 바르게 짚었어요.","이유나 근거 하나가 약하다고 주장 전체가 틀린 것은 아니에요."],"asset":{"type":"passage","lines":["이유 1 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","이유 2 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 △","이유 3 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","근거 1 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 2 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 3 — 이유와 관련 △ · 객관적인 사실이나 정보 ◎"],"numbered":false,"title":"이유와 근거의 타당성 판단 — 『국어』 139~140쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_challenge#6','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C11',3,'mc','auto','『국어』 139쪽 예시에서 카드 뉴스의 주장을 「매우 그렇다(◎)」로 판단한 까닭은 무엇인가요?',ARRAY['K6-2-u3-X21','K6-2-u3-X08','K6-2-u3-X03']::text[],false,'{"seq":6,"concept":"K6-2-u3-C11","difficulty":3,"kind":"mc","stem":"『국어』 139쪽 예시에서 카드 뉴스의 주장을 「매우 그렇다(◎)」로 판단한 까닭은 무엇인가요?","options":[{"t":"사람들의 마음에 상처를 주고 함께 사는 사회를 어렵게 만드는 문제이기 때문","correct":true},{"t":"카드 뉴스의 그림이 예쁘고 글씨가 커서 눈에 잘 띄기 때문","mis":"K6-2-u3-X21"},{"t":"카드가 여섯 장이나 되어 담긴 내용이 많고 자세하기 때문","mis":"K6-2-u3-X08"},{"t":"많은 사람이 이 카드 뉴스를 보고 누리 소통망에 퍼뜨렸기 때문","mis":"K6-2-u3-X03"}],"explanation":["주장은 우리 생활에 중요한 문제인지, 실천 가능한지 살펴요.","혐오·차별 표현은 사람들에게 상처를 주는 중요한 문제예요.","그림이나 장수, 본 사람 수는 주장의 가치를 알려 주지 못해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_challenge#7','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C11',3,'ox','auto','스쿨 존 카드 뉴스의 이유 ② 「교통 법규를 지키지 않으면 벌금을 내야 하기 때문이다.」는 주장과 관련 있으니 충분히 타당해요.',ARRAY['K6-2-u3-X24']::text[],false,'{"seq":7,"concept":"K6-2-u3-C11","difficulty":3,"kind":"ox","stem":"스쿨 존 카드 뉴스의 이유 ② 「교통 법규를 지키지 않으면 벌금을 내야 하기 때문이다.」는 주장과 관련 있으니 충분히 타당해요.","answer":"X","reason_options":[{"t":"주장과 관련은 있지만 어린이의 안전이 아니라 돈을 내지 않으려는 것을 이유로 들어 타당성이 떨어지기 때문에","correct":true},{"t":"벌금은 법에 나오는 말이라 어떤 주장이든 뒷받침하기 때문에","mis":"K6-2-u3-X24"}],"mis":"K6-2-u3-X24","explanation":["스쿨 존의 교통 법규는 어린이의 안전을 지키려는 것이에요.","벌금을 내지 않으려고 지키자는 이유는 그 참뜻과 어긋나요.","그래서 관련은 있어도 타당성이 떨어진다고 판단해요."],"asset":{"type":"passage","lines":["[제목] 줄이세요, 어린이 보호 구역 ‘스쿨 존’입니다.","주장 어린이 보호 구역인 스쿨 존에서는 교통 법규를 지키자.","이유 ① 어린이들의 안전을 지키는 일이기 때문이다.","이유 ② 교통 법규를 지키지 않으면 벌금을 내야 하기 때문이다.","근거 ① 스쿨 존에 설치하는 시설물의 종류","근거 ② 법규를 위반했을 때 벌금을 내는 기준"],"numbered":false,"title":"세상과 연결하기 — 모둠이 정한 카드 뉴스 예시(『국어』 141쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_challenge#8','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C11',4,'essay','teacher','『국어』 137쪽처럼 「무분별한 혐오·차별 표현은 이제 그만!」의 주장, 이유, 근거를 정리하세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u3-C11","difficulty":4,"kind":"essay","stem":"『국어』 137쪽처럼 「무분별한 혐오·차별 표현은 이제 그만!」의 주장, 이유, 근거를 정리하세요.","answer_guide":{"answer":"예: 주장 — 혐오·차별 표현을 멈추어야 한다. 이유 — 혐오·차별 표현은 특정 집단에 대한 부정적 인식을 강화할 수 있기 때문이다. / 많은 사람이 겪고 있기 때문이다. / 인간의 존엄성을 침해하고 사회적 갈등을 초래하기 때문이다. 근거 — 혐오·차별 표현 순화 사례(살색 → 살구색), 혐오·차별 표현 경험 여부 그래프, 각국의 혐오·차별 표현 규제 사례.","scoring_points":["주장을 바르게 썼는가","이유 세 가지를 썼는가","근거 세 가지를 썼는가"]},"explanation":["주장은 제목과 강조한 내용에서 찾아요.","「왜 멈추어야 할까요?」 아래가 이유예요.","이유마다 붙은 사례·그래프·규제가 근거예요."],"asset":{"type":"passage","lines":["셋째 장 [왜 멈추어야 할까요?] 특정 집단에 대한 부정적 인식을 강화할 수 있기 때문","      [사례] ‘살색’ → ‘살구색’(피부색에 대한 편견과 차별이 생길 수 있어 바꿈)","넷째 장 [왜 멈추어야 할까요?] 많은 사람이 겪고 있기 때문","      [그래프] 국가인권위원회 조사 — 참여자의 70.3퍼센트가 경험함","다섯째 장 [왜 멈추어야 할까요?] 인간의 존엄성을 침해하고 사회적 갈등을 초래하기 때문","      [사례] 독일은 형법으로, 캐나다는 인권법으로 규제 · 우리나라도 제도 마련","여섯째 장 혐오·차별 표현을 멈추는 것이 서로를 존중하는 사회로 나아가는 첫걸음"],"numbered":false,"title":"같은 카드 뉴스 셋째~여섯째 장 간추림 — 『국어』 135~136쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_challenge#9','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',4,'essay','teacher','『국어』 141쪽 스쿨 존 카드 뉴스의 주장, 이유, 근거가 타당한지 판단하고 그렇게 판단한 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C12","difficulty":4,"kind":"essay","stem":"『국어』 141쪽 스쿨 존 카드 뉴스의 주장, 이유, 근거가 타당한지 판단하고 그렇게 판단한 까닭을 쓰세요.","answer_guide":{"answer":"예: 이 카드 뉴스의 주장은 어린이의 안전을 지키자는 내용이라서 매우 가치 있고 중요하다. 하지만 ‘벌금을 내야 하기 때문’이라는 이유는 주장과 관련은 있지만 단순히 돈을 내지 않으려는 것을 이유로 들어 타당성이 떨어진다. 또 근거로 든 ‘시설물의 종류’는 어떤 시설물을 설치하는지 알려 줄 뿐, 우리가 안전하게 보호받아야 하는 까닭을 충분히 뒷받침하지 못한다.","scoring_points":["주장이 가치 있고 중요한지 판단했는가","약한 이유를 찾고 까닭을 썼는가","약한 근거를 찾고 까닭을 썼는가"]},"explanation":["주장의 가치를 먼저 세워요.","이유는 참뜻과 맞는지 살펴요.","근거는 이유를 보여 주는지 살펴요."],"asset":{"type":"passage","lines":["[제목] 줄이세요, 어린이 보호 구역 ‘스쿨 존’입니다.","주장 어린이 보호 구역인 스쿨 존에서는 교통 법규를 지키자.","이유 ① 어린이들의 안전을 지키는 일이기 때문이다.","이유 ② 교통 법규를 지키지 않으면 벌금을 내야 하기 때문이다.","근거 ① 스쿨 존에 설치하는 시설물의 종류","근거 ② 법규를 위반했을 때 벌금을 내는 기준"],"numbered":false,"title":"세상과 연결하기 — 모둠이 정한 카드 뉴스 예시(『국어』 141쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L09_challenge#10','kor',6,2,'u3','L09','tb_g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C20',4,'essay','teacher','카드 뉴스를 보고 만든 생각을 묻는 질문 「혐오·차별 표현을 줄이기 위해 생활 속에서 어떤 행동을 할 수 있을까요?」에 답을 쓰세요. 『국어』 138쪽 낱말(강화·규제·조장·침해) 가운데 하나 이상을 넣어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C20","difficulty":4,"kind":"essay","stem":"카드 뉴스를 보고 만든 생각을 묻는 질문 「혐오·차별 표현을 줄이기 위해 생활 속에서 어떤 행동을 할 수 있을까요?」에 답을 쓰세요. 『국어』 138쪽 낱말(강화·규제·조장·침해) 가운데 하나 이상을 넣어 쓰세요.","answer_guide":{"answer":"예: 친구의 외모나 사는 곳을 놀리는 말을 듣고 함께 웃으면 차별을 조장하는 셈이 되므로, 그런 말을 들으면 그 말이 다른 사람의 마음을 침해할 수 있다고 정중하게 알려 주겠다. 또 누리 소통망에 글을 쓸 때 누군가를 부정적으로 보게 만드는 표현을 쓰지 않겠다.","scoring_points":["생활 속에서 할 수 있는 행동을 썼는가","낱말을 하나 이상 뜻에 맞게 썼는가","카드 뉴스의 내용과 이어지게 썼는가"]},"explanation":["생각을 묻는 질문은 답이 사람마다 달라요.","카드 뉴스의 내용과 이어지게 써요.","낱말은 뜻에 맞게 넣어요."],"asset":{"type":"passage","lines":["● 강화: 세력이나 힘을 더 강하고 튼튼하게 함.","● 규제: 규칙이나 규정에 의하여 일정한 한도를 정하거나","  정한 한도를 넘지 못하게 막음.","● 조장: 바람직하지 않은 일을 더 심해지도록 부추김.","● 침해: 침범하여 해를 끼침."],"numbered":false,"title":"카드 뉴스 낱말 알기 보기 — 『국어』 138쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_basic#1','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',1,'mc','auto','「관심 있는 주제의 영상을 보고 설명하기」 활동에서 가장 먼저 할 일은 무엇인가요?',ARRAY['K6-2-u3-X22']::text[],false,'{"seq":1,"concept":"K6-2-u3-C13","difficulty":1,"kind":"mc","stem":"「관심 있는 주제의 영상을 보고 설명하기」 활동에서 가장 먼저 할 일은 무엇인가요?","options":[{"t":"평소에 관심 있는 주제 말해 보기","correct":true},{"t":"가장 타당하다고 생각한 영상을 골라 설명하기","mis":"K6-2-u3-X22"},{"t":"평가표를 만들어 영상의 내용 타당성 평가하기","mis":"K6-2-u3-X22"},{"t":"주제를 표현한 영상 찾아보기","mis":"K6-2-u3-X22"}],"explanation":["먼저 관심 있는 주제를 말해 보아요.","그다음 같은 주제를 정한 친구들끼리 영상을 찾아요.","평가표로 평가한 뒤 가장 타당한 영상을 설명해요."],"asset":{"type":"passage","lines":["① 평소에 관심 있는 주제 말해 보기(예: 환경 · 건축 · 우주)","② 관심 있는 주제를 정한 친구들끼리 모여 그 주제를 표현한 영상 찾아보기","③ 평가표를 만들어 살펴본 영상들의 내용 타당성 평가하기","④ 가장 타당하다고 생각한 영상을 골라 주장, 이유, 근거를 친구들에게 설명하기"],"numbered":false,"title":"이런 활동도 있어요 — 관심 있는 주제의 영상을 보고 설명하기(『국어』 142쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_basic#2','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C14',1,'sa','auto','기초 다지기에서 「놓다」는 어떻게 발음하나요? 소리 나는 대로 쓰세요. (괄호 [ ]는 쓰지 않아요.)','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C14","difficulty":1,"kind":"sa","stem":"기초 다지기에서 「놓다」는 어떻게 발음하나요? 소리 나는 대로 쓰세요. (괄호 [ ]는 쓰지 않아요.)","answer":["노타"],"explanation":["받침 ㅎ 뒤에 ㄷ이 왔어요.","ㅎ과 ㄷ이 합쳐져 [ㅌ]으로 소리 나요.","그래서 「놓다」는 [노타]로 발음해요."],"asset":{"type":"passage","lines":["1 놓다[노타] · 닿다[다ː타] · 쌓다[싸타]","2 받침 ㅎ 뒤에 ㄱ이 오면 [ㅋ], ㄷ이 오면 [ㅌ], ㅈ이 오면 [ㅊ]으로 합쳐 발음해요.","3 놓는[논는] · 쌓는[싼는]","4 받침 ㅎ 뒤에 ㄴ이 오면 ㅎ은 [ㄴ]으로 발음해요."],"numbered":false,"title":"기초 다지기 — 받침 ‘ㅎ’이 들어간 낱말 발음(『국어』 147쪽)"},"mis":"K6-2-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_basic#3','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C14',1,'ox','auto','「쌓는」은 [싼는]으로 발음해요.',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":3,"concept":"K6-2-u3-C14","difficulty":1,"kind":"ox","stem":"「쌓는」은 [싼는]으로 발음해요.","answer":"O","reason_options":[{"t":"받침 ㅎ 뒤에 ㄴ이 오면 ㅎ은 [ㄴ]으로 발음하기 때문에","correct":true},{"t":"받침 ㅎ 뒤에 ㄴ이 오면 ㅎ은 [ㄱ]으로 발음하기 때문에","mis":"K6-2-u3-X23"}],"mis":"K6-2-u3-X23","explanation":["「쌓는」은 받침 ㅎ 뒤에 ㄴ이 왔어요.","이때 ㅎ은 [ㄴ]으로 소리 나요.","그래서 [싼는]이에요. [싹는]은 틀린 발음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_basic#4','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C22',1,'mc','auto','카드 뉴스 「비규격 농산물을 소비하자」의 주장은 무엇인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":4,"concept":"K6-2-u3-C22","difficulty":1,"kind":"mc","stem":"카드 뉴스 「비규격 농산물을 소비하자」의 주장은 무엇인가요?","options":[{"t":"비규격 농산물을 소비하자","correct":true},{"t":"농산물을 저렴하게 구입할 수 있다","mis":"K6-2-u3-X01"},{"t":"자연환경을 보호할 수 있다","mis":"K6-2-u3-X01"},{"t":"비규격 농산물은 크기가 작거나 상처가 난 농산물이다","mis":"K6-2-u3-X01"}],"explanation":["제목과 첫 장의 강조한 문장에 주장이 있어요.","「저렴하게 구입」과 「자연환경 보호」는 이유예요.","크기가 작거나 상처가 났다는 것은 비규격 농산물의 뜻이에요."],"asset":{"type":"passage","lines":["비규격 농산물은 맛이나 영양은 차이가 없지만 크기가 작거나","상처가 나서 제값을 받지 못하는 농산물입니다.","이유 ① 농산물을 저렴하게 구입할 수 있습니다.","근거 ① 한국소비자원 2021년 조사 — 구매한 까닭의 46.5퍼센트가 저렴해서","이유 ② 자연환경을 보호할 수 있습니다.","근거 ② 농림축산식품부 2023년 조사 — 버려지는 농산물이 환경에 악영향","이유 ③ 모양이 예쁜 농산물을 만들 수 있습니다.","근거 ③ 많이 소비하면 예쁜 농산물이 잘 자랄 환경이 만들어진다고 함"],"numbered":false,"title":"카드 뉴스 「비규격 농산물을 소비하자」 간추림 — 『국어』 145쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_basic#5','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',2,'mc','auto','영상을 안전하게 검색할 때 주의할 점으로 알맞지 않은 것은 무엇인가요?',ARRAY['K6-2-u3-X22']::text[],false,'{"seq":5,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"영상을 안전하게 검색할 때 주의할 점으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"자동 완성어에 자극적인 낱말이 뜨면 그 낱말을 눌러 본다","correct":true},{"t":"관심 있는 주제와 관련해 구체적인 검색어를 입력한다","mis":"K6-2-u3-X22"},{"t":"검색어 끝에 ‘어린이’, ‘교육용’ 같은 낱말을 함께 입력한다","mis":"K6-2-u3-X22"},{"t":"쓰려고 했던 낱말을 끝까지 입력한다","mis":"K6-2-u3-X22"}],"explanation":["구체적인 검색어를 쓰면 엉뚱한 영상이 덜 나와요.","‘초등’, ‘어린이’, ‘교육용’ 같은 낱말을 붙이면 볼 수 있는 영상이 더 나와요.","자극적인 추천 검색어는 무시하고 쓰려던 낱말을 끝까지 입력해요."],"asset":{"type":"passage","lines":["첫째, 관심 있는 주제와 관련해 구체적인 검색어를 입력한다.","둘째, 검색어 끝에 ‘초등’, ‘어린이’, ‘교육용’, ‘공식’, ‘뉴스’ 같은","      낱말을 함께 입력한다.","셋째, 자동 완성어나 추천 검색어에 자극적이거나 주제와 상관없는 낱말이","      뜨더라도 무시하고 쓰려고 했던 낱말을 끝까지 입력한다."],"numbered":false,"title":"영상을 안전하게 검색할 때 주의할 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_basic#6','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C14',2,'mc','auto','기초 다지기의 문장 「나는 작품의 제목을 어떻게 지으면 좋을지 고민했다.」에서 「어떻게」의 바른 발음은 무엇인가요?',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":6,"concept":"K6-2-u3-C14","difficulty":2,"kind":"mc","stem":"기초 다지기의 문장 「나는 작품의 제목을 어떻게 지으면 좋을지 고민했다.」에서 「어떻게」의 바른 발음은 무엇인가요?","options":[{"t":"[어떠케]","correct":true},{"t":"[어떧께]","mis":"K6-2-u3-X23"},{"t":"[어떠게]","mis":"K6-2-u3-X23"},{"t":"[어떤게]","mis":"K6-2-u3-X23"}],"explanation":["「어떻게」는 받침 ㅎ 뒤에 ㄱ이 왔어요.","ㅎ과 ㄱ이 합쳐지면 [ㅋ]으로 소리 나요.","그래서 [어떠케]로 발음해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_basic#7','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C22',2,'mc','auto','「비규격 농산물을 소비하자」에서 이유 ③ 「모양이 예쁜 농산물을 만들 수 있습니다.」가 타당하지 않은 까닭은 무엇인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X07','K6-2-u3-X28']::text[],false,'{"seq":7,"concept":"K6-2-u3-C22","difficulty":2,"kind":"mc","stem":"「비규격 농산물을 소비하자」에서 이유 ③ 「모양이 예쁜 농산물을 만들 수 있습니다.」가 타당하지 않은 까닭은 무엇인가요?","options":[{"t":"주장과 관련 없는 이야기이기 때문","correct":true},{"t":"근거가 숫자로 되어 있지 않기 때문","mis":"K6-2-u3-X08"},{"t":"모양이 예쁜 농산물은 누구나 좋아하기 때문","mis":"K6-2-u3-X07"},{"t":"이유가 세 개나 되어 너무 많기 때문","mis":"K6-2-u3-X28"}],"explanation":["주장은 모양이 고르지 않은 비규격 농산물을 소비하자는 것이에요.","모양이 예쁜 농산물을 만든다는 것은 그 주장과 관련이 없어요.","이유는 주장과 관련 있는지부터 살펴요."],"asset":{"type":"passage","lines":["비규격 농산물은 맛이나 영양은 차이가 없지만 크기가 작거나","상처가 나서 제값을 받지 못하는 농산물입니다.","이유 ① 농산물을 저렴하게 구입할 수 있습니다.","근거 ① 한국소비자원 2021년 조사 — 구매한 까닭의 46.5퍼센트가 저렴해서","이유 ② 자연환경을 보호할 수 있습니다.","근거 ② 농림축산식품부 2023년 조사 — 버려지는 농산물이 환경에 악영향","이유 ③ 모양이 예쁜 농산물을 만들 수 있습니다.","근거 ③ 많이 소비하면 예쁜 농산물이 잘 자랄 환경이 만들어진다고 함"],"numbered":false,"title":"카드 뉴스 「비규격 농산물을 소비하자」 간추림 — 『국어』 145쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_basic#8','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',2,'match','auto','영상의 내용을 깊이 있게 이해하는 차례와 그때 할 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u3-C13","difficulty":2,"kind":"match","stem":"영상의 내용을 깊이 있게 이해하는 차례와 그때 할 일을 알맞게 이으세요.","pairs":[{"l":"보기","r":"해석하지 않고 관찰하여 알아낸 것만 말한다"},{"l":"생각하기","r":"영상에서 무슨 일이 일어나고 있다고 생각하는지 말한다"},{"l":"궁금해하기","r":"보고 생각한 것을 바탕으로 궁금한 것을 묻는다"}],"mis":"K6-2-u3-X22","explanation":["보기 단계에서는 본 것만 말해요.","생각하기 단계에서 해석을 쌓아 가요.","궁금해하기 단계에서 더 넓은 질문을 해요."],"asset":{"type":"passage","lines":["1 준비하기 — 이야기를 시작하기 전에 2~3분 동안 조용히 자세히 관찰한다.","2 보기 — 해석이 아니라 관찰하여 알아낸 것만 말한다.","3 생각하기 — 영상에서 무슨 일이 일어나고 있다고 생각하는지 말한다.","4 궁금해하기 — 보고 생각해 온 것을 바탕으로 지금 궁금한 것을 묻는다."],"numbered":false,"title":"영상의 내용을 깊이 있게 이해하는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_basic#9','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C14',2,'blank','auto','기초 다지기의 문장 「까만 바둑돌을 닮은 강아지가 (    ) 꼬리를 만 채 꼬물거리고 있었다.」에 「동그랗게」가 들어가요. 「동그랗게」의 바른 발음은 무엇인가요?',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":9,"concept":"K6-2-u3-C14","difficulty":2,"kind":"blank","stem":"기초 다지기의 문장 「까만 바둑돌을 닮은 강아지가 (    ) 꼬리를 만 채 꼬물거리고 있었다.」에 「동그랗게」가 들어가요. 「동그랗게」의 바른 발음은 무엇인가요?","options":[{"t":"[동그라케]","correct":true},{"t":"[동그랃께]","mis":"K6-2-u3-X23"},{"t":"[동그라게]","mis":"K6-2-u3-X23"},{"t":"[동그란게]","mis":"K6-2-u3-X23"}],"explanation":["「동그랗게」는 받침 ㅎ 뒤에 ㄱ이 왔어요.","ㅎ과 ㄱ이 합쳐져 [ㅋ]으로 소리 나요.","그래서 [동그라케]로 발음해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_basic#10','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',3,'essay','teacher','영상 평가표를 만들 때 한 친구가 「비속어를 쓰는가?」라는 기준을 넣자고 했어요. 이 기준을 어떻게 다루면 좋을지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C13","difficulty":3,"kind":"essay","stem":"영상 평가표를 만들 때 한 친구가 「비속어를 쓰는가?」라는 기준을 넣자고 했어요. 이 기준을 어떻게 다루면 좋을지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 비속어를 쓰는지는 표현을 보는 기준이라 넣어도 되지만, 먼저 주장은 가치 있고 중요한지, 이유는 주장을 적절하게 뒷받침하는지, 근거는 이유를 적절하게 뒷받침하는지로 내용의 타당성을 충분히 평가해야 한다. 그다음에 비속어 같은 표현을 덧붙여 판단하자고 말하겠다.","scoring_points":["표현 기준이라는 점을 알았는가","내용의 타당성을 먼저 평가해야 한다고 썼는가","세 가지 타당성 기준을 썼는가"]},"explanation":["비속어 사용은 표현에 대한 기준이에요.","평가표는 내용의 타당성이 먼저예요.","표현은 그다음에 덧붙여 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_challenge#1','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',2,'mc','auto','가장 타당하다고 생각한 영상을 골라 친구들에게 설명할 때 함께 이야기할 것은 무엇인가요?',ARRAY['K6-2-u3-X03','K6-2-u3-X15','K6-2-u3-X21']::text[],false,'{"seq":1,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"가장 타당하다고 생각한 영상을 골라 친구들에게 설명할 때 함께 이야기할 것은 무엇인가요?","options":[{"t":"그 영상이 가장 타당하다고 생각한 까닭","correct":true},{"t":"그 영상의 조회 수와 좋아요 수","mis":"K6-2-u3-X03"},{"t":"그 영상을 만든 사람의 나이와 이름","mis":"K6-2-u3-X15"},{"t":"그 영상이 얼마나 재미있었는지만","mis":"K6-2-u3-X21"}],"explanation":["영상의 주장, 이유, 근거를 설명해요.","평가표를 바탕으로 가장 타당하다고 생각한 까닭도 말해요.","조회 수나 재미는 타당성을 알려 주지 못해요."],"asset":{"type":"passage","lines":["① 평소에 관심 있는 주제 말해 보기(예: 환경 · 건축 · 우주)","② 관심 있는 주제를 정한 친구들끼리 모여 그 주제를 표현한 영상 찾아보기","③ 평가표를 만들어 살펴본 영상들의 내용 타당성 평가하기","④ 가장 타당하다고 생각한 영상을 골라 주장, 이유, 근거를 친구들에게 설명하기"],"numbered":false,"title":"이런 활동도 있어요 — 관심 있는 주제의 영상을 보고 설명하기(『국어』 142쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_challenge#2','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C14',2,'sa','auto','받침 ㅎ 뒤에 ㅈ이 오면 합쳐서 어떤 소리로 발음하나요? 자음 하나를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C14","difficulty":2,"kind":"sa","stem":"받침 ㅎ 뒤에 ㅈ이 오면 합쳐서 어떤 소리로 발음하나요? 자음 하나를 쓰세요.","answer":["ㅊ"],"explanation":["받침 ㅎ 뒤에 ㄱ이 오면 [ㅋ], ㄷ이 오면 [ㅌ]으로 합쳐져요.","ㅈ이 오면 [ㅊ]으로 합쳐져요.","예를 들어 「쌓지」는 [싸치]로 발음해요."],"asset":{"type":"passage","lines":["1 놓다[노타] · 닿다[다ː타] · 쌓다[싸타]","2 받침 ㅎ 뒤에 ㄱ이 오면 [ㅋ], ㄷ이 오면 [ㅌ], ㅈ이 오면 [ㅊ]으로 합쳐 발음해요.","3 놓는[논는] · 쌓는[싼는]","4 받침 ㅎ 뒤에 ㄴ이 오면 ㅎ은 [ㄴ]으로 발음해요."],"numbered":false,"title":"기초 다지기 — 받침 ‘ㅎ’이 들어간 낱말 발음(『국어』 147쪽)"},"mis":"K6-2-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_challenge#3','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C22',3,'mc','auto','「비규격 농산물을 소비하자」에서 근거 ③이 타당하지 않은 까닭은 무엇인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X25','K6-2-u3-X03']::text[],false,'{"seq":3,"concept":"K6-2-u3-C22","difficulty":3,"kind":"mc","stem":"「비규격 농산물을 소비하자」에서 근거 ③이 타당하지 않은 까닭은 무엇인가요?","options":[{"t":"확인할 수 있는 사실이 아니라 주관적인 내용이어서 이유를 뒷받침하지 못하기 때문","correct":true},{"t":"근거 ③은 다른 근거보다 짧기 때문","mis":"K6-2-u3-X08"},{"t":"근거 ③에도 「예쁜 농산물」이라는 말이 들어 있어 이유와 잘 맞기 때문","mis":"K6-2-u3-X25"},{"t":"농부들에게 도움이 된다는 말은 무조건 옳기 때문","mis":"K6-2-u3-X03"}],"explanation":["근거 ①과 ②는 조사 기관과 결과를 밝힌 객관적인 정보예요.","근거 ③은 누가 조사했는지도 없이 그렇게 된다고만 말해요.","주관적인 근거는 이유를 뒷받침하지 못해요."],"asset":{"type":"passage","lines":["비규격 농산물은 맛이나 영양은 차이가 없지만 크기가 작거나","상처가 나서 제값을 받지 못하는 농산물입니다.","이유 ① 농산물을 저렴하게 구입할 수 있습니다.","근거 ① 한국소비자원 2021년 조사 — 구매한 까닭의 46.5퍼센트가 저렴해서","이유 ② 자연환경을 보호할 수 있습니다.","근거 ② 농림축산식품부 2023년 조사 — 버려지는 농산물이 환경에 악영향","이유 ③ 모양이 예쁜 농산물을 만들 수 있습니다.","근거 ③ 많이 소비하면 예쁜 농산물이 잘 자랄 환경이 만들어진다고 함"],"numbered":false,"title":"카드 뉴스 「비규격 농산물을 소비하자」 간추림 — 『국어』 145쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_challenge#4','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C14',3,'mc','auto','기초 다지기의 문장 「어제 먹은 아이스크림 맛이 얼마나 좋던지 계속 생각이 나네.」에서 「좋던지」의 바른 발음은 무엇인가요?',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":4,"concept":"K6-2-u3-C14","difficulty":3,"kind":"mc","stem":"기초 다지기의 문장 「어제 먹은 아이스크림 맛이 얼마나 좋던지 계속 생각이 나네.」에서 「좋던지」의 바른 발음은 무엇인가요?","options":[{"t":"[조턴지]","correct":true},{"t":"[조떤지]","mis":"K6-2-u3-X23"},{"t":"[조던지]","mis":"K6-2-u3-X23"},{"t":"[존던지]","mis":"K6-2-u3-X23"}],"explanation":["「좋던지」는 받침 ㅎ 뒤에 ㄷ이 왔어요.","ㅎ과 ㄷ이 합쳐져 [ㅌ]으로 소리 나요.","그래서 [조턴지]로 발음해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_challenge#5','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',3,'error','auto','관심 있는 주제를 정하며 친구들이 말했어요. 『국어』 142~143쪽 활동에 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X26','K6-2-u3-X22']::text[],false,'{"seq":5,"concept":"K6-2-u3-C13","difficulty":3,"kind":"error","stem":"관심 있는 주제를 정하며 친구들이 말했어요. 『국어』 142~143쪽 활동에 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「주제는 내가 좋아하는 게임 캐릭터처럼 나 혼자만의 취향으로 정하면 돼.」","correct":true,"mis_target":"K6-2-u3-X26"},{"t":"친구 1 — 「여러 사람이 함께 고민해 볼 만한 주제를 고르자.」","mis":"K6-2-u3-X22"},{"t":"친구 2 — 「같은 주제를 다룬 여러 관점의 영상을 찾아보자.」","mis":"K6-2-u3-X22"}],"explanation":["주제는 단순한 취향보다 함께 깊이 고민할 만한 것으로 정해요.","같은 주제를 다룬 다양한 관점의 영상을 찾아보아요.","친구 3은 혼자만의 취향으로 주제를 정하려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_challenge#6','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',3,'mc','auto','우리 반에서 정한 활동 예시 1 「영상을 카드 뉴스로 설명하기」의 차례로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X22']::text[],false,'{"seq":6,"concept":"K6-2-u3-C13","difficulty":3,"kind":"mc","stem":"우리 반에서 정한 활동 예시 1 「영상을 카드 뉴스로 설명하기」의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"관심 있는 주제의 영상 찾기 → 영상의 주장, 이유, 근거 파악하기 → 설명하는 카드 뉴스 만들기","correct":true},{"t":"카드 뉴스 만들기 → 영상 찾기 → 주장, 이유, 근거 파악하기","mis":"K6-2-u3-X22"},{"t":"주장, 이유, 근거 파악하기 → 카드 뉴스 만들기 → 영상 찾기","mis":"K6-2-u3-X22"},{"t":"영상 찾기 → 카드 뉴스 만들기 → 주장, 이유, 근거 파악하기","mis":"K6-2-u3-X22"}],"explanation":["먼저 관심 있는 주제의 영상을 찾아요.","그 영상의 주장, 이유, 근거를 파악해요.","파악한 내용을 설명하는 카드 뉴스를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_challenge#7','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C14',3,'ox','auto','「놓아」는 받침 ㅎ 소리를 살려 [노하]로 발음해요.',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":7,"concept":"K6-2-u3-C14","difficulty":3,"kind":"ox","stem":"「놓아」는 받침 ㅎ 소리를 살려 [노하]로 발음해요.","answer":"X","reason_options":[{"t":"받침 ㅎ 뒤에 모음으로 시작하는 말이 오면 ㅎ을 발음하지 않아 [노아]로 소리 나기 때문에","correct":true},{"t":"받침 ㅎ은 어느 자리에서나 [ㅎ] 소리를 그대로 내기 때문에","mis":"K6-2-u3-X23"}],"mis":"K6-2-u3-X23","explanation":["「놓아」는 받침 ㅎ 뒤에 모음 ㅏ가 왔어요.","이때는 ㅎ을 발음하지 않아요.","그래서 [노아]예요. 「쌓이다」도 [싸이다]로 소리 나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_challenge#8','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C22',4,'essay','teacher','「비규격 농산물을 소비하자」의 주장, 이유, 근거가 타당한지 판단하고 그렇게 판단한 까닭을 쓰세요. 그리고 주장을 뒷받침하는 이유를 하나 더 생각해 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u3-C22","difficulty":4,"kind":"essay","stem":"「비규격 농산물을 소비하자」의 주장, 이유, 근거가 타당한지 판단하고 그렇게 판단한 까닭을 쓰세요. 그리고 주장을 뒷받침하는 이유를 하나 더 생각해 쓰세요.","answer_guide":{"answer":"예: 비규격 농산물 소비는 음식물 쓰레기를 줄이고 환경을 보호할 수 있다는 점에서 가치 있고 소비자들이 실천할 수 있는 수준이므로 타당한 주장이다. 이유 ①, ②는 타당하지만 이유 ③은 주장과 관련 없는 이야기라서 타당하지 않다. 근거 ①, ②는 타당하지만 근거 ③은 주관적이어서 이유를 뒷받침하지 못한다. 더 생각한 이유 — 버려지는 농산물을 소비해 농가를 지원할 수 있다.","scoring_points":["주장의 가치와 실천 가능성을 판단했는가","약한 이유와 근거를 찾고 까닭을 썼는가","주장과 관련 있는 이유를 하나 더 썼는가"]},"explanation":["주장 — 가치 있고 실천할 수 있나.","이유 ③은 관련이 없고, 근거 ③은 주관적이에요.","더할 이유도 주장과 관련 있게 써요."],"asset":{"type":"passage","lines":["비규격 농산물은 맛이나 영양은 차이가 없지만 크기가 작거나","상처가 나서 제값을 받지 못하는 농산물입니다.","이유 ① 농산물을 저렴하게 구입할 수 있습니다.","근거 ① 한국소비자원 2021년 조사 — 구매한 까닭의 46.5퍼센트가 저렴해서","이유 ② 자연환경을 보호할 수 있습니다.","근거 ② 농림축산식품부 2023년 조사 — 버려지는 농산물이 환경에 악영향","이유 ③ 모양이 예쁜 농산물을 만들 수 있습니다.","근거 ③ 많이 소비하면 예쁜 농산물이 잘 자랄 환경이 만들어진다고 함"],"numbered":false,"title":"카드 뉴스 「비규격 농산물을 소비하자」 간추림 — 『국어』 145쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_challenge#9','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C14',4,'essay','teacher','기초 다지기의 문장 「여기가 물건을 놓는 곳입니다.」와 「블록을 쌓는 것은 재미있습니다.」에서 「놓는」과 「쌓는」의 발음을 쓰고, 「닿다」의 발음과 견주어 받침 ㅎ이 뒤 소리에 따라 어떻게 소리 나는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C14","difficulty":4,"kind":"essay","stem":"기초 다지기의 문장 「여기가 물건을 놓는 곳입니다.」와 「블록을 쌓는 것은 재미있습니다.」에서 「놓는」과 「쌓는」의 발음을 쓰고, 「닿다」의 발음과 견주어 받침 ㅎ이 뒤 소리에 따라 어떻게 소리 나는지 쓰세요.","answer_guide":{"answer":"예: 「놓는」은 [논는], 「쌓는」은 [싼는]으로 발음한다. 받침 ㅎ 뒤에 ㄴ이 오면 ㅎ은 [ㄴ]으로 소리 나기 때문이다. 「닿다」는 [다ː타]로 발음한다. 받침 ㅎ 뒤에 ㄷ이 오면 둘이 합쳐져 [ㅌ]으로 소리 나기 때문이다.","scoring_points":["[논는]·[싼는]을 바르게 썼는가","「닿다」를 [다ː타](또는 [다타])로 썼는가","ㄴ 앞과 ㄷ 앞의 차이를 까닭으로 썼는가"]},"explanation":["ㄴ 앞 — ㅎ은 [ㄴ].","ㄷ 앞 — 합쳐서 [ㅌ].","뒤에 오는 소리를 먼저 보아요."],"asset":{"type":"passage","lines":["1 놓다[노타] · 닿다[다ː타] · 쌓다[싸타]","2 받침 ㅎ 뒤에 ㄱ이 오면 [ㅋ], ㄷ이 오면 [ㅌ], ㅈ이 오면 [ㅊ]으로 합쳐 발음해요.","3 놓는[논는] · 쌓는[싼는]","4 받침 ㅎ 뒤에 ㄴ이 오면 ㅎ은 [ㄴ]으로 발음해요."],"numbered":false,"title":"기초 다지기 — 받침 ‘ㅎ’이 들어간 낱말 발음(『국어』 147쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_L12_challenge#10','kor',6,2,'u3','L12','tb_g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',4,'essay','teacher','우리 반에서 정한 활동 예시 2처럼 라디오 프로그램 진행자가 되어 관심 있는 주제의 영상을 소개하는 대사를 쓰세요. 영상의 주장, 이유, 근거와 그 영상이 타당하다고 생각한 까닭을 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C13","difficulty":4,"kind":"essay","stem":"우리 반에서 정한 활동 예시 2처럼 라디오 프로그램 진행자가 되어 관심 있는 주제의 영상을 소개하는 대사를 쓰세요. 영상의 주장, 이유, 근거와 그 영상이 타당하다고 생각한 까닭을 넣으세요.","answer_guide":{"answer":"예: 진행자 — 오늘은 「환경」을 주제로 한 영상을 소개합니다. 이 영상은 일회용 컵 대신 개인 컵을 쓰자고 주장합니다. 일회용 컵이 썩는 데 오랜 시간이 걸려 환경을 오염시키기 때문이라고 하고, 그 근거로 기관의 조사 자료를 보여 줍니다. 이유와 근거가 주장과 잘 이어지고 출처도 밝혀서 가장 타당한 영상이라고 생각했습니다.","scoring_points":["진행자의 말투로 썼는가","주장, 이유, 근거를 넣었는가","타당하다고 생각한 까닭을 넣었는가"]},"explanation":["라디오는 소리로만 전하니 말로 또렷하게 설명해요.","주장, 이유, 근거를 차례로 말해요.","타당하다고 판단한 까닭도 함께 말해요."],"asset":{"type":"passage","lines":["1. 라디오 프로그램의 형식(뉴스 · 이야기 쇼 · 드라마)과 주제 정하기","2. 진행하기 위한 역할 정하기 — 진행자 · 기자 · 출연자","3. 주제를 표현하는 영상을 찾아 주장, 이유, 근거 파악하기","4. 영상 속 중요한 장면을 분석하는 내용을 담아 대본 만들기"],"numbered":false,"title":"우리 반에서 정한 활동 예시 2 — 라디오 프로그램 진행자가 되어 설명하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#1','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C1',1,'mc','auto','주장, 이유, 근거의 뜻을 바르게 말한 것은 무엇인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X08']::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":1,"kind":"mc","stem":"주장, 이유, 근거의 뜻을 바르게 말한 것은 무엇인가요?","options":[{"t":"주장은 자신의 의견, 이유는 주장의 까닭, 근거는 이유를 뒷받침하는 자료나 사실이다","correct":true},{"t":"주장은 자료나 사실, 이유는 자신의 의견, 근거는 주장을 꾸미는 말이다","mis":"K6-2-u3-X01"},{"t":"주장, 이유, 근거는 모두 같은 뜻이어서 아무 자리에 바꾸어 써도 된다","mis":"K6-2-u3-X01"},{"t":"근거는 말하는 사람의 느낌을, 이유는 듣는 사람의 생각을 드러내는 말이다","mis":"K6-2-u3-X08"}],"explanation":["주장은 어떤 주제에 대한 자신의 의견을 드러내는 말이에요.","이유는 왜 그렇게 주장하는지를 설명하는 말이에요.","근거는 이유를 뒷받침하는 자료나 사실이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#2','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C2',1,'mc','auto','여러 매체가 전달하는 주장을 들을 때의 태도로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X03','K6-2-u3-X02','K6-2-u3-X26']::text[],false,'{"seq":2,"concept":"K6-2-u3-C2","difficulty":1,"kind":"mc","stem":"여러 매체가 전달하는 주장을 들을 때의 태도로 가장 알맞은 것은 무엇인가요?","options":[{"t":"그 내용의 타당성을 판단하며 비판적으로 듣는다","correct":true},{"t":"많은 사람이 본 내용이면 그대로 믿는다","mis":"K6-2-u3-X03"},{"t":"모든 주장은 틀렸다고 생각하고 듣는다","mis":"K6-2-u3-X02"},{"t":"나와 친한 사람의 주장만 믿는다","mis":"K6-2-u3-X26"}],"explanation":["주장을 담은 매체는 우리 생활 곳곳에 있어요.","그 내용을 타당성을 판단하며 비판적으로 파악해야 해요.","그대로 믿거나 무조건 의심하는 것은 따져 보기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#3','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C15',1,'mc','auto','「실수에서 배워요」에서 플레밍이 실수 덕분에 발견한 것은 무엇인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":3,"concept":"K6-2-u3-C15","difficulty":1,"kind":"mc","stem":"「실수에서 배워요」에서 플레밍이 실수 덕분에 발견한 것은 무엇인가요?","options":[{"t":"페니실린","correct":true},{"t":"배양기","mis":"K6-2-u3-X04"},{"t":"포도상 구균","mis":"K6-2-u3-X04"},{"t":"뇌파","mis":"K6-2-u3-X04"}],"explanation":["플레밍은 접시를 배양기 밖에 두고 휴가를 떠났어요.","돌아와 미생물이 줄어든 것을 보았어요.","그렇게 페니실린을 발견했어요."],"asset":{"type":"passage","lines":["실수는 조심하지 않아서 잘못하는 행동을 말합니다.","(간추림) 친구와 부딪치는 실수, 약속을 깜빡 잊는 실수는 우리를 속상하게 한다.","하지만 모든 실수가 나쁜 것은 아닙니다.","(간추림) 실수에서 문제점을 찾으려 노력하면 고칠 점을 발견할 수 있다.","(간추림) 1928년 플레밍은 포도상 구균을 기르던 접시를","(간추림) 실수로 배양기 밖에 두고 휴가를 떠났다.","(간추림) 돌아와 미생물이 줄어든 것을 보고 페니실린을 발견했다.","(간추림) 실수를 했느냐보다 무엇을 배우고 실천하느냐가 중요하다."],"numbered":false,"title":"「실수에서 배워요」 — 『국어』 118쪽 듣기 자료 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#4','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C16',1,'mc','auto','「용기초등학교 어린이 생각 발표회」에서 윤정이와 현우가 바꾸고 싶어 한 것은 무엇인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":4,"concept":"K6-2-u3-C16","difficulty":1,"kind":"mc","stem":"「용기초등학교 어린이 생각 발표회」에서 윤정이와 현우가 바꾸고 싶어 한 것은 무엇인가요?","options":[{"t":"학교 급식으로 나오는 반찬의 구성","correct":true},{"t":"학교 운동장의 쓰레기통","mis":"K6-2-u3-X04"},{"t":"급식실의 의자 배치","mis":"K6-2-u3-X04"},{"t":"도서관의 문 여는 시간","mis":"K6-2-u3-X04"}],"explanation":["두 친구는 모두 학교 급식에 대해 말했어요.","윤정이는 채소 위주의 음식을 늘리자고 했어요.","현우는 질 좋은 고기반찬을 더 충분히 제공하자고 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#5','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C17',1,'blank','auto','「무엇을 내주거나 갖다 바치다.」라는 뜻을 가진 낱말은 무엇인가요?',ARRAY['K6-2-u3-X29']::text[],false,'{"seq":5,"concept":"K6-2-u3-C17","difficulty":1,"kind":"blank","stem":"「무엇을 내주거나 갖다 바치다.」라는 뜻을 가진 낱말은 무엇인가요?","options":[{"t":"제공하다","correct":true},{"t":"섭취하다","mis":"K6-2-u3-X29"},{"t":"가속하다","mis":"K6-2-u3-X29"},{"t":"대항하다","mis":"K6-2-u3-X29"}],"explanation":["「급식에서 채소 위주의 음식을 제공하는 날」처럼 쓰였어요.","「제공하다」는 무엇을 내준다는 뜻이에요.","양분을 빨아들이는 것은 「섭취하다」예요."],"asset":{"type":"passage","lines":["보기: 가속하다 · 대항하다 · 발생하다 · 섭취하다 · 제공하다","㉮ 생물체가 양분 따위를 몸속에 빨아들이다.","㉯ 무엇을 내주거나 갖다 바치다.","㉰ 굽히거나 지지 않으려고 맞서서 버티거나 항거하다.","㉱ 점점 속도를 더하다."],"numbered":false,"title":"「용기초등학교 어린이 생각 발표회」 낱말 알기 — 『국어』 125쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#6','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C18',1,'mc','auto','「낭독의 재발견」의 주장으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X15','K6-2-u3-X16']::text[],false,'{"seq":6,"concept":"K6-2-u3-C18","difficulty":1,"kind":"mc","stem":"「낭독의 재발견」의 주장으로 알맞은 것은 무엇인가요?","options":[{"t":"낭독은 글의 내용을 잘 이해하는 데 도움을 준다","correct":true},{"t":"사람들의 집중력이 점점 떨어지고 있다","mis":"K6-2-u3-X15"},{"t":"캐나다 사람들은 뇌파 측정 연구를 했다","mis":"K6-2-u3-X15"},{"t":"책은 소리 내지 않고 읽어야 한다","mis":"K6-2-u3-X16"}],"explanation":["제목, 자료, 강조한 표현을 합쳐 주장을 세워요.","집중력이 떨어지고 있다는 것은 영상이 제시한 자료예요.","주장은 낭독이 글의 내용을 이해하는 데 도움을 준다는 것이에요."],"asset":{"type":"passage","lines":["[장면] 책에 집중하지 못하는 시대","[장면] 캐나다 사람들을 대상으로 설문과 뇌파 측정 연구를 한 결과","[장면] 낭랑하게 목청을 돋우고 가락에 맞추어 책을 읽다 보면","[장면] ‘입, 몸, 마음’이라는 낱말을 굵은 글자로 강조한다."],"numbered":false,"title":"영상 「낭독의 재발견」의 장면 — 『국어』 129~130쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#7','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C20',1,'mc','auto','카드 뉴스 「무분별한 혐오·차별 표현은 이제 그만!」에서 혐오·차별 표현이 나타나는 모습으로 든 것이 아닌 것은 무엇인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":7,"concept":"K6-2-u3-C20","difficulty":1,"kind":"mc","stem":"카드 뉴스 「무분별한 혐오·차별 표현은 이제 그만!」에서 혐오·차별 표현이 나타나는 모습으로 든 것이 아닌 것은 무엇인가요?","options":[{"t":"날씨","correct":true},{"t":"말","mis":"K6-2-u3-X04"},{"t":"복장","mis":"K6-2-u3-X04"},{"t":"상징물","mis":"K6-2-u3-X04"}],"explanation":["둘째 장은 혐오·차별 표현이 어떻게 나타나는지 알려 줘요.","말, 글, 행동, 복장, 상징물로 나타난다고 했어요.","날씨는 들어 있지 않아요."],"asset":{"type":"passage","lines":["첫째 장 — 무분별한 혐오·차별 표현은 이제 그만!","둘째 장 — 혐오·차별 표현이란 무엇일까요?","[뜻] 성별, 장애, 종교, 나이, 출신 지역, 인종 같은 것으로 개인이나 집단에","      대해 편견을 조장하거나 멸시, 모욕, 위협, 폭력을 선동하는 행위","[나타나는 모습] 말 · 글 · 행동 · 복장 · 상징물"],"numbered":false,"title":"카드 뉴스 「무분별한 혐오·차별 표현은 이제 그만!」 첫째 · 둘째 장 — 『국어』 134쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#8','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C14',1,'mc','auto','「닿다」의 바른 발음은 무엇인가요?',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":8,"concept":"K6-2-u3-C14","difficulty":1,"kind":"mc","stem":"「닿다」의 바른 발음은 무엇인가요?","options":[{"t":"[다ː타]","correct":true},{"t":"[닫다]","mis":"K6-2-u3-X23"},{"t":"[다다]","mis":"K6-2-u3-X23"},{"t":"[단다]","mis":"K6-2-u3-X23"}],"explanation":["「닿다」는 받침 ㅎ 뒤에 ㄷ이 왔어요.","ㅎ과 ㄷ이 합쳐져 [ㅌ]으로 소리 나요.","그래서 [다ː타]로 발음해요."],"asset":{"type":"passage","lines":["1 놓다[노타] · 닿다[다ː타] · 쌓다[싸타]","2 받침 ㅎ 뒤에 ㄱ이 오면 [ㅋ], ㄷ이 오면 [ㅌ], ㅈ이 오면 [ㅊ]으로 합쳐 발음해요.","3 놓는[논는] · 쌓는[싼는]","4 받침 ㅎ 뒤에 ㄴ이 오면 ㅎ은 [ㄴ]으로 발음해요."],"numbered":false,"title":"기초 다지기 — 받침 ‘ㅎ’이 들어간 낱말 발음(『국어』 147쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#9','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C4',2,'mc','auto','『국어』 144쪽 1번에서 주장하는 말의 내용이 타당한지 평가할 때 필요한 기준으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X28']::text[],false,'{"seq":9,"concept":"K6-2-u3-C4","difficulty":2,"kind":"mc","stem":"『국어』 144쪽 1번에서 주장하는 말의 내용이 타당한지 평가할 때 필요한 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"㉰ 이유는 주장을 적절하게 뒷받침하는가?","correct":true},{"t":"㉯ 주장의 길이가 적당한가?","mis":"K6-2-u3-X28"},{"t":"㉱ 듣는 사람을 기분 좋게 만드는 이유인가?","mis":"K6-2-u3-X28"},{"t":"㉲ 근거의 종류는 다양한가?","mis":"K6-2-u3-X28"}],"explanation":["필요한 기준은 ㉮, ㉰, ㉳예요.","주장의 길이나 듣는 사람의 기분은 타당성과 관계없어요.","근거는 종류가 많은지보다 이유를 뒷받침하는지가 중요해요."],"asset":{"type":"passage","lines":["㉮ 주장은 가치 있고 중요한가?","㉯ 주장의 길이가 적당한가?","㉰ 이유는 주장을 적절하게 뒷받침하는가?","㉱ 듣는 사람을 기분 좋게 만드는 이유인가?","㉲ 근거의 종류는 다양한가?","㉳ 근거는 이유를 적절하게 뒷받침하는가?"],"numbered":false,"title":"마무리 1번 — 주장하는 말의 내용을 평가하며 들을 때 필요한 기준 찾기(『국어』 144쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#10','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C3',2,'mc','auto','주장하는 말을 들을 때 지나치게 감정에 호소하지는 않는지 주의하며 들어야 하는 까닭은 무엇인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X04','K6-2-u3-X14']::text[],false,'{"seq":10,"concept":"K6-2-u3-C3","difficulty":2,"kind":"mc","stem":"주장하는 말을 들을 때 지나치게 감정에 호소하지는 않는지 주의하며 들어야 하는 까닭은 무엇인가요?","options":[{"t":"감정에 기대는 말은 이유와 근거가 타당한지 따지지 못하게 할 수 있기 때문","correct":true},{"t":"감정을 드러내는 말은 모두 거짓말이기 때문","mis":"K6-2-u3-X02"},{"t":"목소리가 큰 사람의 말이 가장 타당하기 때문","mis":"K6-2-u3-X04"},{"t":"감정에 호소할수록 근거가 더 객관적이기 때문","mis":"K6-2-u3-X14"}],"explanation":["주장하는 말을 들을 때는 말하는 이의 태도도 살펴요.","지나치게 감정에 기대면 내용을 따지기 어려워요.","그래서 주장, 이유, 근거를 차분히 따져 보아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"말하는 사람의 주장과 이유나 근거를 놓치지 않도록 메모하며 듣는 게 좋겠어."},{"who":"친구 2","text":"말하는 사람의 주장과 내 생각을 비교하며 들으면 어떨까?"},{"who":"친구 3","text":"지나치게 감정에 호소하지는 않는지 주의하며 들어야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#11','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C6',2,'mc','auto','『국어』 121쪽에서 말한 근거 자료의 유형을 모두 모은 것은 무엇인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X15','K6-2-u3-X01']::text[],false,'{"seq":11,"concept":"K6-2-u3-C6","difficulty":2,"kind":"mc","stem":"『국어』 121쪽에서 말한 근거 자료의 유형을 모두 모은 것은 무엇인가요?","options":[{"t":"표, 그래프, 면담 자료, 사례","correct":true},{"t":"느낌, 짐작, 소문, 바람","mis":"K6-2-u3-X08"},{"t":"제목, 자막, 음악, 장면","mis":"K6-2-u3-X15"},{"t":"주장, 이유, 근거, 결론","mis":"K6-2-u3-X01"}],"explanation":["근거 자료의 유형에는 표, 그래프, 면담 자료, 사례가 있어요.","느낌이나 짐작은 객관적인 근거가 아니에요.","제목, 자막, 음악은 영상의 주장을 찾는 실마리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#12','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C5',2,'mc','auto','「오류를 찾아라」 놀이의 ㉮ 「모든 사람은 아침에 운동을 해야 한다. 나는 아침 운동을 하면 기분이 좋기 때문이다.」에서 이유에 오류가 있는 까닭은 무엇인가요?',ARRAY['K6-2-u3-X28','K6-2-u3-X02']::text[],false,'{"seq":12,"concept":"K6-2-u3-C5","difficulty":2,"kind":"mc","stem":"「오류를 찾아라」 놀이의 ㉮ 「모든 사람은 아침에 운동을 해야 한다. 나는 아침 운동을 하면 기분이 좋기 때문이다.」에서 이유에 오류가 있는 까닭은 무엇인가요?","options":[{"t":"혼자만의 느낌이라 많은 사람이 받아들이기 어렵기 때문","correct":true},{"t":"주장 문장과 이유 문장의 글자 수가 비슷하기 때문","mis":"K6-2-u3-X28"},{"t":"아침 운동은 누구에게나 언제나 몸에 해롭기 때문","mis":"K6-2-u3-X02"},{"t":"「아침」이라는 낱말이 두 문장에 되풀이되기 때문","mis":"K6-2-u3-X28"}],"explanation":["주장은 모든 사람이 아침에 운동을 하자는 것이에요.","이유는 「나는 기분이 좋다」는 혼자만의 느낌이에요.","많은 사람이 받아들일 만한 이유로 바꾸어야 해요."],"asset":{"type":"passage","lines":["㉮ 모든 사람은 아침에 운동을 해야 한다.","   나는 아침 운동을 하면 기분이 좋기 때문이다.","㉯ 학생들은 교복을 입어야 한다.","   교복을 입으면 싸울 일이 줄어들기 때문이다.","㉰ 플라스틱 사용을 줄여야 한다.","   거북이 비닐 때문에 고통받는 걸 보니 너무 슬펐기 때문이다."],"numbered":false,"title":"「오류를 찾아라」 놀이 — 이유에 오류가 있는 문장의 예"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#13','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C9',2,'mc','auto','지호와 규민이가 영상의 주장을 파악한 과정으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":13,"concept":"K6-2-u3-C9","difficulty":2,"kind":"mc","stem":"지호와 규민이가 영상의 주장을 파악한 과정으로 알맞은 것은 무엇인가요?","options":[{"t":"제목, 자료, 강조를 정한 까닭을 차례로 묻고 답했다","correct":true},{"t":"영상의 길이와 화면 색깔을 장면마다 견주어 보았다","mis":"K6-2-u3-X15"},{"t":"영상을 만든 사람의 이름과 나이만 찾아보았다","mis":"K6-2-u3-X15"},{"t":"마지막 장면 하나만 보고 영상의 주장을 정했다","mis":"K6-2-u3-X15"}],"explanation":["지호는 제목, 자료, 강조에 대해 물었어요.","규민이는 그렇게 한 까닭을 답했어요.","세 가지를 합쳐 영상의 주장을 찾아요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"영상의 제목을 ‘낭독의 재발견’으로 정한 까닭은 무엇일까?"},{"who":"규민","text":"오래된 방법이라고 생각했던 낭독의 효과를 다시 한번 알려 주기 위해서야."},{"who":"지호","text":"인간의 집중력이 점점 떨어지고 있다는 실험 결과를 보여 주는 자료를 제시한 까닭은 무엇일까?"},{"who":"규민","text":"집중력과 기억력 향상에 도움이 되는 낭독의 필요성을 보여 주는 정보를 제시하고 싶었기 때문이야."},{"who":"지호","text":"영상에서 ‘입, 몸, 마음’이라는 낱말을 굵은 글자로 강조한 까닭은 무엇일까?"},{"who":"규민","text":"낭독의 긍정적인 효과를 강조해서 표현하기 위해서야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#14','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C12',2,'mc','auto','카드 뉴스의 근거 3 「각국의 혐오·차별 표현 규제 사례」가 이유 3을 적절하게 뒷받침하지 못하는 까닭은 무엇인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X08','K6-2-u3-X19']::text[],false,'{"seq":14,"concept":"K6-2-u3-C12","difficulty":2,"kind":"mc","stem":"카드 뉴스의 근거 3 「각국의 혐오·차별 표현 규제 사례」가 이유 3을 적절하게 뒷받침하지 못하는 까닭은 무엇인가요?","options":[{"t":"규제는 해결 방안이라 존엄성 침해나 갈등이 일어난다는 것을 보여 주지 못하기 때문","correct":true},{"t":"독일과 캐나다는 먼 나라라서 그 사례를 믿을 수 없기 때문","mis":"K6-2-u3-X02"},{"t":"규제하는 나라 이름이 둘뿐이라 근거의 양이 너무 적기 때문","mis":"K6-2-u3-X08"},{"t":"여러 나라가 규제한다는 사실은 어떤 이유든 언제나 뒷받침하기 때문","mis":"K6-2-u3-X19"}],"explanation":["이유 3은 혐오·차별 표현이 존엄성을 침해하고 갈등을 초래한다는 것이에요.","규제 사례는 그 뒤에 마련한 해결 방안이에요.","이유를 보여 주려면 실제로 생긴 문제의 사례를 들어야 해요."],"asset":{"type":"passage","lines":["이유 1 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","이유 2 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 △","이유 3 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","근거 1 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 2 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 3 — 이유와 관련 △ · 객관적인 사실이나 정보 ◎"],"numbered":false,"title":"이유와 근거의 타당성 판단 — 『국어』 139~140쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#15','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C22',2,'mc','auto','「비규격 농산물을 소비하자」에서 비규격 농산물의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":15,"concept":"K6-2-u3-C22","difficulty":2,"kind":"mc","stem":"「비규격 농산물을 소비하자」에서 비규격 농산물의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"맛이나 영양은 차이가 없지만 크기가 작거나 상처가 나서 제값을 받지 못하는 농산물","correct":true},{"t":"맛과 영양이 떨어져 먹을 수 없어 버려야 하는 농산물","mis":"K6-2-u3-X04"},{"t":"크기와 모양이 모두 고르고 상처가 없어 제값을 받는 농산물","mis":"K6-2-u3-X04"},{"t":"우리나라가 아닌 다른 나라에서 들여와 값이 싼 농산물","mis":"K6-2-u3-X04"}],"explanation":["첫 장에서 비규격 농산물이 무엇인지 설명해요.","맛이나 영양은 차이가 없어요.","크기가 작거나 상처가 나서 제값을 받지 못할 뿐이에요."],"asset":{"type":"passage","lines":["비규격 농산물은 맛이나 영양은 차이가 없지만 크기가 작거나","상처가 나서 제값을 받지 못하는 농산물입니다.","이유 ① 농산물을 저렴하게 구입할 수 있습니다.","근거 ① 한국소비자원 2021년 조사 — 구매한 까닭의 46.5퍼센트가 저렴해서","이유 ② 자연환경을 보호할 수 있습니다.","근거 ② 농림축산식품부 2023년 조사 — 버려지는 농산물이 환경에 악영향","이유 ③ 모양이 예쁜 농산물을 만들 수 있습니다.","근거 ③ 많이 소비하면 예쁜 농산물이 잘 자랄 환경이 만들어진다고 함"],"numbered":false,"title":"카드 뉴스 「비규격 농산물을 소비하자」 간추림 — 『국어』 145쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#16','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C13',2,'mc','auto','관심 있는 주제의 영상을 평가표로 평가할 때 쓰는 세 기준으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X21','K6-2-u3-X03','K6-2-u3-X26']::text[],false,'{"seq":16,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"관심 있는 주제의 영상을 평가표로 평가할 때 쓰는 세 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"주장은 가치 있고 중요한가, 이유와 근거는 각각 주장과 이유를 적절하게 뒷받침하나","correct":true},{"t":"영상이 재미있나, 배경 음악이 좋나, 길이가 짧아 보기 편하나","mis":"K6-2-u3-X21"},{"t":"조회 수가 많나, 댓글이 많이 달렸나, 최근에 새로 올린 영상인가","mis":"K6-2-u3-X03"},{"t":"내가 좋아하는 주제인가, 친구가 추천했나, 화면이 예쁘고 밝은가","mis":"K6-2-u3-X26"}],"explanation":["『국어』 142쪽 평가표에는 세 기준이 있어요.","주장, 이유, 근거의 타당성을 차례로 판단해요.","재미나 조회 수는 내용의 타당성을 알려 주지 못해요."],"asset":{"type":"passage","lines":["① 평소에 관심 있는 주제 말해 보기(예: 환경 · 건축 · 우주)","② 관심 있는 주제를 정한 친구들끼리 모여 그 주제를 표현한 영상 찾아보기","③ 평가표를 만들어 살펴본 영상들의 내용 타당성 평가하기","④ 가장 타당하다고 생각한 영상을 골라 주장, 이유, 근거를 친구들에게 설명하기"],"numbered":false,"title":"이런 활동도 있어요 — 관심 있는 주제의 영상을 보고 설명하기(『국어』 142쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#17','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C1',3,'mc','auto','듣기 자료 「일회용품은 이제 그만」의 주장은 무엇인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X06']::text[],false,'{"seq":17,"concept":"K6-2-u3-C1","difficulty":3,"kind":"mc","stem":"듣기 자료 「일회용품은 이제 그만」의 주장은 무엇인가요?","options":[{"t":"환경을 위해 일회용품 사용을 줄이자","correct":true},{"t":"일회용품을 만들려면 많은 자원이 필요하다","mis":"K6-2-u3-X01"},{"t":"종이컵은 땅속에서 썩는 데 20년이 걸린다","mis":"K6-2-u3-X01"},{"t":"나무젓가락은 편리하다","mis":"K6-2-u3-X06"}],"explanation":["말하는 이는 「환경을 위해 일회용품 사용을 줄입시다.」라고 했어요.","많은 자원이 필요하다는 것은 이유예요.","썩는 데 걸리는 햇수는 근거예요."],"asset":{"type":"passage","lines":["(간추림) 종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다.","(간추림) 우리가 편리하게 쓰던 일회용품이 지구를 병들게 하고 있다.","환경을 위해 일회용품 사용을 줄입시다.","(간추림) 일회용품을 만들려면 많은 자원이 필요하다.","(간추림) 나무젓가락과 종이컵을 만들려면 숲의 나무를 베어야 한다.","(간추림) 일회용품은 오랫동안 썩지 않아 환경을 오염시킨다.","(간추림) 땅속에서 썩는 데 종이컵은 20년, 스티로폼 도시락은","(간추림) 500년이 걸린다고 한다."],"numbered":false,"title":"「일회용품은 이제 그만」 — 듣기 자료 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#18','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C5',3,'mc','auto','「일회용품은 이제 그만」의 이유 「일회용품은 오랫동안 썩지 않아 환경을 오염시킨다」를 판단한 것으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X06','K6-2-u3-X07','K6-2-u3-X28']::text[],false,'{"seq":18,"concept":"K6-2-u3-C5","difficulty":3,"kind":"mc","stem":"「일회용품은 이제 그만」의 이유 「일회용품은 오랫동안 썩지 않아 환경을 오염시킨다」를 판단한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"주장과 관련 있고, 많은 사람이 받아들일 만하다","correct":true},{"t":"일회용품을 줄이자는 주장과 관련 없는 이야기이다","mis":"K6-2-u3-X06"},{"t":"말하는 사람 혼자만의 느낌이라 받아들이기 어렵다","mis":"K6-2-u3-X07"},{"t":"이유가 둘이나 되어 오히려 타당하지 않다","mis":"K6-2-u3-X28"}],"explanation":["이유는 주장과 관련 있는지 살펴요.","환경 오염은 일회용품을 줄이자는 주장과 바로 이어져요.","많은 사람이 받아들일 만한 까닭이에요."],"asset":{"type":"passage","lines":["(간추림) 종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다.","(간추림) 우리가 편리하게 쓰던 일회용품이 지구를 병들게 하고 있다.","환경을 위해 일회용품 사용을 줄입시다.","(간추림) 일회용품을 만들려면 많은 자원이 필요하다.","(간추림) 나무젓가락과 종이컵을 만들려면 숲의 나무를 베어야 한다.","(간추림) 일회용품은 오랫동안 썩지 않아 환경을 오염시킨다.","(간추림) 땅속에서 썩는 데 종이컵은 20년, 스티로폼 도시락은","(간추림) 500년이 걸린다고 한다."],"numbered":false,"title":"「일회용품은 이제 그만」 — 듣기 자료 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#19','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C13',3,'mc','auto','누리 소통망의 영상에 평가 댓글을 쓸 때의 조건이 아닌 것은 무엇인가요?',ARRAY['K6-2-u3-X27']::text[],false,'{"seq":19,"concept":"K6-2-u3-C13","difficulty":3,"kind":"mc","stem":"누리 소통망의 영상에 평가 댓글을 쓸 때의 조건이 아닌 것은 무엇인가요?","options":[{"t":"영상을 만든 사람을 깎아내리는 별명 붙이기","correct":true},{"t":"자신이 파악한 영상의 주장이 무엇인지 쓰기","mis":"K6-2-u3-X27"},{"t":"이유와 근거가 타당한지 까닭과 함께 쓰기","mis":"K6-2-u3-X27"},{"t":"타당하지 않은 부분에 대해 정중하게 확인 요청하기","mis":"K6-2-u3-X27"}],"explanation":["댓글에는 주장, 판단, 까닭, 정중한 확인 요청을 써요.","예의 바르고 건설적으로 비판해요.","다른 사람을 비방하거나 혐오하는 표현은 쓰지 않아요."],"asset":{"type":"passage","lines":["• 자신이 파악한 영상의 주장이 무엇인지 쓰기","• 주장이 타당한지 쓰기","• 이유와 근거가 타당한지 까닭과 함께 쓰기","• 타당하지 않은 부분에 대해 정중하게 확인 요청하기"],"numbered":false,"title":"영상에 평가 댓글을 쓸 때의 조건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#20','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C10',3,'mc','auto','영상에서 자막을 되풀이하고 음악으로 분위기를 높인 장면을 보았을 때 알맞은 생각은 무엇인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X15','K6-2-u3-X21']::text[],false,'{"seq":20,"concept":"K6-2-u3-C10","difficulty":3,"kind":"mc","stem":"영상에서 자막을 되풀이하고 음악으로 분위기를 높인 장면을 보았을 때 알맞은 생각은 무엇인가요?","options":[{"t":"강조한 내용이니 주장을 찾는 실마리로 삼고, 타당한지는 따로 따진다","correct":true},{"t":"강조가 셀수록 그 말은 틀림없는 사실이라고 믿는다","mis":"K6-2-u3-X17"},{"t":"강조된 장면은 주장과 관계없으니 보지 않고 넘어간다","mis":"K6-2-u3-X15"},{"t":"음악이 멋지고 웅장하면 영상의 내용도 타당하다고 본다","mis":"K6-2-u3-X21"}],"explanation":["강조 효과는 영상이 무엇을 말하고 싶은지 알려 줘요.","그래서 주장을 찾는 데 도움이 돼요.","그 말이 타당한지는 이유와 근거로 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#21','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C8',3,'mc','auto','주장하는 말에서 근거로 객관적인 사실이나 정보를 활용했는지 판단할 때 살펴볼 것으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X14','K6-2-u3-X08']::text[],false,'{"seq":21,"concept":"K6-2-u3-C8","difficulty":3,"kind":"mc","stem":"주장하는 말에서 근거로 객관적인 사실이나 정보를 활용했는지 판단할 때 살펴볼 것으로 알맞은 것은 무엇인가요?","options":[{"t":"누가 보아도 그러한지, 어디에서 나온 자료인지","correct":true},{"t":"말하는 사람이 얼마나 감동적으로 말했는지","mis":"K6-2-u3-X14"},{"t":"근거가 얼마나 긴지","mis":"K6-2-u3-X08"},{"t":"근거에 어려운 낱말이 많은지","mis":"K6-2-u3-X08"}],"explanation":["객관적인 근거는 누가 보아도 그러한 사실이나 정보예요.","어디에서 나온 자료인지 밝혀야 확인할 수 있어요.","감동이나 길이는 객관성과 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#22','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C19',3,'mc','auto','「나를 성장시키는 기록법」에서 장면 2의 「받아 적기」와 장면 3의 「수사차록법」을 견준 것으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":22,"concept":"K6-2-u3-C19","difficulty":3,"kind":"mc","stem":"「나를 성장시키는 기록법」에서 장면 2의 「받아 적기」와 장면 3의 「수사차록법」을 견준 것으로 알맞은 것은 무엇인가요?","options":[{"t":"장면 2는 그대로 적기만 했고, 장면 3은 생각을 덧붙여 적었다","correct":true},{"t":"두 장면 모두 생각 없이 들은 대로 그대로 적었다","mis":"K6-2-u3-X15"},{"t":"장면 2가 생각을 덧붙인 기록이고 장면 3은 베끼기만 했다","mis":"K6-2-u3-X15"},{"t":"두 장면은 기록과 관계없이 인물을 소개하는 장면이다","mis":"K6-2-u3-X15"}],"explanation":["장면 2는 이해하지 않고 오로지 적기만 했어요.","장면 3의 수사차록법은 자신의 생각을 덧붙여 적었어요.","두 장면을 견주면 생각을 함께 적어야 한다는 주장이 드러나요."],"asset":{"type":"passage","lines":["1 제목 — 나를 성장시키는 기록법","2 열심히 받아 적었는데도 뒤돌아서면 기억하지 못한다.","3 정약용이 활용한 수사차록법","4 이순신의 「난중일기」 — 업무를 정리하고 작전을 세우며 생각을 정리한 기록","5 천재로 불렸던 인물들의 공통점 — 떠오르는 생각을 종이에 기록하는 능력","6 「적자! 생존」 — 잘 적는 사람이 살아남는 현상?"],"numbered":false,"title":"영상 「나를 성장시키는 기록법」의 장면 — 『국어』 131쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#23','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C7',4,'essay','teacher','듣기 자료 「일회용품은 이제 그만」의 주장, 이유, 근거를 파악하고, 이유와 근거가 타당한지 판단 기준에 따라 판단하세요. 그렇게 판단한 까닭도 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u3-C7","difficulty":4,"kind":"essay","stem":"듣기 자료 「일회용품은 이제 그만」의 주장, 이유, 근거를 파악하고, 이유와 근거가 타당한지 판단 기준에 따라 판단하세요. 그렇게 판단한 까닭도 쓰세요.","answer_guide":{"answer":"예: 주장 — 환경을 위해 일회용품 사용을 줄이자. 이유 — 일회용품을 만들려면 많은 자원이 필요하다. / 일회용품은 오랫동안 썩지 않아 환경을 오염시킨다. 근거 — 나무젓가락과 종이컵을 만들려면 나무를 베어야 한다. / 종이컵은 20년, 스티로폼 도시락은 500년이 걸려야 썩는다. 두 이유는 주장과 관련 있고 많은 사람이 받아들일 만하다(◎). 근거도 이유와 관련 있는 정보이지만 숫자가 어디에서 나왔는지 밝히지 않아 출처를 밝히면 더 타당해질 것이다(○).","scoring_points":["주장, 이유, 근거를 바르게 파악했는가","이유를 두 기준으로 판단했는가","근거를 두 기준으로 판단하고 까닭을 썼는가"]},"explanation":["먼저 주장, 이유, 근거를 가려요.","이유와 근거를 기준에 따라 판단해요.","판단마다 까닭을 논리적으로 설명해요."],"asset":{"type":"passage","lines":["(간추림) 종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다.","(간추림) 우리가 편리하게 쓰던 일회용품이 지구를 병들게 하고 있다.","환경을 위해 일회용품 사용을 줄입시다.","(간추림) 일회용품을 만들려면 많은 자원이 필요하다.","(간추림) 나무젓가락과 종이컵을 만들려면 숲의 나무를 베어야 한다.","(간추림) 일회용품은 오랫동안 썩지 않아 환경을 오염시킨다.","(간추림) 땅속에서 썩는 데 종이컵은 20년, 스티로폼 도시락은","(간추림) 500년이 걸린다고 한다."],"numbered":false,"title":"「일회용품은 이제 그만」 — 듣기 자료 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#24','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C13',4,'essay','teacher','댓글 조건 네 가지에 맞게 「낭독의 재발견」에 평가 댓글을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u3-C13","difficulty":4,"kind":"essay","stem":"댓글 조건 네 가지에 맞게 「낭독의 재발견」에 평가 댓글을 쓰세요.","answer_guide":{"answer":"예: 이 영상은 낭독이 글의 내용을 잘 이해하는 데 도움을 준다고 주장하는 것 같아요. 책에 집중하지 못하는 시대에 꼭 필요한 주장이라 가치 있다고 생각해요. 집중력이 떨어지고 있다는 연구 결과를 보여 주어 이유를 잘 뒷받침했어요. 다만 낭독이 이해를 돕는다는 것을 보여 주는 자료도 더 있는지 알려 주실 수 있을까요?","scoring_points":["영상의 주장을 썼는가","주장, 이유, 근거가 타당한지 까닭과 함께 썼는가","타당하지 않은 부분을 정중하게 확인 요청했는가"]},"explanation":["조건 — 주장, 주장의 타당성, 이유와 근거의 타당성과 까닭, 정중한 확인 요청.","예의 바르고 건설적으로 써요.","비방하거나 혐오하는 표현은 쓰지 않아요."],"asset":{"type":"passage","lines":["• 자신이 파악한 영상의 주장이 무엇인지 쓰기","• 주장이 타당한지 쓰기","• 이유와 근거가 타당한지 까닭과 함께 쓰기","• 타당하지 않은 부분에 대해 정중하게 확인 요청하기"],"numbered":false,"title":"영상에 평가 댓글을 쓸 때의 조건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_a#25','kor',6,2,'u3','','tb_g6_2_kor_u3_review_a','unit_review','K6-2-u3-C2',4,'essay','teacher','『국어』 146쪽 스스로 확인하기의 문장 가운데 하나를 골라 이 단원에서 할 수 있게 된 것을 쓰고, 생활 속에서 어떻게 실천할지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u3-C2","difficulty":4,"kind":"essay","stem":"『국어』 146쪽 스스로 확인하기의 문장 가운데 하나를 골라 이 단원에서 할 수 있게 된 것을 쓰고, 생활 속에서 어떻게 실천할지 쓰세요.","answer_guide":{"answer":"예: 나는 자료를 보고 주장, 이유, 근거를 파악할 수 있게 되었다. 앞으로 누리 소통망에서 카드 뉴스를 보면 제목과 강조한 문장에서 주장을 찾고, 이유가 주장과 관련 있는지, 근거가 객관적인 정보인지 따져 본 뒤에 다른 사람에게 전하겠다.","scoring_points":["스스로 확인하기 문장 하나를 골라 썼는가","할 수 있게 된 것을 구체적으로 썼는가","생활 속 실천 방법을 썼는가"]},"explanation":["스스로 확인하기로 단원을 되돌아보아요.","할 수 있게 된 것을 구체적으로 써요.","생활 속에서 실천할 방법을 정해요."],"asset":{"type":"passage","lines":["● 주장, 이유, 근거의 타당성을 판단하며 주장하는 말을 들을 수 있다.","● 자료를 보고 주장, 이유, 근거를 파악할 수 있다.","● 자료에서 제시한 정보가 사실인지 판단할 수 있다.","● 주장하는 말과 자료를 비판적으로 듣거나 봐야 하는 까닭을 말할 수 있다.","[점수] 매우 그렇다: 5 · 그렇다: 4 · 보통이다: 3 · 그렇지 않다: 2 · 매우 그렇지 않다: 1"],"numbered":false,"title":"스스로 확인하기 — 『국어』 146쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#1','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C1',1,'sa','auto','「어떤 주제에 대한 자신의 의견을 드러내는 말」을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":1,"kind":"sa","stem":"「어떤 주제에 대한 자신의 의견을 드러내는 말」을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["주장"],"explanation":["『국어』 118쪽에서 주장, 이유, 근거의 뜻을 배웠어요.","자신의 의견을 드러내는 말은 주장이에요.","그 까닭은 이유, 이유를 받치는 자료는 근거예요."],"mis":"K6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#2','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C2',1,'sa','auto','「누군가의 주장을 받아들이기 전에 한 번 더 생각해야 하는 까닭은 무엇일까요?」에 대한 예상 반응이에요. 「그대로 믿었다가 (    )을/를 볼 수도 있기 때문입니다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C2","difficulty":1,"kind":"sa","stem":"「누군가의 주장을 받아들이기 전에 한 번 더 생각해야 하는 까닭은 무엇일까요?」에 대한 예상 반응이에요. 「그대로 믿었다가 (    )을/를 볼 수도 있기 때문입니다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["손해"],"explanation":["주장에는 사실이 아닌 내용이 담겨 있을 수 있어요.","그대로 믿었다가 손해를 볼 수도 있어요.","그래서 받아들이기 전에 한 번 더 생각해요."],"mis":"K6-2-u3-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#3','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C15',1,'sa','auto','「실수에서 배워요」의 주장이에요. 「실수를 (    )의 기회로 삼을 수 있다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u3-C15","difficulty":1,"kind":"sa","stem":"「실수에서 배워요」의 주장이에요. 「실수를 (    )의 기회로 삼을 수 있다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["배움"],"explanation":["말하는 이는 모든 실수가 나쁜 것은 아니라고 했어요.","실수에서 새로운 것을 배울 수 있다고 했어요.","주장은 실수를 배움의 기회로 삼을 수 있다는 것이에요."],"asset":{"type":"passage","lines":["주장 실수를 배움의 기회로 삼을 수 있다.","이유 실수에서 문제점을 찾으려 노력하면 고칠 점을 발견할 수 있기 때문이다.","근거 실수를 그냥 지나치지 않고 자세히 탐구한 플레밍처럼","      실수를 다시 생각해 보고 반성하면 더 좋은 해결 방법을","      찾을 수 있기 때문이다."],"numbered":false,"title":"「실수에서 배워요」의 주장 · 이유 · 근거 — 『국어』 119쪽 3번"},"mis":"K6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#4','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C16',1,'sa','auto','윤정이는 일주일에 한 번 채식을 하면 일 년에 어떤 나무 열다섯 그루를 심는 효과가 있다고 했나요? 나무 이름을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u3-C16","difficulty":1,"kind":"sa","stem":"윤정이는 일주일에 한 번 채식을 하면 일 년에 어떤 나무 열다섯 그루를 심는 효과가 있다고 했나요? 나무 이름을 쓰세요.","answer":["소나무"],"explanation":["윤정이는 한 기사 내용을 근거로 들었어요.","일주일에 한 번 채식을 하면 소나무 열다섯 그루를 심는 효과가 있다고 했어요.","이 근거는 지구 온난화라는 이유를 뒷받침해요."],"asset":{"type":"passage","lines":["주장 급식에서 채소 위주의 음식을 제공하는 날을 늘리자.","이유 육류를 생산하고 소비하는 과정이 지구 온난화를 가속하는 원인이 되기 때문이다.","근거 일주일에 한 번 채식을 했을 때 일 년에 소나무 열다섯 그루를","      심는 효과가 있다는 기사가 있다."],"numbered":false,"title":"「용기초등학교 어린이 생각 발표회」 윤정이의 말 정리 — 『국어』 124쪽"},"mis":"K6-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#5','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C21',1,'sa','auto','「세력이나 힘을 더 강하고 튼튼하게 함.」이라는 뜻을 가진 낱말을 쓰세요. 『국어』 138쪽 <보기>에서 찾으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u3-C21","difficulty":1,"kind":"sa","stem":"「세력이나 힘을 더 강하고 튼튼하게 함.」이라는 뜻을 가진 낱말을 쓰세요. 『국어』 138쪽 <보기>에서 찾으세요.","answer":["강화"],"explanation":["셋째 장에 「부정적 인식을 강화할 수 있기 때문」이 나와요.","힘을 더 강하고 튼튼하게 하는 것이 강화예요.","<보기>에는 강화, 규제, 조장, 침해가 있어요."],"asset":{"type":"passage","lines":["● 강화: 세력이나 힘을 더 강하고 튼튼하게 함.","● 규제: 규칙이나 규정에 의하여 일정한 한도를 정하거나","  정한 한도를 넘지 못하게 막음.","● 조장: 바람직하지 않은 일을 더 심해지도록 부추김.","● 침해: 침범하여 해를 끼침."],"numbered":false,"title":"카드 뉴스 낱말 알기 보기 — 『국어』 138쪽"},"mis":"K6-2-u3-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#6','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C19',1,'sa','auto','「나를 성장시키는 기록법」의 주장이에요. 「(    )을/를 함께 적은 기록은 자신을 성장시킨다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C19","difficulty":1,"kind":"sa","stem":"「나를 성장시키는 기록법」의 주장이에요. 「(    )을/를 함께 적은 기록은 자신을 성장시킨다.」 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["생각"],"explanation":["그대로 받아 적기만 하면 기억에 남지 않는다고 했어요.","정약용과 이순신은 자신의 생각을 덧붙여 기록했어요.","그래서 주장은 생각을 함께 적은 기록이 자신을 성장시킨다는 것이에요."],"asset":{"type":"passage","lines":["1 제목 — 나를 성장시키는 기록법","2 열심히 받아 적었는데도 뒤돌아서면 기억하지 못한다.","3 정약용이 활용한 수사차록법","4 이순신의 「난중일기」 — 업무를 정리하고 작전을 세우며 생각을 정리한 기록","5 천재로 불렸던 인물들의 공통점 — 떠오르는 생각을 종이에 기록하는 능력","6 「적자! 생존」 — 잘 적는 사람이 살아남는 현상?"],"numbered":false,"title":"영상 「나를 성장시키는 기록법」의 장면 — 『국어』 131쪽"},"mis":"K6-2-u3-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#7','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C20',1,'sa','auto','카드 뉴스 셋째 장에서 피부색에 대한 편견과 차별이 생길 수 있어 ‘살색’ 대신 바꾸어 쓰고 있는 말을 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u3-C20","difficulty":1,"kind":"sa","stem":"카드 뉴스 셋째 장에서 피부색에 대한 편견과 차별이 생길 수 있어 ‘살색’ 대신 바꾸어 쓰고 있는 말을 쓰세요.","answer":["살구색"],"explanation":["‘살색’은 사람의 피부색이 모두 같다는 편견을 심어 줄 수 있어요.","그래서 지금은 ‘살구색’으로 바꾸어 써요.","이 사례는 첫째 이유를 뒷받침하는 근거예요."],"asset":{"type":"passage","lines":["셋째 장 [왜 멈추어야 할까요?] 특정 집단에 대한 부정적 인식을 강화할 수 있기 때문","      [사례] ‘살색’ → ‘살구색’(피부색에 대한 편견과 차별이 생길 수 있어 바꿈)","넷째 장 [왜 멈추어야 할까요?] 많은 사람이 겪고 있기 때문","      [그래프] 국가인권위원회 조사 — 참여자의 70.3퍼센트가 경험함","다섯째 장 [왜 멈추어야 할까요?] 인간의 존엄성을 침해하고 사회적 갈등을 초래하기 때문","      [사례] 독일은 형법으로, 캐나다는 인권법으로 규제 · 우리나라도 제도 마련","여섯째 장 혐오·차별 표현을 멈추는 것이 서로를 존중하는 사회로 나아가는 첫걸음"],"numbered":false,"title":"같은 카드 뉴스 셋째~여섯째 장 간추림 — 『국어』 135~136쪽"},"mis":"K6-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#8','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C14',1,'sa','auto','「쌓다」는 어떻게 발음하나요? 소리 나는 대로 쓰세요. (괄호 [ ]는 쓰지 않아요.)','{}'::text[],false,'{"seq":8,"concept":"K6-2-u3-C14","difficulty":1,"kind":"sa","stem":"「쌓다」는 어떻게 발음하나요? 소리 나는 대로 쓰세요. (괄호 [ ]는 쓰지 않아요.)","answer":["싸타"],"explanation":["받침 ㅎ 뒤에 ㄷ이 왔어요.","ㅎ과 ㄷ이 합쳐져 [ㅌ]으로 소리 나요.","그래서 「쌓다」는 [싸타]예요."],"asset":{"type":"passage","lines":["1 놓다[노타] · 닿다[다ː타] · 쌓다[싸타]","2 받침 ㅎ 뒤에 ㄱ이 오면 [ㅋ], ㄷ이 오면 [ㅌ], ㅈ이 오면 [ㅊ]으로 합쳐 발음해요.","3 놓는[논는] · 쌓는[싼는]","4 받침 ㅎ 뒤에 ㄴ이 오면 ㅎ은 [ㄴ]으로 발음해요."],"numbered":false,"title":"기초 다지기 — 받침 ‘ㅎ’이 들어간 낱말 발음(『국어』 147쪽)"},"mis":"K6-2-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#9','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C4',2,'mc','auto','『국어』 144쪽 1번의 기준 가운데 주장의 타당성을 판단하는 기준은 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X28']::text[],false,'{"seq":9,"concept":"K6-2-u3-C4","difficulty":2,"kind":"mc","stem":"『국어』 144쪽 1번의 기준 가운데 주장의 타당성을 판단하는 기준은 어느 것인가요?","options":[{"t":"㉮ 주장은 가치 있고 중요한가?","correct":true},{"t":"㉰ 이유는 주장을 적절하게 뒷받침하는가?","mis":"K6-2-u3-X01"},{"t":"㉳ 근거는 이유를 적절하게 뒷받침하는가?","mis":"K6-2-u3-X01"},{"t":"㉯ 주장의 길이가 적당한가?","mis":"K6-2-u3-X28"}],"explanation":["㉮는 주장의 타당성을 판단하는 기준이에요.","㉰와 ㉳는 이유와 근거의 타당성을 판단하는 기준이에요.","㉯는 타당성과 관계없는 기준이에요."],"asset":{"type":"passage","lines":["㉮ 주장은 가치 있고 중요한가?","㉯ 주장의 길이가 적당한가?","㉰ 이유는 주장을 적절하게 뒷받침하는가?","㉱ 듣는 사람을 기분 좋게 만드는 이유인가?","㉲ 근거의 종류는 다양한가?","㉳ 근거는 이유를 적절하게 뒷받침하는가?"],"numbered":false,"title":"마무리 1번 — 주장하는 말의 내용을 평가하며 들을 때 필요한 기준 찾기(『국어』 144쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#10','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C3',2,'sa','auto','주장하는 말은 한 번 들은 뒤 다시 듣기 어려워요. 그래서 주장, 이유, 근거를 놓치지 않으려고 쓰는 듣기 방법을 「○○하며 듣기」라고 해요. ○○에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C3","difficulty":2,"kind":"sa","stem":"주장하는 말은 한 번 들은 뒤 다시 듣기 어려워요. 그래서 주장, 이유, 근거를 놓치지 않으려고 쓰는 듣기 방법을 「○○하며 듣기」라고 해요. ○○에 알맞은 두 글자 낱말을 쓰세요.","answer":["메모"],"explanation":["주장하는 말은 되감아 듣기 어려워요.","그래서 들으며 중요한 내용을 적어 두어요.","메모하며 듣기와 요약하며 듣기를 활용해요."],"mis":"K6-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#11','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C6',2,'mc','auto','근거로 제시된 정보가 사실인지 알아보는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X09','K6-2-u3-X03']::text[],false,'{"seq":11,"concept":"K6-2-u3-C6","difficulty":2,"kind":"mc","stem":"근거로 제시된 정보가 사실인지 알아보는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"관련 책이나 기사를 찾아보고 그 출처가 믿을 만한지 다시 살핀다","correct":true},{"t":"검색해서 가장 먼저 나온 글을 그대로 믿고 옮긴다","mis":"K6-2-u3-X09"},{"t":"많은 사람이 퍼 나른 글이면 확인하지 않고 사실로 본다","mis":"K6-2-u3-X03"},{"t":"말한 사람이 자신 있게 말했으면 따로 찾지 않고 사실로 본다","mis":"K6-2-u3-X03"}],"explanation":["근거가 사실인지 판단하려면 관련 책이나 기사를 찾아볼 수 있어요.","인터넷 검색만이 아니라 여러 방법을 쓸 수 있어요.","찾은 자료의 출처가 믿을 만한지도 다시 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#12','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C5',2,'mc','auto','「오류를 찾아라」 놀이의 ㉰ 「플라스틱 사용을 줄여야 한다. 거북이 비닐 때문에 고통받는 걸 보니 너무 슬펐기 때문이다.」를 고친다면 어떤 이유가 알맞을까요?',ARRAY['K6-2-u3-X07','K6-2-u3-X06']::text[],false,'{"seq":12,"concept":"K6-2-u3-C5","difficulty":2,"kind":"mc","stem":"「오류를 찾아라」 놀이의 ㉰ 「플라스틱 사용을 줄여야 한다. 거북이 비닐 때문에 고통받는 걸 보니 너무 슬펐기 때문이다.」를 고친다면 어떤 이유가 알맞을까요?","options":[{"t":"버려진 비닐과 플라스틱이 바다 생물을 다치게 하기 때문이다","correct":true},{"t":"플라스틱이라는 말이 듣기 싫기 때문이다","mis":"K6-2-u3-X07"},{"t":"나는 슬픈 장면을 보면 눈물이 나기 때문이다","mis":"K6-2-u3-X07"},{"t":"거북이는 귀엽기 때문이다","mis":"K6-2-u3-X06"}],"explanation":["「너무 슬펐기 때문」은 말하는 사람의 느낌이에요.","느낌 대신 플라스틱 때문에 생기는 문제를 이유로 들어야 해요.","그래야 많은 사람이 받아들일 만한 이유가 돼요."],"asset":{"type":"passage","lines":["㉮ 모든 사람은 아침에 운동을 해야 한다.","   나는 아침 운동을 하면 기분이 좋기 때문이다.","㉯ 학생들은 교복을 입어야 한다.","   교복을 입으면 싸울 일이 줄어들기 때문이다.","㉰ 플라스틱 사용을 줄여야 한다.","   거북이 비닐 때문에 고통받는 걸 보니 너무 슬펐기 때문이다."],"numbered":false,"title":"「오류를 찾아라」 놀이 — 이유에 오류가 있는 문장의 예"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#13','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C19',2,'mc','auto','「나를 성장시키는 기록법」의 제목을 이렇게 지은 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":13,"concept":"K6-2-u3-C19","difficulty":2,"kind":"mc","stem":"「나를 성장시키는 기록법」의 제목을 이렇게 지은 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"내 생각을 반영한 기록이 쌓여 나를 성장시킬 수 있기 때문","correct":true},{"t":"기록하는 데 쓰는 공책을 소개하려고","mis":"K6-2-u3-X15"},{"t":"받아 적기를 빨리 하는 방법을 알려 주려고","mis":"K6-2-u3-X15"},{"t":"정약용과 이순신의 생애를 차례로 알려 주려고","mis":"K6-2-u3-X15"}],"explanation":["제목은 「나를 성장시키는」 기록법이에요.","생각을 담은 기록이 쌓이면 나를 성장시킬 수 있다는 뜻이에요.","제목을 정한 까닭에서 주장을 짐작할 수 있어요."],"asset":{"type":"passage","lines":["1 제목 — 나를 성장시키는 기록법","2 열심히 받아 적었는데도 뒤돌아서면 기억하지 못한다.","3 정약용이 활용한 수사차록법","4 이순신의 「난중일기」 — 업무를 정리하고 작전을 세우며 생각을 정리한 기록","5 천재로 불렸던 인물들의 공통점 — 떠오르는 생각을 종이에 기록하는 능력","6 「적자! 생존」 — 잘 적는 사람이 살아남는 현상?"],"numbered":false,"title":"영상 「나를 성장시키는 기록법」의 장면 — 『국어』 131쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#14','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C12',2,'mc','auto','이유와 근거 가운데 약한 자리를 찾았을 때 알맞게 판단한 것은 무엇인가요?',ARRAY['K6-2-u3-X20','K6-2-u3-X03','K6-2-u3-X11']::text[],false,'{"seq":14,"concept":"K6-2-u3-C12","difficulty":2,"kind":"mc","stem":"이유와 근거 가운데 약한 자리를 찾았을 때 알맞게 판단한 것은 무엇인가요?","options":[{"t":"약한 자리를 짚고 고칠 방법을 말하되, 주장 전체가 틀렸다고 하지 않는다","correct":true},{"t":"약한 자리가 하나라도 있으면 주장 전체를 믿지 않는다","mis":"K6-2-u3-X20"},{"t":"약한 자리는 모른 척하고 넘어간다","mis":"K6-2-u3-X03"},{"t":"약한 자리만 찾고 타당한 점은 말하지 않는다","mis":"K6-2-u3-X11"}],"explanation":["타당한 점을 먼저 찾아요.","약한 자리는 까닭과 고칠 방법을 함께 말해요.","하나가 약하다고 주장 전체가 틀린 것은 아니에요."],"asset":{"type":"passage","lines":["이유 1 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","이유 2 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 △","이유 3 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","근거 1 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 2 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 3 — 이유와 관련 △ · 객관적인 사실이나 정보 ◎"],"numbered":false,"title":"이유와 근거의 타당성 판단 — 『국어』 139~140쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#15','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C22',2,'mc','auto','「비규격 농산물을 소비하자」에서 이유 ① 「농산물을 저렴하게 구입할 수 있습니다.」를 뒷받침하는 근거는 무엇인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X25']::text[],false,'{"seq":15,"concept":"K6-2-u3-C22","difficulty":2,"kind":"mc","stem":"「비규격 농산물을 소비하자」에서 이유 ① 「농산물을 저렴하게 구입할 수 있습니다.」를 뒷받침하는 근거는 무엇인가요?","options":[{"t":"한국소비자원 조사에서 구매한 까닭의 46.5퍼센트가 가격이 저렴해서였다는 결과","correct":true},{"t":"농림축산식품부 조사에서 버려지는 농산물이 환경에 악영향을 준다는 결과","mis":"K6-2-u3-X01"},{"t":"모양이 예쁜 농산물이 더 잘 자랄 환경이 만들어진다는 말","mis":"K6-2-u3-X25"},{"t":"비규격 농산물은 크기가 작다는 뜻풀이","mis":"K6-2-u3-X01"}],"explanation":["이유 ①은 저렴하게 살 수 있다는 것이에요.","한국소비자원 조사 결과가 그것을 보여 줘요.","농림축산식품부 조사는 이유 ②의 근거예요."],"asset":{"type":"passage","lines":["비규격 농산물은 맛이나 영양은 차이가 없지만 크기가 작거나","상처가 나서 제값을 받지 못하는 농산물입니다.","이유 ① 농산물을 저렴하게 구입할 수 있습니다.","근거 ① 한국소비자원 2021년 조사 — 구매한 까닭의 46.5퍼센트가 저렴해서","이유 ② 자연환경을 보호할 수 있습니다.","근거 ② 농림축산식품부 2023년 조사 — 버려지는 농산물이 환경에 악영향","이유 ③ 모양이 예쁜 농산물을 만들 수 있습니다.","근거 ③ 많이 소비하면 예쁜 농산물이 잘 자랄 환경이 만들어진다고 함"],"numbered":false,"title":"카드 뉴스 「비규격 농산물을 소비하자」 간추림 — 『국어』 145쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#16','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C13',2,'mc','auto','영상을 깊이 있게 이해하는 차례에서 「보기」 단계에 알맞은 모습은 무엇인가요?',ARRAY['K6-2-u3-X22','K6-2-u3-X04']::text[],false,'{"seq":16,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"영상을 깊이 있게 이해하는 차례에서 「보기」 단계에 알맞은 모습은 무엇인가요?","options":[{"t":"해석하지 않고 영상에서 관찰한 것만 말한다","correct":true},{"t":"본 것과 짐작한 것을 섞어 바로 주제를 말한다","mis":"K6-2-u3-X22"},{"t":"보기 전에 결론부터 정한다","mis":"K6-2-u3-X04"},{"t":"궁금한 것부터 묻고 영상은 보지 않는다","mis":"K6-2-u3-X22"}],"explanation":["먼저 2~3분 동안 조용히 자세히 관찰해요.","보기 단계에서는 관찰한 것만 말해요.","생각하기와 궁금해하기는 그다음이에요."],"asset":{"type":"passage","lines":["1 준비하기 — 이야기를 시작하기 전에 2~3분 동안 조용히 자세히 관찰한다.","2 보기 — 해석이 아니라 관찰하여 알아낸 것만 말한다.","3 생각하기 — 영상에서 무슨 일이 일어나고 있다고 생각하는지 말한다.","4 궁금해하기 — 보고 생각해 온 것을 바탕으로 지금 궁금한 것을 묻는다."],"numbered":false,"title":"영상의 내용을 깊이 있게 이해하는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#17','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C1',3,'mc','auto','「일회용품은 이제 그만」에서 「땅속에서 썩는 데 종이컵은 20년, 스티로폼 도시락은 500년이 걸린다」는 어떤 이유를 뒷받침하나요?',ARRAY['K6-2-u3-X25','K6-2-u3-X06','K6-2-u3-X01']::text[],false,'{"seq":17,"concept":"K6-2-u3-C1","difficulty":3,"kind":"mc","stem":"「일회용품은 이제 그만」에서 「땅속에서 썩는 데 종이컵은 20년, 스티로폼 도시락은 500년이 걸린다」는 어떤 이유를 뒷받침하나요?","options":[{"t":"일회용품은 오랫동안 썩지 않아 환경을 오염시킨다","correct":true},{"t":"일회용품을 만들려면 많은 자원이 필요하다","mis":"K6-2-u3-X25"},{"t":"일회용품은 편리하게 쓸 수 있다","mis":"K6-2-u3-X06"},{"t":"일회용품 사용을 줄이자","mis":"K6-2-u3-X01"}],"explanation":["이유는 두 가지예요 — 많은 자원이 필요하다, 오랫동안 썩지 않아 오염시킨다.","썩는 데 걸리는 햇수는 오랫동안 썩지 않는다는 것을 보여 줘요.","그래서 둘째 이유의 근거예요."],"asset":{"type":"passage","lines":["(간추림) 종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다.","(간추림) 우리가 편리하게 쓰던 일회용품이 지구를 병들게 하고 있다.","환경을 위해 일회용품 사용을 줄입시다.","(간추림) 일회용품을 만들려면 많은 자원이 필요하다.","(간추림) 나무젓가락과 종이컵을 만들려면 숲의 나무를 베어야 한다.","(간추림) 일회용품은 오랫동안 썩지 않아 환경을 오염시킨다.","(간추림) 땅속에서 썩는 데 종이컵은 20년, 스티로폼 도시락은","(간추림) 500년이 걸린다고 한다."],"numbered":false,"title":"「일회용품은 이제 그만」 — 듣기 자료 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#18','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C6',3,'mc','auto','「일회용품은 이제 그만」의 근거를 더 믿을 만하게 하려면 무엇을 덧붙이면 좋을까요?',ARRAY['K6-2-u3-X14','K6-2-u3-X08','K6-2-u3-X06']::text[],false,'{"seq":18,"concept":"K6-2-u3-C6","difficulty":3,"kind":"mc","stem":"「일회용품은 이제 그만」의 근거를 더 믿을 만하게 하려면 무엇을 덧붙이면 좋을까요?","options":[{"t":"「~고 합니다」로 전한 숫자가 어느 기관이나 자료에서 나왔는지 출처","correct":true},{"t":"「꼭 줄여야 합니다!」를 여러 번 되풀이하는 말","mis":"K6-2-u3-X14"},{"t":"말하는 이가 일회용품을 싫어한다는 느낌","mis":"K6-2-u3-X08"},{"t":"일회용품과 관계없는 동물 이야기","mis":"K6-2-u3-X06"}],"explanation":["근거로 든 숫자는 객관적인 정보처럼 보여요.","하지만 어디에서 나온 자료인지 밝히지 않았어요.","출처를 밝히면 듣는 사람이 확인할 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다.","(간추림) 우리가 편리하게 쓰던 일회용품이 지구를 병들게 하고 있다.","환경을 위해 일회용품 사용을 줄입시다.","(간추림) 일회용품을 만들려면 많은 자원이 필요하다.","(간추림) 나무젓가락과 종이컵을 만들려면 숲의 나무를 베어야 한다.","(간추림) 일회용품은 오랫동안 썩지 않아 환경을 오염시킨다.","(간추림) 땅속에서 썩는 데 종이컵은 20년, 스티로폼 도시락은","(간추림) 500년이 걸린다고 한다."],"numbered":false,"title":"「일회용품은 이제 그만」 — 듣기 자료 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#19','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C13',3,'mc','auto','영상 평가 댓글의 마지막 조건 「타당하지 않은 부분에 대해 정중하게 확인 요청하기」에 알맞은 문장은 무엇인가요?',ARRAY['K6-2-u3-X27','K6-2-u3-X20']::text[],false,'{"seq":19,"concept":"K6-2-u3-C13","difficulty":3,"kind":"mc","stem":"영상 평가 댓글의 마지막 조건 「타당하지 않은 부분에 대해 정중하게 확인 요청하기」에 알맞은 문장은 무엇인가요?","options":[{"t":"「근거로 든 조사 결과가 어디에서 나왔는지 알려 주실 수 있을까요?」","correct":true},{"t":"「이런 엉터리 영상은 도대체 왜 만들었어요?」","mis":"K6-2-u3-X27"},{"t":"「근거가 없으니 이 영상은 처음부터 끝까지 다 거짓말이네요.」","mis":"K6-2-u3-X20"},{"t":"「재미없어요. 다시는 이런 영상 올리지 마세요.」","mis":"K6-2-u3-X27"}],"explanation":["확인 요청은 궁금한 점을 예의 바르게 묻는 것이에요.","비방하거나 단정하는 말은 건설적인 비판이 아니에요.","근거의 출처를 정중하게 묻는 것이 알맞아요."],"asset":{"type":"passage","lines":["• 자신이 파악한 영상의 주장이 무엇인지 쓰기","• 주장이 타당한지 쓰기","• 이유와 근거가 타당한지 까닭과 함께 쓰기","• 타당하지 않은 부분에 대해 정중하게 확인 요청하기"],"numbered":false,"title":"영상에 평가 댓글을 쓸 때의 조건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#20','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C13',3,'mc','auto','영상 평가표에 「비속어를 쓰는가?」 같은 표현 기준을 더하고 싶을 때 알맞은 방법은 무엇인가요?',ARRAY['K6-2-u3-X21','K6-2-u3-X02']::text[],false,'{"seq":20,"concept":"K6-2-u3-C13","difficulty":3,"kind":"mc","stem":"영상 평가표에 「비속어를 쓰는가?」 같은 표현 기준을 더하고 싶을 때 알맞은 방법은 무엇인가요?","options":[{"t":"내용의 타당성을 먼저 평가한 뒤 표현 기준을 덧붙인다","correct":true},{"t":"표현 기준만으로 영상의 좋고 나쁨을 평가한다","mis":"K6-2-u3-X21"},{"t":"표현 기준은 평가표에 절대 넣으면 안 된다","mis":"K6-2-u3-X02"},{"t":"표현 기준을 가장 먼저, 가장 무겁게 본다","mis":"K6-2-u3-X21"}],"explanation":["표현 기준을 넣고 싶다면 넣어도 돼요.","하지만 내용의 타당성을 먼저 충분히 평가해요.","표현은 그다음에 덧붙여 판단해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#21','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C8',3,'mc','auto','「용기초등학교 어린이 생각 발표회」에서 현우가 「한 연구 결과에 따르면」이라고 말한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X14','K6-2-u3-X13']::text[],false,'{"seq":21,"concept":"K6-2-u3-C8","difficulty":3,"kind":"mc","stem":"「용기초등학교 어린이 생각 발표회」에서 현우가 「한 연구 결과에 따르면」이라고 말한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"근거가 연구에서 나온 정보임을 밝히려고","correct":true},{"t":"말을 더 길고 어렵게 들리게 하려고","mis":"K6-2-u3-X08"},{"t":"듣는 사람이 충치가 무서워 겁을 먹게 하려고","mis":"K6-2-u3-X14"},{"t":"근거가 어디에서 나왔는지 숨기려고","mis":"K6-2-u3-X13"}],"explanation":["현우는 단백질이 부족하면 충치 위험이 높아질 수 있다는 연구 결과를 들었어요.","연구 결과라고 밝혀 객관적인 정보임을 드러냈어요.","더 믿을 만하려면 어떤 연구인지도 밝히면 좋아요."],"asset":{"type":"passage","lines":["주장 질 좋은 고기반찬을 더 충분히 제공하자.","이유 질 좋은 고기반찬으로만 성장에 필요한 단백질을 섭취할 수 있기 때문이다.","근거 단백질 섭취 부족 시 충치 발생 위험이 높아질 수 있다는 연구 결과가 있다."],"numbered":false,"title":"「용기초등학교 어린이 생각 발표회」 현우의 말 정리 — 『국어』 124쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#22','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C18',3,'mc','auto','「낭독의 재발견」의 주장을 찾을 때 세 가지 요소를 합친 것으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":22,"concept":"K6-2-u3-C18","difficulty":3,"kind":"mc","stem":"「낭독의 재발견」의 주장을 찾을 때 세 가지 요소를 합친 것으로 알맞은 것은 무엇인가요?","options":[{"t":"제목 + 자료 + 강조를 합쳐 → 낭독은 글의 내용을 잘 이해하는 데 도움을 준다","correct":true},{"t":"자료(캐나다 연구) 하나만 보고 → 캐나다 사람들은 집중력이 낮다","mis":"K6-2-u3-X15"},{"t":"제목 하나만 보고 → 낭독은 오래되어 이제 쓰지 않는 방법이다","mis":"K6-2-u3-X15"},{"t":"강조 하나만 보고 → 입과 몸과 마음이 건강해야 한다","mis":"K6-2-u3-X15"}],"explanation":["한 요소만 보면 주장을 잘못 세울 수 있어요.","제목, 자료, 강조를 합쳐요.","그러면 낭독이 글의 내용을 이해하는 데 도움을 준다는 주장이 나와요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"영상의 제목을 ‘낭독의 재발견’으로 정한 까닭은 무엇일까?"},{"who":"규민","text":"오래된 방법이라고 생각했던 낭독의 효과를 다시 한번 알려 주기 위해서야."},{"who":"지호","text":"인간의 집중력이 점점 떨어지고 있다는 실험 결과를 보여 주는 자료를 제시한 까닭은 무엇일까?"},{"who":"규민","text":"집중력과 기억력 향상에 도움이 되는 낭독의 필요성을 보여 주는 정보를 제시하고 싶었기 때문이야."},{"who":"지호","text":"영상에서 ‘입, 몸, 마음’이라는 낱말을 굵은 글자로 강조한 까닭은 무엇일까?"},{"who":"규민","text":"낭독의 긍정적인 효과를 강조해서 표현하기 위해서야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#23','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C5',4,'essay','teacher','「일회용품은 이제 그만」에서 말하는 이가 처음에 든 「종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다」는 정보가 어떤 이유를 뒷받침하는지 쓰고, 이 정보가 사실인지 확인하는 방법을 두 가지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u3-C5","difficulty":4,"kind":"essay","stem":"「일회용품은 이제 그만」에서 말하는 이가 처음에 든 「종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다」는 정보가 어떤 이유를 뒷받침하는지 쓰고, 이 정보가 사실인지 확인하는 방법을 두 가지 쓰세요.","answer_guide":{"answer":"예: 이 정보는 일회용품을 만들려면 많은 자원이 필요하다는 이유를 뒷받침한다. 종이컵 하나에도 나무가 많이 든다는 것을 숫자로 보여 주기 때문이다. 이 정보가 사실인지 확인하려면 관련 내용을 다룬 책이나 기사를 찾아보고, 그 기사를 쓴 곳이 믿을 만한 기관인지 출처를 다시 살펴보겠다.","scoring_points":["뒷받침하는 이유를 바르게 썼는가","이유와 이어지는 까닭을 썼는가","책·기사 찾기와 출처 확인 같은 방법을 두 가지 썼는가"]},"explanation":["근거는 어떤 이유를 보여 주는지부터 살펴요.","숫자 정보도 사실인지 확인해요.","여러 방법으로 확인하고 출처를 살펴요."],"asset":{"type":"passage","lines":["(간추림) 종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다.","(간추림) 우리가 편리하게 쓰던 일회용품이 지구를 병들게 하고 있다.","환경을 위해 일회용품 사용을 줄입시다.","(간추림) 일회용품을 만들려면 많은 자원이 필요하다.","(간추림) 나무젓가락과 종이컵을 만들려면 숲의 나무를 베어야 한다.","(간추림) 일회용품은 오랫동안 썩지 않아 환경을 오염시킨다.","(간추림) 땅속에서 썩는 데 종이컵은 20년, 스티로폼 도시락은","(간추림) 500년이 걸린다고 한다."],"numbered":false,"title":"「일회용품은 이제 그만」 — 듣기 자료 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#24','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C13',4,'essay','teacher','댓글 조건 네 가지에 맞게 「나를 성장시키는 기록법」에 평가 댓글을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u3-C13","difficulty":4,"kind":"essay","stem":"댓글 조건 네 가지에 맞게 「나를 성장시키는 기록법」에 평가 댓글을 쓰세요.","answer_guide":{"answer":"예: 이 영상의 주장은 생각을 함께 적은 기록이 자신을 성장시킨다는 것이라고 생각해요. 누구나 바로 실천할 수 있는 가치 있는 주장이에요. 정약용과 이순신의 기록을 사례로 들어 이유를 잘 뒷받침했어요. 그런데 천재로 불렸던 인물들이 모두 기록하는 습관이 있었다는 내용은 어디에서 나온 자료인지 알려 주실 수 있을까요?","scoring_points":["영상의 주장을 썼는가","주장, 이유, 근거가 타당한지 까닭과 함께 썼는가","타당하지 않은 부분을 정중하게 확인 요청했는가"]},"explanation":["먼저 영상의 주장을 한 문장으로 써요.","타당한 점과 까닭을 써요.","궁금하거나 부족한 점은 정중하게 물어요."],"asset":{"type":"passage","lines":["• 자신이 파악한 영상의 주장이 무엇인지 쓰기","• 주장이 타당한지 쓰기","• 이유와 근거가 타당한지 까닭과 함께 쓰기","• 타당하지 않은 부분에 대해 정중하게 확인 요청하기"],"numbered":false,"title":"영상에 평가 댓글을 쓸 때의 조건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_b#25','kor',6,2,'u3','','tb_g6_2_kor_u3_review_b','unit_review','K6-2-u3-C2',4,'essay','teacher','주장하는 말과 자료를 비판적으로 듣거나 봐야 하는 까닭을 이 단원에서 배운 말을 넣어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u3-C2","difficulty":4,"kind":"essay","stem":"주장하는 말과 자료를 비판적으로 듣거나 봐야 하는 까닭을 이 단원에서 배운 말을 넣어 쓰세요.","answer_guide":{"answer":"예: 주장하는 말과 자료에는 사실이 아닌 내용이 담겨 있을 수 있어서 그대로 믿으면 손해를 보거나 잘못된 정보를 퍼뜨릴 수 있다. 주장이 가치 있고 중요한지, 이유와 근거가 주장과 이유를 적절하게 뒷받침하는지 따져 보면 잘못된 정보를 걸러 내고 믿을 만한 정보를 골라 쓸 수 있다.","scoring_points":["그대로 믿었을 때의 문제를 썼는가","타당성 판단 기준을 넣었는가","비판적으로 보면 좋은 점을 썼는가"]},"explanation":["비판적으로 보기는 무조건 의심하기가 아니에요.","주장, 이유, 근거의 기준으로 따져요.","잘못된 정보를 걸러 내고 믿을 만한 정보를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#1','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C1',1,'ox','auto','「이유는 근거를 뒷받침하는 자료나 사실이에요.」라는 말은 바른 말이에요.',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":1,"kind":"ox","stem":"「이유는 근거를 뒷받침하는 자료나 사실이에요.」라는 말은 바른 말이에요.","answer":"X","reason_options":[{"t":"이유를 뒷받침하는 자료나 사실은 근거이고, 이유는 왜 그렇게 주장하는지 설명하는 말이기 때문에","correct":true},{"t":"이유와 근거는 같은 말이어서 바꾸어 써도 되기 때문에","mis":"K6-2-u3-X01"}],"mis":"K6-2-u3-X01","explanation":["이유와 근거의 자리가 바뀌었어요.","이유는 왜 그렇게 주장하는지 설명해요.","근거가 이유를 뒷받침해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#2','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C2',1,'ox','auto','자료의 근거가 사실인지 확인하면 잘못된 정보를 걸러 낼 수 있어요.',ARRAY['K6-2-u3-X02']::text[],false,'{"seq":2,"concept":"K6-2-u3-C2","difficulty":1,"kind":"ox","stem":"자료의 근거가 사실인지 확인하면 잘못된 정보를 걸러 낼 수 있어요.","answer":"O","reason_options":[{"t":"근거가 사실이 아니면 그 자료를 그대로 믿거나 옮기지 않을 수 있기 때문에","correct":true},{"t":"근거를 확인하면 모든 자료가 틀렸다는 것을 알게 되기 때문에","mis":"K6-2-u3-X02"}],"mis":"K6-2-u3-X02","explanation":["『국어』 117쪽에서 친구가 한 말이에요.","근거가 사실인지 확인하면 잘못된 정보를 걸러 낼 수 있어요.","확인한다고 모든 자료가 틀린 것은 아니에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"주장하는 내용이 내 의견과 어떻게 같거나 다른지 비교할 수 있어."},{"who":"친구 2","text":"이유가 확실한 정보는 믿고 활용할 수 있어."},{"who":"친구 3","text":"근거가 사실인지 확인하면 잘못된 정보를 걸러 낼 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#3','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C15',1,'ox','auto','「실수에서 배워요」에서 말하는 이는 실수를 했느냐보다 실수에서 무엇을 배우고 실천하느냐가 중요하다고 했어요.',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":3,"concept":"K6-2-u3-C15","difficulty":1,"kind":"ox","stem":"「실수에서 배워요」에서 말하는 이는 실수를 했느냐보다 실수에서 무엇을 배우고 실천하느냐가 중요하다고 했어요.","answer":"O","reason_options":[{"t":"실수를 되돌아보고 반성하면 잘못한 행동을 고치고 더 좋은 방법을 찾을 수 있다고 했기 때문에","correct":true},{"t":"실수를 한 번도 하지 않는 것이 가장 중요하다고 했기 때문에","mis":"K6-2-u3-X04"}],"mis":"K6-2-u3-X04","explanation":["말하는 이는 플레밍의 일화를 들었어요.","실수를 그냥 지나치지 않고 탐구하는 것이 중요하다고 했어요.","실수에서 배우고 실천하느냐가 중요하다는 말이에요."],"asset":{"type":"passage","lines":["실수는 조심하지 않아서 잘못하는 행동을 말합니다.","(간추림) 친구와 부딪치는 실수, 약속을 깜빡 잊는 실수는 우리를 속상하게 한다.","하지만 모든 실수가 나쁜 것은 아닙니다.","(간추림) 실수에서 문제점을 찾으려 노력하면 고칠 점을 발견할 수 있다.","(간추림) 1928년 플레밍은 포도상 구균을 기르던 접시를","(간추림) 실수로 배양기 밖에 두고 휴가를 떠났다.","(간추림) 돌아와 미생물이 줄어든 것을 보고 페니실린을 발견했다.","(간추림) 실수를 했느냐보다 무엇을 배우고 실천하느냐가 중요하다."],"numbered":false,"title":"「실수에서 배워요」 — 『국어』 118쪽 듣기 자료 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#4','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C16',1,'ox','auto','현우는 학교 급식에서 질 좋은 고기반찬을 더 충분히 제공해야 한다고 주장했어요.',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":4,"concept":"K6-2-u3-C16","difficulty":1,"kind":"ox","stem":"현우는 학교 급식에서 질 좋은 고기반찬을 더 충분히 제공해야 한다고 주장했어요.","answer":"O","reason_options":[{"t":"성장에 필요한 단백질을 섭취하려면 질 좋은 고기반찬이 필요하다고 말했기 때문에","correct":true},{"t":"고기반찬을 줄이고 채소 위주의 음식을 늘리자고 말했기 때문에","mis":"K6-2-u3-X04"}],"mis":"K6-2-u3-X04","explanation":["채소 위주의 음식을 늘리자는 것은 윤정이의 주장이에요.","현우는 질 좋은 고기반찬을 더 충분히 제공하자고 했어요.","단백질 섭취를 그 이유로 들었어요."],"asset":{"type":"passage","lines":["주장 질 좋은 고기반찬을 더 충분히 제공하자.","이유 질 좋은 고기반찬으로만 성장에 필요한 단백질을 섭취할 수 있기 때문이다.","근거 단백질 섭취 부족 시 충치 발생 위험이 높아질 수 있다는 연구 결과가 있다."],"numbered":false,"title":"「용기초등학교 어린이 생각 발표회」 현우의 말 정리 — 『국어』 124쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#5','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C17',1,'ox','auto','「대항하다」는 「점점 속도를 더하다.」라는 뜻이에요.',ARRAY['K6-2-u3-X29']::text[],false,'{"seq":5,"concept":"K6-2-u3-C17","difficulty":1,"kind":"ox","stem":"「대항하다」는 「점점 속도를 더하다.」라는 뜻이에요.","answer":"X","reason_options":[{"t":"「대항하다」는 굽히거나 지지 않으려고 맞서서 버티는 것이고, 점점 속도를 더하는 것은 「가속하다」이기 때문에","correct":true},{"t":"「대항하다」와 「가속하다」는 뜻이 같기 때문에","mis":"K6-2-u3-X29"}],"mis":"K6-2-u3-X29","explanation":["현우는 단백질이 질병에 대항하는 면역력을 높인다고 했어요.","「대항하다」는 맞서서 버틴다는 뜻이에요.","「점점 속도를 더하다」는 「가속하다」예요."],"asset":{"type":"passage","lines":["보기: 가속하다 · 대항하다 · 발생하다 · 섭취하다 · 제공하다","㉮ 생물체가 양분 따위를 몸속에 빨아들이다.","㉯ 무엇을 내주거나 갖다 바치다.","㉰ 굽히거나 지지 않으려고 맞서서 버티거나 항거하다.","㉱ 점점 속도를 더하다."],"numbered":false,"title":"「용기초등학교 어린이 생각 발표회」 낱말 알기 — 『국어』 125쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#6','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C9',1,'ox','auto','영상은 주장하는 글이나 연설처럼 주장을 언제나 직접 말해 줘요.',ARRAY['K6-2-u3-X16']::text[],false,'{"seq":6,"concept":"K6-2-u3-C9","difficulty":1,"kind":"ox","stem":"영상은 주장하는 글이나 연설처럼 주장을 언제나 직접 말해 줘요.","answer":"X","reason_options":[{"t":"영상은 자료를 보여 주고 보는 사람이 주장을 추론하게 만드는 경우가 많기 때문에","correct":true},{"t":"영상에 나오는 첫 문장이 언제나 주장이기 때문에","mis":"K6-2-u3-X16"}],"mis":"K6-2-u3-X16","explanation":["영상은 주장을 직접 말하지 않는 경우가 많아요.","제시한 자료를 바탕으로 보는 사람이 주장을 추론해요.","제목, 자료, 강조를 함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#7','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C20',1,'ox','auto','카드 뉴스 넷째 장의 그래프는 혐오·차별 표현을 많은 사람이 겪고 있다는 이유를 뒷받침하는 근거예요.',ARRAY['K6-2-u3-X10']::text[],false,'{"seq":7,"concept":"K6-2-u3-C20","difficulty":1,"kind":"ox","stem":"카드 뉴스 넷째 장의 그래프는 혐오·차별 표현을 많은 사람이 겪고 있다는 이유를 뒷받침하는 근거예요.","answer":"O","reason_options":[{"t":"국가인권위원회 조사에서 참여자의 70.3퍼센트가 혐오·차별 표현을 경험했다는 것을 보여 주기 때문에","correct":true},{"t":"그래프는 카드 뉴스를 꾸미려고 넣은 그림일 뿐이기 때문에","mis":"K6-2-u3-X10"}],"mis":"K6-2-u3-X10","explanation":["넷째 장의 이유는 「많은 사람이 겪고 있기 때문」이에요.","그래프는 경험한 사람이 많다는 것을 보여 줘요.","그래프도 근거 자료의 한 갈래예요."],"asset":{"type":"passage","lines":["셋째 장 [왜 멈추어야 할까요?] 특정 집단에 대한 부정적 인식을 강화할 수 있기 때문","      [사례] ‘살색’ → ‘살구색’(피부색에 대한 편견과 차별이 생길 수 있어 바꿈)","넷째 장 [왜 멈추어야 할까요?] 많은 사람이 겪고 있기 때문","      [그래프] 국가인권위원회 조사 — 참여자의 70.3퍼센트가 경험함","다섯째 장 [왜 멈추어야 할까요?] 인간의 존엄성을 침해하고 사회적 갈등을 초래하기 때문","      [사례] 독일은 형법으로, 캐나다는 인권법으로 규제 · 우리나라도 제도 마련","여섯째 장 혐오·차별 표현을 멈추는 것이 서로를 존중하는 사회로 나아가는 첫걸음"],"numbered":false,"title":"같은 카드 뉴스 셋째~여섯째 장 간추림 — 『국어』 135~136쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#8','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C14',1,'ox','auto','「놓는」은 [노는]으로 발음해요.',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":8,"concept":"K6-2-u3-C14","difficulty":1,"kind":"ox","stem":"「놓는」은 [노는]으로 발음해요.","answer":"X","reason_options":[{"t":"받침 ㅎ 뒤에 ㄴ이 오면 ㅎ은 [ㄴ]으로 소리 나 [논는]으로 발음하기 때문에","correct":true},{"t":"받침 ㅎ 뒤에 ㄴ이 오면 ㅎ은 아무 소리도 나지 않기 때문에","mis":"K6-2-u3-X23"}],"mis":"K6-2-u3-X23","explanation":["「놓는」은 받침 ㅎ 뒤에 ㄴ이 왔어요.","이때 ㅎ은 [ㄴ]으로 소리 나요.","그래서 [논는]이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#9','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C6',2,'ox','auto','「근거의 종류는 다양한가?」는 주장하는 말의 타당성을 평가할 때 필요한 기준이에요.',ARRAY['K6-2-u3-X28']::text[],false,'{"seq":9,"concept":"K6-2-u3-C6","difficulty":2,"kind":"ox","stem":"「근거의 종류는 다양한가?」는 주장하는 말의 타당성을 평가할 때 필요한 기준이에요.","answer":"X","reason_options":[{"t":"근거는 종류가 많은지가 아니라 이유와 관련 있고 객관적인 사실이나 정보인지로 판단하기 때문에","correct":true},{"t":"근거는 종류가 많을수록 언제나 더 타당하기 때문에","mis":"K6-2-u3-X28"}],"mis":"K6-2-u3-X28","explanation":["근거가 여러 종류라도 이유와 관련 없으면 뒷받침하지 못해요.","근거는 이유와 관련 있는지 살펴요.","그리고 객관적인 사실이나 정보인지 살펴요."],"asset":{"type":"passage","lines":["㉮ 주장은 가치 있고 중요한가?","㉯ 주장의 길이가 적당한가?","㉰ 이유는 주장을 적절하게 뒷받침하는가?","㉱ 듣는 사람을 기분 좋게 만드는 이유인가?","㉲ 근거의 종류는 다양한가?","㉳ 근거는 이유를 적절하게 뒷받침하는가?"],"numbered":false,"title":"마무리 1번 — 주장하는 말의 내용을 평가하며 들을 때 필요한 기준 찾기(『국어』 144쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#10','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C3',2,'ox','auto','주장하는 말을 들을 때에는 말하는 이의 표현이나 태도도 주의하며 들을 수 있어요.',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":10,"concept":"K6-2-u3-C3","difficulty":2,"kind":"ox","stem":"주장하는 말을 들을 때에는 말하는 이의 표현이나 태도도 주의하며 들을 수 있어요.","answer":"O","reason_options":[{"t":"주장, 이유, 근거뿐 아니라 어떤 태도로 말하는지 비판적으로 듣는 것도 중요하기 때문에","correct":true},{"t":"내용보다 말하는 이의 옷차림이 더 중요하기 때문에","mis":"K6-2-u3-X04"}],"mis":"K6-2-u3-X04","explanation":["주장하는 말을 평가할 때 주장, 이유, 근거를 파악해요.","말하는 이가 어떤 태도로 말하는지도 살펴요.","지나치게 감정에 호소하지는 않는지 주의해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#11','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C6',2,'ox','auto','「카드 뉴스 넷째 장의 국가인권위원회 조사 그래프」는 근거 자료의 유형 가운데 그래프에 해당해요.',ARRAY['K6-2-u3-X10']::text[],false,'{"seq":11,"concept":"K6-2-u3-C6","difficulty":2,"kind":"ox","stem":"「카드 뉴스 넷째 장의 국가인권위원회 조사 그래프」는 근거 자료의 유형 가운데 그래프에 해당해요.","answer":"O","reason_options":[{"t":"조사 결과를 막대로 나타내 보여 주는 자료이기 때문에","correct":true},{"t":"사람과 묻고 답한 말을 옮긴 면담 자료이기 때문에","mis":"K6-2-u3-X10"}],"mis":"K6-2-u3-X10","explanation":["넷째 장에는 조사 결과를 나타낸 그래프가 있어요.","근거 자료의 유형에는 표, 그래프, 면담 자료, 사례가 있어요.","이 자료는 그래프에 해당해요."],"asset":{"type":"passage","lines":["셋째 장 [왜 멈추어야 할까요?] 특정 집단에 대한 부정적 인식을 강화할 수 있기 때문","      [사례] ‘살색’ → ‘살구색’(피부색에 대한 편견과 차별이 생길 수 있어 바꿈)","넷째 장 [왜 멈추어야 할까요?] 많은 사람이 겪고 있기 때문","      [그래프] 국가인권위원회 조사 — 참여자의 70.3퍼센트가 경험함","다섯째 장 [왜 멈추어야 할까요?] 인간의 존엄성을 침해하고 사회적 갈등을 초래하기 때문","      [사례] 독일은 형법으로, 캐나다는 인권법으로 규제 · 우리나라도 제도 마련","여섯째 장 혐오·차별 표현을 멈추는 것이 서로를 존중하는 사회로 나아가는 첫걸음"],"numbered":false,"title":"같은 카드 뉴스 셋째~여섯째 장 간추림 — 『국어』 135~136쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#12','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C5',2,'ox','auto','스쿨 존 카드 뉴스의 이유 ① 「어린이들의 안전을 지키는 일이기 때문이다.」는 주장을 적절하게 뒷받침해요.',ARRAY['K6-2-u3-X06']::text[],false,'{"seq":12,"concept":"K6-2-u3-C5","difficulty":2,"kind":"ox","stem":"스쿨 존 카드 뉴스의 이유 ① 「어린이들의 안전을 지키는 일이기 때문이다.」는 주장을 적절하게 뒷받침해요.","answer":"O","reason_options":[{"t":"스쿨 존에서 교통 법규를 지키자는 주장과 바로 이어지고 많은 사람이 받아들일 만하기 때문에","correct":true},{"t":"안전이라는 말이 들어가면 어떤 주장이든 뒷받침하기 때문에","mis":"K6-2-u3-X06"}],"mis":"K6-2-u3-X06","explanation":["주장은 스쿨 존에서 교통 법규를 지키자는 것이에요.","어린이의 안전을 지키는 일은 그 주장과 바로 이어져요.","많은 사람이 고개를 끄덕일 만한 이유예요."],"asset":{"type":"passage","lines":["[제목] 줄이세요, 어린이 보호 구역 ‘스쿨 존’입니다.","주장 어린이 보호 구역인 스쿨 존에서는 교통 법규를 지키자.","이유 ① 어린이들의 안전을 지키는 일이기 때문이다.","이유 ② 교통 법규를 지키지 않으면 벌금을 내야 하기 때문이다.","근거 ① 스쿨 존에 설치하는 시설물의 종류","근거 ② 법규를 위반했을 때 벌금을 내는 기준"],"numbered":false,"title":"세상과 연결하기 — 모둠이 정한 카드 뉴스 예시(『국어』 141쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#13','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C19',2,'ox','auto','「나를 성장시키는 기록법」의 수사차록법은 중요하다고 생각하는 부분을 베껴 쓰되 자신의 생각을 덧붙여 기록하는 방법이에요.',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":13,"concept":"K6-2-u3-C19","difficulty":2,"kind":"ox","stem":"「나를 성장시키는 기록법」의 수사차록법은 중요하다고 생각하는 부분을 베껴 쓰되 자신의 생각을 덧붙여 기록하는 방법이에요.","answer":"O","reason_options":[{"t":"정약용은 베껴 쓰는 데서 그치지 않고 자신의 생각을 덧붙였기 때문에","correct":true},{"t":"정약용은 생각을 덧붙이지 않고 들은 대로만 받아 적었기 때문에","mis":"K6-2-u3-X15"}],"mis":"K6-2-u3-X15","explanation":["장면 3에는 정약용의 수사차록법이 나와요.","중요한 부분을 베껴 쓰되 자신의 생각을 덧붙여 기록해요.","생각을 함께 적은 기록이라는 주장과 이어져요."],"asset":{"type":"passage","lines":["1 제목 — 나를 성장시키는 기록법","2 열심히 받아 적었는데도 뒤돌아서면 기억하지 못한다.","3 정약용이 활용한 수사차록법","4 이순신의 「난중일기」 — 업무를 정리하고 작전을 세우며 생각을 정리한 기록","5 천재로 불렸던 인물들의 공통점 — 떠오르는 생각을 종이에 기록하는 능력","6 「적자! 생존」 — 잘 적는 사람이 살아남는 현상?"],"numbered":false,"title":"영상 「나를 성장시키는 기록법」의 장면 — 『국어』 131쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#14','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C12',2,'ox','auto','「혐오·차별 표현은 많은 사람이 겪고 있기 때문입니다.」는 혐오·차별 표현을 왜 멈추어야 하는지를 직접 보여 주는 이유예요.',ARRAY['K6-2-u3-X18']::text[],false,'{"seq":14,"concept":"K6-2-u3-C12","difficulty":2,"kind":"ox","stem":"「혐오·차별 표현은 많은 사람이 겪고 있기 때문입니다.」는 혐오·차별 표현을 왜 멈추어야 하는지를 직접 보여 주는 이유예요.","answer":"X","reason_options":[{"t":"얼마나 많은 사람이 겪는지라는 규모만 말할 뿐, 어떤 문제가 생기는지는 말하지 않기 때문에","correct":true},{"t":"많은 사람이 겪는다는 것만으로 멈추어야 할 까닭이 충분하기 때문에","mis":"K6-2-u3-X18"}],"mis":"K6-2-u3-X18","explanation":["이유 2는 문제의 규모를 보여 줘요.","왜 멈추어야 하는지 밝히려면 생기는 문제를 말해야 해요.","그래서 보통이다(△)로 판단할 수 있어요."],"asset":{"type":"passage","lines":["이유 1 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","이유 2 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 △","이유 3 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","근거 1 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 2 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 3 — 이유와 관련 △ · 객관적인 사실이나 정보 ◎"],"numbered":false,"title":"이유와 근거의 타당성 판단 — 『국어』 139~140쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#15','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C22',2,'ox','auto','「비규격 농산물을 소비하자」의 주장은 소비자들이 실천할 수 있는 수준이에요.',ARRAY['K6-2-u3-X05']::text[],false,'{"seq":15,"concept":"K6-2-u3-C22","difficulty":2,"kind":"ox","stem":"「비규격 농산물을 소비하자」의 주장은 소비자들이 실천할 수 있는 수준이에요.","answer":"O","reason_options":[{"t":"비규격 농산물을 골라 사는 것은 누구나 장을 볼 때 할 수 있는 일이기 때문에","correct":true},{"t":"농산물을 직접 길러야만 실천할 수 있는 주장이기 때문에","mis":"K6-2-u3-X05"}],"mis":"K6-2-u3-X05","explanation":["주장이 가치 있고 중요한지 판단할 때 실천 가능성을 살펴요.","비규격 농산물을 사는 것은 생활에서 바로 할 수 있어요.","그래서 가치 있고 실천할 수 있는 주장이에요."],"asset":{"type":"passage","lines":["비규격 농산물은 맛이나 영양은 차이가 없지만 크기가 작거나","상처가 나서 제값을 받지 못하는 농산물입니다.","이유 ① 농산물을 저렴하게 구입할 수 있습니다.","근거 ① 한국소비자원 2021년 조사 — 구매한 까닭의 46.5퍼센트가 저렴해서","이유 ② 자연환경을 보호할 수 있습니다.","근거 ② 농림축산식품부 2023년 조사 — 버려지는 농산물이 환경에 악영향","이유 ③ 모양이 예쁜 농산물을 만들 수 있습니다.","근거 ③ 많이 소비하면 예쁜 농산물이 잘 자랄 환경이 만들어진다고 함"],"numbered":false,"title":"카드 뉴스 「비규격 농산물을 소비하자」 간추림 — 『국어』 145쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#16','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C13',2,'ox','auto','관심 있는 주제의 영상을 찾을 때에는 같은 주제를 다룬 다양한 관점의 영상을 찾아보는 것이 좋아요.',ARRAY['K6-2-u3-X22']::text[],false,'{"seq":16,"concept":"K6-2-u3-C13","difficulty":2,"kind":"ox","stem":"관심 있는 주제의 영상을 찾을 때에는 같은 주제를 다룬 다양한 관점의 영상을 찾아보는 것이 좋아요.","answer":"O","reason_options":[{"t":"여러 관점의 영상을 견주어야 어느 영상의 내용이 더 타당한지 판단할 수 있기 때문에","correct":true},{"t":"가장 먼저 나온 영상 하나만 보면 충분하기 때문에","mis":"K6-2-u3-X22"}],"mis":"K6-2-u3-X22","explanation":["관심 있는 주제를 정한 친구들끼리 모여 영상을 찾아요.","다양한 관점의 영상을 찾아야 견주어 볼 수 있어요.","평가표로 견준 뒤 가장 타당한 영상을 골라요."],"asset":{"type":"passage","lines":["① 평소에 관심 있는 주제 말해 보기(예: 환경 · 건축 · 우주)","② 관심 있는 주제를 정한 친구들끼리 모여 그 주제를 표현한 영상 찾아보기","③ 평가표를 만들어 살펴본 영상들의 내용 타당성 평가하기","④ 가장 타당하다고 생각한 영상을 골라 주장, 이유, 근거를 친구들에게 설명하기"],"numbered":false,"title":"이런 활동도 있어요 — 관심 있는 주제의 영상을 보고 설명하기(『국어』 142쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#17','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C1',3,'match','auto','「일회용품은 이제 그만」의 내용을 주장, 이유, 근거로 알맞게 이으세요.','{}'::text[],false,'{"seq":17,"concept":"K6-2-u3-C1","difficulty":3,"kind":"match","stem":"「일회용품은 이제 그만」의 내용을 주장, 이유, 근거로 알맞게 이으세요.","pairs":[{"l":"환경을 위해 일회용품 사용을 줄입시다.","r":"주장"},{"l":"일회용품을 만들려면 많은 자원이 필요합니다.","r":"이유"},{"l":"나무젓가락과 종이컵을 만들려면 숲의 나무를 베어야 합니다.","r":"근거"}],"mis":"K6-2-u3-X01","explanation":["하자는 말이 주장이에요.","왜 줄여야 하는지 밝힌 말이 이유예요.","나무를 베어야 한다는 사실이 이유를 뒷받침하는 근거예요."],"asset":{"type":"passage","lines":["(간추림) 종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다.","(간추림) 우리가 편리하게 쓰던 일회용품이 지구를 병들게 하고 있다.","환경을 위해 일회용품 사용을 줄입시다.","(간추림) 일회용품을 만들려면 많은 자원이 필요하다.","(간추림) 나무젓가락과 종이컵을 만들려면 숲의 나무를 베어야 한다.","(간추림) 일회용품은 오랫동안 썩지 않아 환경을 오염시킨다.","(간추림) 땅속에서 썩는 데 종이컵은 20년, 스티로폼 도시락은","(간추림) 500년이 걸린다고 한다."],"numbered":false,"title":"「일회용품은 이제 그만」 — 듣기 자료 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#18','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C6',3,'ox','auto','「종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다」는 일회용품을 만들려면 많은 자원이 필요하다는 이유와 관련 있는 근거예요.',ARRAY['K6-2-u3-X25']::text[],false,'{"seq":18,"concept":"K6-2-u3-C6","difficulty":3,"kind":"ox","stem":"「종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다」는 일회용품을 만들려면 많은 자원이 필요하다는 이유와 관련 있는 근거예요.","answer":"O","reason_options":[{"t":"종이컵을 만드는 데 나무가 많이 든다는 것을 숫자로 보여 주기 때문에","correct":true},{"t":"나무라는 낱말만 들어가면 어떤 이유든 뒷받침하기 때문에","mis":"K6-2-u3-X25"}],"mis":"K6-2-u3-X25","explanation":["이유는 일회용품을 만들려면 많은 자원이 필요하다는 것이에요.","종이컵을 만드는 데 나무가 많이 든다는 정보는 그 이유를 보여 줘요.","근거는 이유와 관련 있는지부터 살펴요."],"asset":{"type":"passage","lines":["(간추림) 종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다.","(간추림) 우리가 편리하게 쓰던 일회용품이 지구를 병들게 하고 있다.","환경을 위해 일회용품 사용을 줄입시다.","(간추림) 일회용품을 만들려면 많은 자원이 필요하다.","(간추림) 나무젓가락과 종이컵을 만들려면 숲의 나무를 베어야 한다.","(간추림) 일회용품은 오랫동안 썩지 않아 환경을 오염시킨다.","(간추림) 땅속에서 썩는 데 종이컵은 20년, 스티로폼 도시락은","(간추림) 500년이 걸린다고 한다."],"numbered":false,"title":"「일회용품은 이제 그만」 — 듣기 자료 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#19','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C13',3,'ox','auto','영상 평가 댓글에는 영상 내용이 좋은지 싫은지만 써도 조건에 맞아요.',ARRAY['K6-2-u3-X27']::text[],false,'{"seq":19,"concept":"K6-2-u3-C13","difficulty":3,"kind":"ox","stem":"영상 평가 댓글에는 영상 내용이 좋은지 싫은지만 써도 조건에 맞아요.","answer":"X","reason_options":[{"t":"영상의 주장, 이유, 근거가 타당한지 까닭과 함께 써야 하기 때문에","correct":true},{"t":"댓글은 짧을수록 좋으니 좋고 싫음만 쓰면 되기 때문에","mis":"K6-2-u3-X27"}],"mis":"K6-2-u3-X27","explanation":["단순히 좋고 싫음만 쓰는 것은 평가가 아니에요.","주장을 파악하고 타당한지 까닭과 함께 써요.","타당하지 않은 부분은 정중하게 확인을 요청해요."],"asset":{"type":"passage","lines":["• 자신이 파악한 영상의 주장이 무엇인지 쓰기","• 주장이 타당한지 쓰기","• 이유와 근거가 타당한지 까닭과 함께 쓰기","• 타당하지 않은 부분에 대해 정중하게 확인 요청하기"],"numbered":false,"title":"영상에 평가 댓글을 쓸 때의 조건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#20','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C10',3,'ox','auto','굵은 글자나 되풀이되는 자막으로 강조한 말은 그것만으로 타당한 말이라고 할 수 있어요.',ARRAY['K6-2-u3-X17']::text[],false,'{"seq":20,"concept":"K6-2-u3-C10","difficulty":3,"kind":"ox","stem":"굵은 글자나 되풀이되는 자막으로 강조한 말은 그것만으로 타당한 말이라고 할 수 있어요.","answer":"X","reason_options":[{"t":"강조는 무엇을 말하고 싶은지 알려 줄 뿐, 그 말이 타당한지는 이유와 근거로 따져야 하기 때문에","correct":true},{"t":"강조된 말은 언제나 근거로 뒷받침되어 있기 때문에","mis":"K6-2-u3-X17"}],"mis":"K6-2-u3-X17","explanation":["강조는 주장을 찾는 실마리예요.","주장을 찾는 일과 타당한지 따지는 일은 달라요.","타당성은 주장, 이유, 근거의 기준으로 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#21','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C8',3,'ox','auto','근거가 약할 때에는 같은 말을 더 크게 되풀이하면 근거가 튼튼해져요.',ARRAY['K6-2-u3-X14']::text[],false,'{"seq":21,"concept":"K6-2-u3-C8","difficulty":3,"kind":"ox","stem":"근거가 약할 때에는 같은 말을 더 크게 되풀이하면 근거가 튼튼해져요.","answer":"X","reason_options":[{"t":"근거는 느낌을 키우는 것이 아니라 확인할 수 있는 객관적인 자료로 바꾸어야 튼튼해지기 때문에","correct":true},{"t":"크게 말할수록 듣는 사람이 더 잘 믿기 때문에","mis":"K6-2-u3-X14"}],"mis":"K6-2-u3-X14","explanation":["되풀이하거나 감정에 호소한다고 근거가 튼튼해지지 않아요.","확인할 수 있는 객관적인 자료로 바꾸어요.","출처도 정확히 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#22','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C19',3,'ox','auto','「나를 성장시키는 기록법」은 주장을 직접 말하지 않아도 여러 인물의 기록 장면으로 주장을 짐작할 수 있게 만든 영상이에요.',ARRAY['K6-2-u3-X16']::text[],false,'{"seq":22,"concept":"K6-2-u3-C19","difficulty":3,"kind":"ox","stem":"「나를 성장시키는 기록법」은 주장을 직접 말하지 않아도 여러 인물의 기록 장면으로 주장을 짐작할 수 있게 만든 영상이에요.","answer":"O","reason_options":[{"t":"정약용, 이순신, 천재들의 기록 습관을 차례로 보여 주며 생각을 기록하는 습관을 강조하기 때문에","correct":true},{"t":"영상 첫 장면에서 주장을 문장으로 그대로 읽어 주기 때문에","mis":"K6-2-u3-X16"}],"mis":"K6-2-u3-X16","explanation":["영상은 자료를 바탕으로 보는 사람이 주장을 추론하게 해요.","여러 인물의 기록 장면이 같은 주장을 가리켜요.","되풀이되는 「생각, 기록, 습관」도 실마리예요."],"asset":{"type":"passage","lines":["1 제목 — 나를 성장시키는 기록법","2 열심히 받아 적었는데도 뒤돌아서면 기억하지 못한다.","3 정약용이 활용한 수사차록법","4 이순신의 「난중일기」 — 업무를 정리하고 작전을 세우며 생각을 정리한 기록","5 천재로 불렸던 인물들의 공통점 — 떠오르는 생각을 종이에 기록하는 능력","6 「적자! 생존」 — 잘 적는 사람이 살아남는 현상?"],"numbered":false,"title":"영상 「나를 성장시키는 기록법」의 장면 — 『국어』 131쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#23','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C7',4,'essay','teacher','「일회용품은 이제 그만」을 평가하며 타당한 점과 보완할 점을 하나씩 쓰세요. 보완할 점에는 고칠 방법도 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u3-C7","difficulty":4,"kind":"essay","stem":"「일회용품은 이제 그만」을 평가하며 타당한 점과 보완할 점을 하나씩 쓰세요. 보완할 점에는 고칠 방법도 함께 쓰세요.","answer_guide":{"answer":"예: 타당한 점 — 일회용품이 썩는 데 걸리는 햇수처럼 이유와 관련 있는 구체적인 정보를 근거로 들어 이유를 잘 뒷받침했다. 보완할 점 — 근거로 든 숫자가 어디에서 나왔는지 밝히지 않았다. 숫자를 조사한 기관이나 자료의 이름을 함께 말하면 듣는 사람이 확인할 수 있어 더 믿을 만해질 것이다.","scoring_points":["타당한 점을 먼저 썼는가","보완할 점을 근거의 기준과 이어 썼는가","고칠 방법을 구체적으로 썼는가"]},"explanation":["살릴 점을 먼저 찾아요.","보완할 점은 기준에 비추어 찾아요.","고칠 방법을 함께 말해야 도움이 돼요."],"asset":{"type":"passage","lines":["(간추림) 종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다.","(간추림) 우리가 편리하게 쓰던 일회용품이 지구를 병들게 하고 있다.","환경을 위해 일회용품 사용을 줄입시다.","(간추림) 일회용품을 만들려면 많은 자원이 필요하다.","(간추림) 나무젓가락과 종이컵을 만들려면 숲의 나무를 베어야 한다.","(간추림) 일회용품은 오랫동안 썩지 않아 환경을 오염시킨다.","(간추림) 땅속에서 썩는 데 종이컵은 20년, 스티로폼 도시락은","(간추림) 500년이 걸린다고 한다."],"numbered":false,"title":"「일회용품은 이제 그만」 — 듣기 자료 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#24','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C13',4,'essay','teacher','친구가 영상에 「이 영상 완전 별로예요. 만든 사람은 아무것도 모르네요.」라는 댓글을 썼어요. 이 댓글이 댓글 조건 네 가지에 맞지 않는 점을 쓰고, 조건에 맞게 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u3-C13","difficulty":4,"kind":"essay","stem":"친구가 영상에 「이 영상 완전 별로예요. 만든 사람은 아무것도 모르네요.」라는 댓글을 썼어요. 이 댓글이 댓글 조건 네 가지에 맞지 않는 점을 쓰고, 조건에 맞게 고쳐 쓰세요.","answer_guide":{"answer":"예: 이 댓글은 영상의 주장이 무엇인지, 주장과 이유, 근거가 타당한지를 쓰지 않았고, 좋고 싫음만 말하며 만든 사람을 깎아내렸다. 고쳐 쓴 댓글 — 이 영상은 일회용 컵을 줄이자고 주장하는 것 같아요. 실천할 수 있는 가치 있는 주장이에요. 다만 이유를 뒷받침하는 자료가 잘 보이지 않는데, 어떤 자료가 있는지 알려 주실 수 있을까요?","scoring_points":["조건에 맞지 않는 점(주장·판단·까닭 빠짐, 비방)을 썼는가","고친 댓글에 주장과 판단을 넣었는가","정중한 확인 요청으로 고쳤는가"]},"explanation":["좋고 싫음만 쓰는 것은 평가가 아니에요.","만든 사람을 깎아내리는 말은 쓰지 않아요.","조건 넷을 지켜 정중하게 고쳐 써요."],"asset":{"type":"passage","lines":["• 자신이 파악한 영상의 주장이 무엇인지 쓰기","• 주장이 타당한지 쓰기","• 이유와 근거가 타당한지 까닭과 함께 쓰기","• 타당하지 않은 부분에 대해 정중하게 확인 요청하기"],"numbered":false,"title":"영상에 평가 댓글을 쓸 때의 조건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_c#25','kor',6,2,'u3','','tb_g6_2_kor_u3_review_c','unit_review','K6-2-u3-C11',4,'essay','teacher','주장하는 말을 듣고 평가하는 방법과 카드 뉴스를 보고 평가하는 방법이 어떻게 같고 다른지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u3-C11","difficulty":4,"kind":"essay","stem":"주장하는 말을 듣고 평가하는 방법과 카드 뉴스를 보고 평가하는 방법이 어떻게 같고 다른지 쓰세요.","answer_guide":{"answer":"예: 같은 점 — 둘 다 주장이 가치 있고 중요한지, 이유가 주장을 적절하게 뒷받침하는지, 근거가 이유를 적절하게 뒷받침하는지라는 같은 기준으로 평가한다. 다른 점 — 주장하는 말은 다시 듣기 어려워 메모하며 들어야 하고, 카드 뉴스는 이미지와 짧은 글로 되어 있어 제목과 강조한 내용에서 주장을 찾고 짧은 글에 빠진 것이 없는지 살펴야 한다.","scoring_points":["같은 평가 기준을 쓴다는 점을 썼는가","주장하는 말의 특성(메모하며 듣기)을 썼는가","카드 뉴스의 특성(제목·강조·짧은 글)을 썼는가"]},"explanation":["평가 기준은 6학년 1학기에 배운 것과 같아요.","말은 메모하며 들어요.","카드 뉴스는 제목과 강조에서 주장을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#1','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C1',1,'mc','auto','「복도에서 뛰지 말자.」라는 주장의 이유로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X26','K6-2-u3-X06']::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":1,"kind":"mc","stem":"「복도에서 뛰지 말자.」라는 주장의 이유로 알맞은 것은 무엇인가요?","options":[{"t":"뛰어다니면 다른 사람과 부딪쳐 사고가 날 수 있기 때문","correct":true},{"t":"복도에서는 천천히 걸어 다니자","mis":"K6-2-u3-X01"},{"t":"학생회 회의에서 정해진 말이라 따라야 하기 때문","mis":"K6-2-u3-X26"},{"t":"복도는 넓고 길어서 뛰기에 알맞기 때문","mis":"K6-2-u3-X06"}],"explanation":["『국어』 122쪽 경험 떠올리기의 예시예요.","학생회 회의에서 복도에서 뛰지 말자는 주장을 들었어요.","부딪쳐 사고가 날 수 있다는 것이 그 이유였어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"뉴스에서 일회용품을 줄이자는 내용을 봤는데 우리가 버린 일회용품 때문에 고통받는 바다 생물이 있다는 이유가 제시되었어."},{"who":"친구 2","text":"성장기에는 아침을 꼭 먹어야 한다는 영상을 봤는데 이유는 없고 주장만 있었어."},{"who":"친구 3","text":"학생회 회의에서 복도에서 뛰지 말자는 주장을 들었어. 복도에서 뛰어다니면 다른 사람과 부딪쳐 사고가 날 수 있다는 이유를 제시했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#2','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C2',1,'mc','auto','『국어』 115쪽 생각 열기에서 주장하는 내용을 담은 매체를 접한 경험으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":2,"concept":"K6-2-u3-C2","difficulty":1,"kind":"mc","stem":"『국어』 115쪽 생각 열기에서 주장하는 내용을 담은 매체를 접한 경험으로 알맞은 것은 무엇인가요?","options":[{"t":"선거에 나온 후보자의 주장하는 말을 들은 적이 있다","correct":true},{"t":"친구와 함께 줄넘기를 한 적이 있다","mis":"K6-2-u3-X15"},{"t":"아무 주장도 없는 날씨 정보만 본 적이 있다","mis":"K6-2-u3-X15"},{"t":"혼자 그림을 그린 적이 있다","mis":"K6-2-u3-X15"}],"explanation":["주장하는 내용을 담은 매체에는 연설, 영상, 카드 뉴스 등이 있어요.","선거 후보자의 말이나 운동을 꾸준히 하자는 영상이 그 예예요.","주장이 담긴 매체는 비판적으로 파악해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#3','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C15',1,'mc','auto','「실수에서 배워요」에서 이유를 뒷받침하려고 든 근거는 무엇인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":3,"concept":"K6-2-u3-C15","difficulty":1,"kind":"mc","stem":"「실수에서 배워요」에서 이유를 뒷받침하려고 든 근거는 무엇인가요?","options":[{"t":"실수를 자세히 탐구해 페니실린을 발견한 플레밍의 일화","correct":true},{"t":"실수를 배움의 기회로 삼을 수 있다는 말","mis":"K6-2-u3-X01"},{"t":"실수는 조심하지 않아서 잘못하는 행동이라는 뜻풀이","mis":"K6-2-u3-X01"},{"t":"친구와 부딪치는 실수가 속상하다는 말","mis":"K6-2-u3-X01"}],"explanation":["주장은 실수를 배움의 기회로 삼을 수 있다는 것이에요.","이유는 실수에서 고칠 점을 발견할 수 있다는 것이에요.","그 이유를 보여 주는 플레밍의 일화가 근거예요."],"asset":{"type":"passage","lines":["주장 실수를 배움의 기회로 삼을 수 있다.","이유 실수에서 문제점을 찾으려 노력하면 고칠 점을 발견할 수 있기 때문이다.","근거 실수를 그냥 지나치지 않고 자세히 탐구한 플레밍처럼","      실수를 다시 생각해 보고 반성하면 더 좋은 해결 방법을","      찾을 수 있기 때문이다."],"numbered":false,"title":"「실수에서 배워요」의 주장 · 이유 · 근거 — 『국어』 119쪽 3번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#4','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C16',1,'mc','auto','윤정이가 주장하는 말에서 이유에 해당하는 것은 무엇인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X04']::text[],false,'{"seq":4,"concept":"K6-2-u3-C16","difficulty":1,"kind":"mc","stem":"윤정이가 주장하는 말에서 이유에 해당하는 것은 무엇인가요?","options":[{"t":"육류를 생산하고 소비하는 과정이 지구 온난화를 가속하는 원인이 되기 때문","correct":true},{"t":"급식에서 채소 위주의 음식을 제공하는 날을 늘리자","mis":"K6-2-u3-X01"},{"t":"소나무 열다섯 그루를 심는 효과가 있다는 기사","mis":"K6-2-u3-X01"},{"t":"질 좋은 고기반찬으로만 단백질을 섭취할 수 있기 때문","mis":"K6-2-u3-X04"}],"explanation":["「채소 위주 음식 날을 늘리자」는 주장이에요.","왜 그런지 밝힌 「지구 온난화를 가속하는 원인」이 이유예요.","기사 내용은 근거예요."],"asset":{"type":"passage","lines":["주장 급식에서 채소 위주의 음식을 제공하는 날을 늘리자.","이유 육류를 생산하고 소비하는 과정이 지구 온난화를 가속하는 원인이 되기 때문이다.","근거 일주일에 한 번 채식을 했을 때 일 년에 소나무 열다섯 그루를","      심는 효과가 있다는 기사가 있다."],"numbered":false,"title":"「용기초등학교 어린이 생각 발표회」 윤정이의 말 정리 — 『국어』 124쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#5','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C21',1,'mc','auto','「규칙이나 규정에 의하여 일정한 한도를 정하거나 정한 한도를 넘지 못하게 막음.」이라는 뜻을 가진 낱말은 무엇인가요?',ARRAY['K6-2-u3-X29']::text[],false,'{"seq":5,"concept":"K6-2-u3-C21","difficulty":1,"kind":"mc","stem":"「규칙이나 규정에 의하여 일정한 한도를 정하거나 정한 한도를 넘지 못하게 막음.」이라는 뜻을 가진 낱말은 무엇인가요?","options":[{"t":"규제","correct":true},{"t":"조장","mis":"K6-2-u3-X29"},{"t":"침해","mis":"K6-2-u3-X29"},{"t":"강화","mis":"K6-2-u3-X29"}],"explanation":["다섯째 장에서 독일은 혐오 표현을 형법으로 규제한다고 했어요.","정한 한도를 넘지 못하게 막는 것이 규제예요.","「큰 소리를 내는 것을 규제한다」처럼 써요."],"asset":{"type":"passage","lines":["● 강화: 세력이나 힘을 더 강하고 튼튼하게 함.","● 규제: 규칙이나 규정에 의하여 일정한 한도를 정하거나","  정한 한도를 넘지 못하게 막음.","● 조장: 바람직하지 않은 일을 더 심해지도록 부추김.","● 침해: 침범하여 해를 끼침."],"numbered":false,"title":"카드 뉴스 낱말 알기 보기 — 『국어』 138쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#6','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C9',1,'mc','auto','영상의 주장을 파악하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u3-X15','K6-2-u3-X03']::text[],false,'{"seq":6,"concept":"K6-2-u3-C9","difficulty":1,"kind":"mc","stem":"영상의 주장을 파악하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"영상의 제목을 정한 까닭을 생각해 본다","correct":true},{"t":"영상이 몇 분 몇 초인지 길이를 재어 본다","mis":"K6-2-u3-X15"},{"t":"영상에 나온 사람이 몇 명인지 세어 본다","mis":"K6-2-u3-X15"},{"t":"영상의 조회 수가 얼마인지 살펴본다","mis":"K6-2-u3-X03"}],"explanation":["영상의 제목에는 만든 사람의 관점이 드러나요.","제목을 정한 까닭을 생각하면 주장에 다가갈 수 있어요.","길이나 사람 수, 조회 수는 주장과 관계없어요."],"asset":{"type":"passage","lines":["● 영상의 제목을 살펴보고 그렇게 정한 까닭을 생각해 본다.","● 영상에서 제시한 자료의 내용을 파악한다.","● 영상에서 강조하는 장면이나 표현이 무엇인지 찾고","  그렇게 표현한 까닭을 생각해 본다."],"numbered":false,"title":"영상의 주장을 파악하는 방법 — 『국어』 133쪽 6번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#7','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C20',1,'mc','auto','카드 뉴스의 마지막 장에서 혐오·차별 표현을 멈추는 것을 무엇이라고 했나요?',ARRAY['K6-2-u3-X19','K6-2-u3-X15','K6-2-u3-X29']::text[],false,'{"seq":7,"concept":"K6-2-u3-C20","difficulty":1,"kind":"mc","stem":"카드 뉴스의 마지막 장에서 혐오·차별 표현을 멈추는 것을 무엇이라고 했나요?","options":[{"t":"서로를 존중하는 사회로 나아가는 첫걸음","correct":true},{"t":"다른 나라의 법을 그대로 따르는 일","mis":"K6-2-u3-X19"},{"t":"혐오 표현 경험을 그래프로 그리는 일","mis":"K6-2-u3-X15"},{"t":"특정 집단에 대한 편견을 강화하는 일","mis":"K6-2-u3-X29"}],"explanation":["여섯째 장은 카드 뉴스를 마무리하는 장이에요.","무심코 쓰는 표현이 누군가를 부정적으로 보게 만들 수 있다고 했어요.","그것을 멈추는 것이 서로를 존중하는 사회로 나아가는 첫걸음이라고 했어요."],"asset":{"type":"passage","lines":["셋째 장 [왜 멈추어야 할까요?] 특정 집단에 대한 부정적 인식을 강화할 수 있기 때문","      [사례] ‘살색’ → ‘살구색’(피부색에 대한 편견과 차별이 생길 수 있어 바꿈)","넷째 장 [왜 멈추어야 할까요?] 많은 사람이 겪고 있기 때문","      [그래프] 국가인권위원회 조사 — 참여자의 70.3퍼센트가 경험함","다섯째 장 [왜 멈추어야 할까요?] 인간의 존엄성을 침해하고 사회적 갈등을 초래하기 때문","      [사례] 독일은 형법으로, 캐나다는 인권법으로 규제 · 우리나라도 제도 마련","여섯째 장 혐오·차별 표현을 멈추는 것이 서로를 존중하는 사회로 나아가는 첫걸음"],"numbered":false,"title":"같은 카드 뉴스 셋째~여섯째 장 간추림 — 『국어』 135~136쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#8','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C14',1,'mc','auto','받침 ㅎ 뒤에 ㄱ이 오면 어떻게 발음하나요?',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":8,"concept":"K6-2-u3-C14","difficulty":1,"kind":"mc","stem":"받침 ㅎ 뒤에 ㄱ이 오면 어떻게 발음하나요?","options":[{"t":"합쳐서 [ㅋ]으로 발음한다","correct":true},{"t":"[ㄷ]으로 끊어 발음한다","mis":"K6-2-u3-X23"},{"t":"ㅎ 소리를 그대로 낸다","mis":"K6-2-u3-X23"},{"t":"[ㄴ]으로 발음한다","mis":"K6-2-u3-X23"}],"explanation":["받침 ㅎ 뒤에 ㄱ이 오면 둘이 합쳐져요.","그래서 [ㅋ]으로 소리 나요.","「어떻게」가 [어떠케]로 소리 나는 까닭이에요."],"asset":{"type":"passage","lines":["1 놓다[노타] · 닿다[다ː타] · 쌓다[싸타]","2 받침 ㅎ 뒤에 ㄱ이 오면 [ㅋ], ㄷ이 오면 [ㅌ], ㅈ이 오면 [ㅊ]으로 합쳐 발음해요.","3 놓는[논는] · 쌓는[싼는]","4 받침 ㅎ 뒤에 ㄴ이 오면 ㅎ은 [ㄴ]으로 발음해요."],"numbered":false,"title":"기초 다지기 — 받침 ‘ㅎ’이 들어간 낱말 발음(『국어』 147쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#9','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C5',2,'match','auto','『국어』 144쪽 1번의 기준을 알맞게 분류하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C5","difficulty":2,"kind":"match","stem":"『국어』 144쪽 1번의 기준을 알맞게 분류하세요.","pairs":[{"l":"㉮ 주장은 가치 있고 중요한가?","r":"주장의 타당성 판단하기"},{"l":"㉳ 근거는 이유를 적절하게 뒷받침하는가?","r":"이유와 근거의 타당성 판단하기"},{"l":"㉯ 주장의 길이가 적당한가?","r":"타당성 기준이 아님"}],"mis":"K6-2-u3-X28","explanation":["㉮는 주장의 타당성을 판단해요.","㉰와 ㉳는 이유와 근거의 타당성을 판단해요.","㉯, ㉱, ㉲는 타당성 기준이 아니에요."],"asset":{"type":"passage","lines":["㉮ 주장은 가치 있고 중요한가?","㉯ 주장의 길이가 적당한가?","㉰ 이유는 주장을 적절하게 뒷받침하는가?","㉱ 듣는 사람을 기분 좋게 만드는 이유인가?","㉲ 근거의 종류는 다양한가?","㉳ 근거는 이유를 적절하게 뒷받침하는가?"],"numbered":false,"title":"마무리 1번 — 주장하는 말의 내용을 평가하며 들을 때 필요한 기준 찾기(『국어』 144쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#10','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C3',2,'error','auto','「용기초등학교 어린이 생각 발표회」를 들으며 친구들이 한 말이에요. 듣는 방법이 알맞지 않은 친구는 누구인가요?',ARRAY['K6-2-u3-X04','K6-2-u3-X26']::text[],false,'{"seq":10,"concept":"K6-2-u3-C3","difficulty":2,"kind":"error","stem":"「용기초등학교 어린이 생각 발표회」를 들으며 친구들이 한 말이에요. 듣는 방법이 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 3 — 「고기반찬이 좋으니 현우 말이 맞다고 미리 정하고 들을래.」","correct":true,"mis_target":"K6-2-u3-X04"},{"t":"친구 1 — 「주장, 이유, 근거를 메모하며 들을래.」","mis":"K6-2-u3-X26"},{"t":"친구 2 — 「두 친구의 주장을 내 생각과 견주며 들을래.」","mis":"K6-2-u3-X26"}],"explanation":["주장, 이유, 근거를 메모하며 들어요.","내 생각과 견주며 들어요.","결론을 미리 정하면 내용을 제대로 평가할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#11','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C6',2,'match','auto','근거 자료와 그 유형을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"K6-2-u3-C6","difficulty":2,"kind":"match","stem":"근거 자료와 그 유형을 알맞게 이으세요.","pairs":[{"l":"플레밍이 실수를 탐구해 페니실린을 발견한 일","r":"사례"},{"l":"혐오·차별 표현 경험 여부를 막대로 나타낸 자료","r":"그래프"},{"l":"어떤 사람을 만나 묻고 답한 내용을 옮긴 자료","r":"면담 자료"}],"mis":"K6-2-u3-X10","explanation":["실제로 있었던 일을 들면 사례예요.","조사 결과를 막대로 나타내면 그래프예요.","사람에게 묻고 답한 내용을 옮기면 면담 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#12','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C5',2,'error','auto','「오류를 찾아라」 놀이에서 두 친구가 ㉯ 「학생들은 교복을 입어야 한다. 교복을 입으면 싸울 일이 줄어들기 때문이다.」를 두고 말했어요. 놀이 방법에 맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X06','K6-2-u3-X24']::text[],false,'{"seq":12,"concept":"K6-2-u3-C5","difficulty":2,"kind":"error","stem":"「오류를 찾아라」 놀이에서 두 친구가 ㉯ 「학생들은 교복을 입어야 한다. 교복을 입으면 싸울 일이 줄어들기 때문이다.」를 두고 말했어요. 놀이 방법에 맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「이 문장은 교복이 나오니까 이유를 따질 필요가 없어.」","correct":true,"mis_target":"K6-2-u3-X06"},{"t":"친구 1 — 「교복과 싸울 일이 줄어드는 것이 어떻게 이어지는지 알 수 없어.」","mis":"K6-2-u3-X24"},{"t":"친구 2 — 「옷차림에 신경을 덜 쓰게 된다처럼 이어지는 이유로 바꾸어 볼래.」","mis":"K6-2-u3-X24"}],"explanation":["놀이에서는 이유에 무엇이 잘못되었는지 말해요.","그리고 오류가 있는 이유 대신 어떤 이유를 들지 말해요.","친구 3은 이유를 따져 보지 않았어요."],"asset":{"type":"passage","lines":["㉮ 모든 사람은 아침에 운동을 해야 한다.","   나는 아침 운동을 하면 기분이 좋기 때문이다.","㉯ 학생들은 교복을 입어야 한다.","   교복을 입으면 싸울 일이 줄어들기 때문이다.","㉰ 플라스틱 사용을 줄여야 한다.","   거북이 비닐 때문에 고통받는 걸 보니 너무 슬펐기 때문이다."],"numbered":false,"title":"「오류를 찾아라」 놀이 — 이유에 오류가 있는 문장의 예"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#13','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C9',2,'blank','auto','『국어』 133쪽 6번의 정리예요. 「영상에서 강조하는 장면이나 (    )이/가 무엇인지 찾고 그렇게 표현한 까닭을 생각해 본다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u3-X15','K6-2-u3-X03']::text[],false,'{"seq":13,"concept":"K6-2-u3-C9","difficulty":2,"kind":"blank","stem":"『국어』 133쪽 6번의 정리예요. 「영상에서 강조하는 장면이나 (    )이/가 무엇인지 찾고 그렇게 표현한 까닭을 생각해 본다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"표현","correct":true},{"t":"길이","mis":"K6-2-u3-X15"},{"t":"조회 수","mis":"K6-2-u3-X03"},{"t":"광고","mis":"K6-2-u3-X15"}],"explanation":["영상은 음악이나 자막으로 장면과 표현을 강조해요.","강조된 장면이나 표현을 찾아요.","그렇게 표현한 까닭을 생각하면 주장이 보여요."],"asset":{"type":"passage","lines":["● 영상의 제목을 살펴보고 그렇게 정한 까닭을 생각해 본다.","● 영상에서 제시한 자료의 내용을 파악한다.","● 영상에서 강조하는 장면이나 표현이 무엇인지 찾고","  그렇게 표현한 까닭을 생각해 본다."],"numbered":false,"title":"영상의 주장을 파악하는 방법 — 『국어』 133쪽 6번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#14','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C12',2,'sa','auto','『국어』 139~140쪽 예시에서 「많은 사람이 받아들일 만한 타당한 이유인가요?」에 보통이다(△)를 받은 이유는 이유 몇인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"K6-2-u3-C12","difficulty":2,"kind":"sa","stem":"『국어』 139~140쪽 예시에서 「많은 사람이 받아들일 만한 타당한 이유인가요?」에 보통이다(△)를 받은 이유는 이유 몇인가요? 숫자로 쓰세요.","answer":["2","이유 2","둘"],"explanation":["이유 1과 이유 3은 두 기준 모두 ◎예요.","이유 2는 문제의 규모만 보여 줘 △를 받았어요.","근거 가운데에서는 근거 3이 △를 받았어요."],"asset":{"type":"passage","lines":["이유 1 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","이유 2 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 △","이유 3 — 주장과 관련 ◎ · 많은 사람이 받아들일 만함 ◎","근거 1 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 2 — 이유와 관련 ◎ · 객관적인 사실이나 정보 ◎","근거 3 — 이유와 관련 △ · 객관적인 사실이나 정보 ◎"],"numbered":false,"title":"이유와 근거의 타당성 판단 — 『국어』 139~140쪽 예시"},"mis":"K6-2-u3-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#15','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C22',2,'sa','auto','「비규격 농산물을 소비하자」에서 주장과 관련 없는 이야기라서 타당하지 않은 이유는 이유 몇인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"K6-2-u3-C22","difficulty":2,"kind":"sa","stem":"「비규격 농산물을 소비하자」에서 주장과 관련 없는 이야기라서 타당하지 않은 이유는 이유 몇인가요? 숫자로 쓰세요.","answer":["3","이유 3","셋"],"explanation":["이유 ①은 저렴한 가격, 이유 ②는 환경 보호예요.","이유 ③은 모양이 예쁜 농산물을 만든다는 것이에요.","이유 ③은 비규격 농산물을 소비하자는 주장과 관련이 없어요."],"asset":{"type":"passage","lines":["비규격 농산물은 맛이나 영양은 차이가 없지만 크기가 작거나","상처가 나서 제값을 받지 못하는 농산물입니다.","이유 ① 농산물을 저렴하게 구입할 수 있습니다.","근거 ① 한국소비자원 2021년 조사 — 구매한 까닭의 46.5퍼센트가 저렴해서","이유 ② 자연환경을 보호할 수 있습니다.","근거 ② 농림축산식품부 2023년 조사 — 버려지는 농산물이 환경에 악영향","이유 ③ 모양이 예쁜 농산물을 만들 수 있습니다.","근거 ③ 많이 소비하면 예쁜 농산물이 잘 자랄 환경이 만들어진다고 함"],"numbered":false,"title":"카드 뉴스 「비규격 농산물을 소비하자」 간추림 — 『국어』 145쪽"},"mis":"K6-2-u3-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#16','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C13',2,'mc','auto','「관심 있는 주제의 영상을 보고 설명하기」에서 평가표로 영상을 평가한 다음에 할 일은 무엇인가요?',ARRAY['K6-2-u3-X22']::text[],false,'{"seq":16,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"「관심 있는 주제의 영상을 보고 설명하기」에서 평가표로 영상을 평가한 다음에 할 일은 무엇인가요?","options":[{"t":"가장 타당한 영상을 골라 주장, 이유, 근거를 설명하기","correct":true},{"t":"평소에 관심 있는 주제를 다시 말해 보기","mis":"K6-2-u3-X22"},{"t":"같은 주제를 정한 친구들끼리 모여 앉기","mis":"K6-2-u3-X22"},{"t":"누리 소통망에서 영상을 새로 검색하기","mis":"K6-2-u3-X22"}],"explanation":["주제 정하기 → 영상 찾기 → 평가표로 평가하기 차례로 해요.","평가한 뒤 가장 타당한 영상을 골라요.","그 영상의 주장, 이유, 근거를 친구들에게 설명해요."],"asset":{"type":"passage","lines":["① 평소에 관심 있는 주제 말해 보기(예: 환경 · 건축 · 우주)","② 관심 있는 주제를 정한 친구들끼리 모여 그 주제를 표현한 영상 찾아보기","③ 평가표를 만들어 살펴본 영상들의 내용 타당성 평가하기","④ 가장 타당하다고 생각한 영상을 골라 주장, 이유, 근거를 친구들에게 설명하기"],"numbered":false,"title":"이런 활동도 있어요 — 관심 있는 주제의 영상을 보고 설명하기(『국어』 142쪽)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#17','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C1',3,'error','auto','「일회용품은 이제 그만」을 듣고 친구들이 주장, 이유, 근거를 말했어요. 자리를 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":17,"concept":"K6-2-u3-C1","difficulty":3,"kind":"error","stem":"「일회용품은 이제 그만」을 듣고 친구들이 주장, 이유, 근거를 말했어요. 자리를 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「주장은 ‘일회용품은 오랫동안 썩지 않는다’야.」","correct":true,"mis_target":"K6-2-u3-X01"},{"t":"친구 1 — 「이유 하나는 ‘일회용품을 만들려면 많은 자원이 필요하다’야.」","mis":"K6-2-u3-X01"},{"t":"친구 2 — 「‘종이컵은 썩는 데 20년이 걸린다’는 근거야.」","mis":"K6-2-u3-X01"}],"explanation":["친구 1은 이유를 바르게 찾았어요.","친구 2는 근거를 바르게 찾았어요.","「오랫동안 썩지 않는다」는 주장이 아니라 이유예요."],"asset":{"type":"passage","lines":["(간추림) 종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다.","(간추림) 우리가 편리하게 쓰던 일회용품이 지구를 병들게 하고 있다.","환경을 위해 일회용품 사용을 줄입시다.","(간추림) 일회용품을 만들려면 많은 자원이 필요하다.","(간추림) 나무젓가락과 종이컵을 만들려면 숲의 나무를 베어야 한다.","(간추림) 일회용품은 오랫동안 썩지 않아 환경을 오염시킨다.","(간추림) 땅속에서 썩는 데 종이컵은 20년, 스티로폼 도시락은","(간추림) 500년이 걸린다고 한다."],"numbered":false,"title":"「일회용품은 이제 그만」 — 듣기 자료 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#18','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C7',3,'error','auto','「일회용품은 이제 그만」의 타당성을 판단하며 친구들이 말했어요. 판단하는 방법이 알맞지 않은 친구는 누구인가요?',ARRAY['K6-2-u3-X12','K6-2-u3-X04','K6-2-u3-X11']::text[],false,'{"seq":18,"concept":"K6-2-u3-C7","difficulty":3,"kind":"error","stem":"「일회용품은 이제 그만」의 타당성을 판단하며 친구들이 말했어요. 판단하는 방법이 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 3 — 「목소리가 힘차서 매우 타당하다고 표시할래.」","correct":true,"mis_target":"K6-2-u3-X12"},{"t":"친구 1 — 「이유가 주장과 관련 있고 많은 사람이 받아들일 만해서 ◎로 판단할래.」","mis":"K6-2-u3-X04"},{"t":"친구 2 — 「근거의 출처가 밝혀져 있지 않아 보완할 점으로 말할래.」","mis":"K6-2-u3-X11"}],"explanation":["판단은 기준에 따라 하고 까닭을 함께 말해요.","목소리나 말솜씨는 타당성의 기준이 아니에요.","보완할 점은 까닭과 함께 말해요."],"asset":{"type":"passage","lines":["(간추림) 종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다.","(간추림) 우리가 편리하게 쓰던 일회용품이 지구를 병들게 하고 있다.","환경을 위해 일회용품 사용을 줄입시다.","(간추림) 일회용품을 만들려면 많은 자원이 필요하다.","(간추림) 나무젓가락과 종이컵을 만들려면 숲의 나무를 베어야 한다.","(간추림) 일회용품은 오랫동안 썩지 않아 환경을 오염시킨다.","(간추림) 땅속에서 썩는 데 종이컵은 20년, 스티로폼 도시락은","(간추림) 500년이 걸린다고 한다."],"numbered":false,"title":"「일회용품은 이제 그만」 — 듣기 자료 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#19','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C13',3,'error','auto','영상 평가 댓글을 쓰는 방법을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X27','K6-2-u3-X21','K6-2-u3-X12']::text[],false,'{"seq":19,"concept":"K6-2-u3-C13","difficulty":3,"kind":"error","stem":"영상 평가 댓글을 쓰는 방법을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「타당하지 않은 부분은 다른 사람을 비웃는 말로 따끔하게 써 줄래.」","correct":true,"mis_target":"K6-2-u3-X27"},{"t":"친구 1 — 「여러 주장이 섞인 영상보다 주장이 뚜렷한 영상을 고를래.」","mis":"K6-2-u3-X21"},{"t":"친구 2 — 「판단 기준을 세우고 그 기준에 따라 판단할래.」","mis":"K6-2-u3-X12"}],"explanation":["주장이 뚜렷한 영상을 고르면 평가하기 쉬워요.","기준을 명확히 세우고 판단해요.","타당하지 않은 부분은 정중하게 확인을 요청해요."],"asset":{"type":"passage","lines":["• 자신이 파악한 영상의 주장이 무엇인지 쓰기","• 주장이 타당한지 쓰기","• 이유와 근거가 타당한지 까닭과 함께 쓰기","• 타당하지 않은 부분에 대해 정중하게 확인 요청하기"],"numbered":false,"title":"영상에 평가 댓글을 쓸 때의 조건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#20','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C10',3,'error','auto','「낭독의 재발견」의 강조 표현을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X15']::text[],false,'{"seq":20,"concept":"K6-2-u3-C10","difficulty":3,"kind":"error","stem":"「낭독의 재발견」의 강조 표현을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「‘입, 몸, 마음’이 굵은 글자니까 낭독의 효과는 증명된 거야.」","correct":true,"mis_target":"K6-2-u3-X17"},{"t":"친구 1 — 「굵은 글자는 낭독의 긍정적인 효과를 강조하려는 거야.」","mis":"K6-2-u3-X15"},{"t":"친구 2 — 「강조한 표현을 제목, 자료와 합치면 주장을 찾을 수 있어.」","mis":"K6-2-u3-X15"}],"explanation":["굵은 글자는 강조하는 표현이에요.","강조한 표현은 제목, 자료와 함께 주장을 찾는 데 써요.","굵은 글자가 효과를 증명하지는 못해요."],"asset":{"type":"passage","lines":["[장면] 책에 집중하지 못하는 시대","[장면] 캐나다 사람들을 대상으로 설문과 뇌파 측정 연구를 한 결과","[장면] 낭랑하게 목청을 돋우고 가락에 맞추어 책을 읽다 보면","[장면] ‘입, 몸, 마음’이라는 낱말을 굵은 글자로 강조한다."],"numbered":false,"title":"영상 「낭독의 재발견」의 장면 — 『국어』 129~130쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#21','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C8',3,'error','auto','우리 반 생각 발표회에서 근거를 준비하며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X13','K6-2-u3-X09','K6-2-u3-X25']::text[],false,'{"seq":21,"concept":"K6-2-u3-C8","difficulty":3,"kind":"error","stem":"우리 반 생각 발표회에서 근거를 준비하며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「누리 소통망에서 본 글인데 출처는 몰라도 그냥 내 생각인 것처럼 말할래.」","correct":true,"mis_target":"K6-2-u3-X13"},{"t":"친구 1 — 「조사한 자료를 쓸 때 출처를 정확히 밝힐래.」","mis":"K6-2-u3-X09"},{"t":"친구 2 — 「이유와 관련 있는 사례와 연구 결과를 찾을래.」","mis":"K6-2-u3-X25"}],"explanation":["조사한 자료를 쓸 때는 출처를 정확히 밝혀요.","근거는 이유와 관련 있는 것으로 찾아요.","남의 자료를 내 생각처럼 말하면 안 돼요."],"asset":{"type":"passage","lines":["문제 급식실에 한꺼번에 많은 학년이 몰려서 급식을 받는 데 오래 걸린다.","주장 학년별로 급식 시간을 조정하자.","이유 급식을 받는 데 오랜 시간을 기다리지 않아도 된다.","이유 식사 시간이 부족해져 건강과 학습에도 영향을 미칠 수 있다.","근거 학생 수가 많은 학교에서 급식 시간을 조정한 뒤","      식사 시간이 안정적으로 확보되었다는 사례가 있다.","근거 급식실이 혼잡하면 서둘러 식사를 하게 되어 소화 불량이나","      위장 장애가 발생할 가능성이 높다는 연구 결과가 있다."],"numbered":false,"title":"우리 반 생각 발표회 준비 예시 — 『국어』 127쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#22','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C19',3,'match','auto','「나를 성장시키는 기록법」의 장면과 그 장면이 하는 구실을 알맞게 이으세요.','{}'::text[],false,'{"seq":22,"concept":"K6-2-u3-C19","difficulty":3,"kind":"match","stem":"「나를 성장시키는 기록법」의 장면과 그 장면이 하는 구실을 알맞게 이으세요.","pairs":[{"l":"장면 1의 제목","r":"제목을 정한 까닭 살펴보기"},{"l":"장면 4의 「난중일기」","r":"영상에서 제시한 자료의 내용 파악하기"},{"l":"장면 6의 「적자! 생존」","r":"영상에서 강조하는 표현 찾기"}],"mis":"K6-2-u3-X15","explanation":["제목은 만든 사람의 관점을 담아요.","「난중일기」는 주장을 뒷받침하는 자료예요.","「적자! 생존」은 강조한 표현이에요."],"asset":{"type":"passage","lines":["1 제목 — 나를 성장시키는 기록법","2 열심히 받아 적었는데도 뒤돌아서면 기억하지 못한다.","3 정약용이 활용한 수사차록법","4 이순신의 「난중일기」 — 업무를 정리하고 작전을 세우며 생각을 정리한 기록","5 천재로 불렸던 인물들의 공통점 — 떠오르는 생각을 종이에 기록하는 능력","6 「적자! 생존」 — 잘 적는 사람이 살아남는 현상?"],"numbered":false,"title":"영상 「나를 성장시키는 기록법」의 장면 — 『국어』 131쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#23','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C1',4,'essay','teacher','「일회용품은 이제 그만」의 주장을 뒷받침하는 이유를 하나 더 생각해 쓰고, 그 이유가 타당한지 『국어』 121쪽 이유의 두 기준으로 스스로 점검해 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u3-C1","difficulty":4,"kind":"essay","stem":"「일회용품은 이제 그만」의 주장을 뒷받침하는 이유를 하나 더 생각해 쓰고, 그 이유가 타당한지 『국어』 121쪽 이유의 두 기준으로 스스로 점검해 쓰세요.","answer_guide":{"answer":"예: 더 생각한 이유 — 일회용품을 줄이면 버려지는 쓰레기의 양이 줄어 쓰레기를 처리하는 데 드는 자원도 아낄 수 있기 때문이다. 점검 — 이 이유는 일회용품 사용을 줄이자는 주장과 관련 있다. 또 쓰레기가 줄면 좋다는 것은 많은 사람이 받아들일 만한 생각이다.","scoring_points":["주장과 관련 있는 이유를 하나 더 썼는가","주장과 관련 있는지 점검했는가","많은 사람이 받아들일 만한지 점검했는가"]},"explanation":["『국어』 145쪽처럼 이유를 더 생각해 보아요.","이유는 주장과 관련 있어야 해요.","많은 사람이 받아들일 만한지도 점검해요."],"asset":{"type":"passage","lines":["(간추림) 종이컵 1톤을 만드는 데 20년생 나무 스무 그루가 필요하다.","(간추림) 우리가 편리하게 쓰던 일회용품이 지구를 병들게 하고 있다.","환경을 위해 일회용품 사용을 줄입시다.","(간추림) 일회용품을 만들려면 많은 자원이 필요하다.","(간추림) 나무젓가락과 종이컵을 만들려면 숲의 나무를 베어야 한다.","(간추림) 일회용품은 오랫동안 썩지 않아 환경을 오염시킨다.","(간추림) 땅속에서 썩는 데 종이컵은 20년, 스티로폼 도시락은","(간추림) 500년이 걸린다고 한다."],"numbered":false,"title":"「일회용품은 이제 그만」 — 듣기 자료 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#24','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C13',4,'essay','teacher','누리 소통망에서 주장하는 영상을 골라 평가 댓글을 쓰려고 할 때, 어떤 영상을 고르는 것이 좋은지와 댓글을 쓸 때 지켜야 할 온라인 공간의 예절을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u3-C13","difficulty":4,"kind":"essay","stem":"누리 소통망에서 주장하는 영상을 골라 평가 댓글을 쓰려고 할 때, 어떤 영상을 고르는 것이 좋은지와 댓글을 쓸 때 지켜야 할 온라인 공간의 예절을 쓰세요.","answer_guide":{"answer":"예: 여러 주장이 섞인 영상보다 주장이 뚜렷하게 드러난 영상을 골라야 주장, 이유, 근거가 타당한지 판단하기 쉽다. 댓글을 쓸 때에는 예의 바르고 건설적으로 비판하고, 다른 사람을 비방하거나 혐오하는 표현을 쓰지 않으며, 타당하지 않은 부분은 정중하게 확인을 요청해야 한다.","scoring_points":["주장이 뚜렷한 영상을 고르는 까닭을 썼는가","예의 바르고 건설적인 비판을 썼는가","비방·혐오 표현을 쓰지 않는다고 썼는가"]},"explanation":["주장이 뚜렷한 영상이 평가하기 좋아요.","온라인에서도 예의를 지켜요.","책임감 있는 태도로 댓글을 써요."],"asset":{"type":"passage","lines":["• 자신이 파악한 영상의 주장이 무엇인지 쓰기","• 주장이 타당한지 쓰기","• 이유와 근거가 타당한지 까닭과 함께 쓰기","• 타당하지 않은 부분에 대해 정중하게 확인 요청하기"],"numbered":false,"title":"영상에 평가 댓글을 쓸 때의 조건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u3_review_d#25','kor',6,2,'u3','','tb_g6_2_kor_u3_review_d','unit_review','K6-2-u3-C13',4,'essay','teacher','이 단원에서 배운 내용을 바탕으로, 다음에 영상을 볼 때 할 일을 차례대로 세 가지 쓰세요. 「언제」와 「무엇을」이 드러나게 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u3-C13","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 내용을 바탕으로, 다음에 영상을 볼 때 할 일을 차례대로 세 가지 쓰세요. 「언제」와 「무엇을」이 드러나게 쓰세요.","answer_guide":{"answer":"예: 첫째, 영상을 보기 전에 주제와 관련된 구체적인 검색어로 찾고 자극적인 추천어는 누르지 않겠다. 둘째, 영상을 보면서 제목, 제시한 자료, 강조한 장면이나 표현을 살펴 주장을 한 문장으로 적겠다. 셋째, 다 본 뒤에 주장, 이유, 근거가 타당한지 평가표로 판단하고, 궁금한 점은 댓글로 정중하게 묻겠다.","scoring_points":["영상 찾기·보기·보고 난 뒤의 차례가 드러났는가","주장을 파악하는 방법을 넣었는가","타당성 판단과 댓글 예절을 넣었는가"]},"explanation":["찾을 때 — 구체적인 검색어.","볼 때 — 제목·자료·강조.","보고 나서 — 타당성 판단과 정중한 댓글."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
